--

CREATE FUNCTION app.leads_force_org_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'app', 'public', 'pg_temp'
    AS $$
begin
  -- Auth context prioritaire (sécurité authed inchangée).
  -- Sans contexte (service_role), on respecte l'org_id explicite fourni.
  new.org_id := coalesce(app.current_org_id(), new.org_id);

  if new.org_id is null then
    raise exception 'missing org_id in auth context'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


