--
-- Name: _point_in_zone_ring(double precision, double precision, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._point_in_zone_ring(p_lng double precision, p_lat double precision, geo jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  ring jsonb; n int; i int; j int;
  xi float8; yi float8; xj float8; yj float8;
  inside boolean := false;
begin
  ring := geo->'coordinates'->0;
  if ring is null or jsonb_typeof(ring) <> 'array' then return false; end if;
  n := jsonb_array_length(ring);
  if n < 3 then return false; end if;
  j := n - 1;
  for i in 0..n-1 loop
    xi := (ring->i->>0)::float8; yi := (ring->i->>1)::float8;
    xj := (ring->j->>0)::float8; yj := (ring->j->>1)::float8;
    if ((yi > p_lat) <> (yj > p_lat))
       and (p_lng < (xj - xi) * (p_lat - yi) / (yj - yi) + xi) then
      inside := not inside;
    end if;
    j := i;
  end loop;
  return inside;
end $$;


