  WHERE id = p_lead_id;
END;
$$;


--
-- Name: anonymize_old_soft_deleted_clients(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonymize_old_soft_deleted_clients(p_days integer DEFAULT 180) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_cutoff timestamptz := now() - make_interval(days => p_days);
  v_count bigint := 0;
  v_cols text;
  v_sql text;
begin
  select string_agg(
    case column_name
      when 'first_name' then 'first_name=''ANONYMIZED'''
      when 'last_name'  then 'last_name='''''
      else column_name || '=null'
    end, ', ')
    into v_cols
    from information_schema.columns
   where table_schema='public' and table_name='clients'
     and column_name in ('first_name','last_name','company','email','phone',
                         'address','address_line1','address_line2','street_number','street_name',
                         'city','province','postal_code','country',
                         'latitude','longitude','place_id','notes',
                         'sms_consent_at','email_consent_at');

  v_sql := format($X$
    with updated as (
      update public.clients set %s, updated_at=now()
       where deleted_at is not null and deleted_at < %L
         and first_name is distinct from 'ANONYMIZED'
      returning id, org_id)
    insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
    select org_id, null, 'anonymize', 'client', id,
           jsonb_build_object('method','retention_softdelete_180d','cutoff', %L::timestamptz) from updated
  $X$, v_cols, v_cutoff, v_cutoff);
  execute v_sql;
  get diagnostics v_count = row_count;
  return v_count;
end $_$;


--
-- Name: apply_appointment_contract_link(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_appointment_contract_link(p_org_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
begin
  update public.automation_rules ar
  set actions = (
    select jsonb_agg(a order by ord)
    from (
      select
        case
          when e->>'type' = 'send_sms'
           and coalesce(e->'config'->>'body', '') <> ''
           and position('[contract_' in (e->'config'->>'body')) = 0
          then jsonb_set(e, '{config,body}',
                 to_jsonb((e->'config'->>'body') || E'\n[contract_line]'))
          when e->>'type' = 'send_email'
           and coalesce(e->'config'->>'body', '') <> ''
           and position('[contract_' in (e->'config'->>'body')) = 0
          then jsonb_set(e, '{config,body}',
                 to_jsonb(
                   -- Glissé à l'intérieur du <div> du gabarit quand il y en a
                   -- un, sinon simplement ajouté à la fin.
                   case
                     when (e->'config'->>'body') ~ '</div>\s*$'
                     then regexp_replace(e->'config'->>'body',
                            '</div>(\s*)$', '[contract_html]</div>\1')
                     else (e->'config'->>'body') || '[contract_html]'
                   end))
          else e
        end as a,
        ord
      from jsonb_array_elements(ar.actions) with ordinality as t(e, ord)
    ) s
  )
  where ar.preset_key = 'appointment_confirmation'
    and jsonb_typeof(ar.actions) = 'array'
    and (p_org_id is null or ar.org_id = p_org_id);
end;
$_$;


