       '<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;"><h2>Bonjour [client_first_name],</h2><p>Ça fait un mois depuis nos travaux chez vous — on espère que tout est encore impeccable!</p><p>Saviez-vous qu''on offre aussi d''autres services d''entretien? Répondez à ce courriel pour en savoir plus.</p><p>Au plaisir,<br/>[company_name]</p></div>'),
      ('reengagement_90d',
       'Bonjour [client_first_name], déjà 3 mois! Un entretien serait peut-être dû. — [company_name] Répondez STOP pour vous désabonner.',
       '[company_name] — Déjà 3 mois!',
       '<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;"><h2>Bonjour [client_first_name],</h2><p>Ça fait trois mois depuis notre dernier passage — un entretien serait peut-être dû.</p><p>Répondez à ce courriel et on vous trouve une place à l''horaire.</p><p>Au plaisir,<br/>[company_name]</p></div>'),
      ('seasonal_reminder_6m',
       'La saison avance! [company_name] peut préparer votre propriété. Répondez à ce message pour un devis. Répondez STOP pour vous désabonner.',
       '[company_name] — La saison s''en vient',
       '<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;"><h2>Bonjour [client_first_name],</h2><p>La saison avance — c''est le bon moment pour préparer votre propriété.</p><p>Répondez à ce courriel pour une soumission rapide et sans engagement.</p><p>À bientôt,<br/>[company_name]</p></div>')
  ),
  patched as (
    select r.id,
           (select jsonb_agg(
              case
                when elem->>'type' = 'send_sms' and fr.sms is not null
                  then jsonb_set(elem, '{config,body}', to_jsonb(fr.sms))
                when elem->>'type' = 'send_email' and fr.email_body is not null
                  then jsonb_set(jsonb_set(elem, '{config,body}', to_jsonb(fr.email_body)),
                                 '{config,subject}', to_jsonb(fr.email_subject))
                else elem
              end order by ord)
            from jsonb_array_elements(r.actions) with ordinality as t(elem, ord)) as new_actions
    from public.automation_rules r
    join fr on fr.preset_key = r.preset_key
    where r.org_id = p_org_id
  )
  update public.automation_rules r
  set actions = p.new_actions,
      updated_at = now()
  from patched p
  where r.id = p.id
    and p.new_actions is not null;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: apply_invoice_payment(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_invoice_payment(p_invoice_id uuid, p_org_id uuid, p_amount_cents integer) RETURNS TABLE(id uuid, paid_cents integer, balance_cents integer, status text, total_cents integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.invoices
  SET
    paid_cents = LEAST(total_cents, COALESCE(paid_cents, 0) + p_amount_cents),
    balance_cents = GREATEST(0, total_cents - LEAST(total_cents, COALESCE(paid_cents, 0) + p_amount_cents)),
    status = CASE
      WHEN total_cents - LEAST(total_cents, COALESCE(paid_cents, 0) + p_amount_cents) <= 0 THEN 'paid'
      ELSE 'partial'
    END,
    paid_at = CASE
      WHEN total_cents - LEAST(total_cents, COALESCE(paid_cents, 0) + p_amount_cents) <= 0 THEN now()
      ELSE paid_at
    END,
    updated_at = now()
  WHERE id = p_invoice_id AND org_id = p_org_id
  RETURNING id, paid_cents, balance_cents, status, total_cents;
$$;


--
-- Name: archive_client(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_client(p_org_id uuid, p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_client integer := 0;
  v_jobs integer := 0;
  v_tasks integer := 0;
  v_automations integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING errcode = '42501';
  END IF;
  IF NOT public.has_org_admin_role(v_uid, p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can archive clients' USING errcode = '42501';
  END IF;

  UPDATE public.clients
  SET deleted_at = v_now, updated_at = v_now
  WHERE id = p_client_id AND org_id = p_org_id AND deleted_at IS NULL;
  GET DIAGNOSTICS v_client = ROW_COUNT;

  UPDATE public.jobs
  SET deleted_at = v_now, updated_at = v_now
  WHERE client_id = p_client_id AND org_id = p_org_id AND deleted_at IS NULL;
  GET DIAGNOSTICS v_jobs = ROW_COUNT;

  UPDATE public.pipeline_deals
  SET deleted_at = v_now, updated_at = v_now
  WHERE client_id = p_client_id AND org_id = p_org_id AND deleted_at IS NULL;

  UPDATE public.tasks
  SET status = 'cancelled'
  WHERE org_id = p_org_id
    AND entity_type = 'client'
    AND entity_id = p_client_id
    AND status IN ('pending', 'in_progress');
  GET DIAGNOSTICS v_tasks = ROW_COUNT;

  UPDATE public.automation_scheduled_tasks
  SET status = 'cancelled', completed_at = v_now
  WHERE org_id = p_org_id
    AND entity_type = 'client'
    AND entity_id = p_client_id
    AND status = 'pending';
  GET DIAGNOSTICS v_automations = ROW_COUNT;

  RETURN jsonb_build_object(
    'client', v_client,
    'jobs', v_jobs,
    'leads', 0,
    'tasks', v_tasks,
    'automations', v_automations
  );
END;
$$;


--
-- Name: archive_record(uuid, text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_record(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_reason text DEFAULT NULL::text, p_hard_delete boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_row jsonb;
  v_result jsonb;
BEGIN
  IF NOT has_org_admin_role(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Admin role required to archive records';
  END IF;

  -- Snapshot the entity
  EXECUTE format(
    'SELECT to_jsonb(t.*) FROM %I t WHERE t.id = $1 AND t.org_id = $2',
    p_entity_type || 's'  -- table name = entity_type + 's'
  ) INTO v_row USING p_entity_id, p_org_id;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'Record not found: % %', p_entity_type, p_entity_id;
  END IF;

  -- Store in archive
  INSERT INTO archived_records (org_id, entity_type, entity_id, entity_data, archived_by, reason)
  VALUES (p_org_id, p_entity_type, p_entity_id, v_row, auth.uid(), p_reason)
  ON CONFLICT (org_id, entity_type, entity_id) DO UPDATE
    SET entity_data = EXCLUDED.entity_data, archived_by = EXCLUDED.archived_by, archived_at = now(), reason = EXCLUDED.reason;

  IF p_hard_delete THEN
    EXECUTE format('DELETE FROM %I WHERE id = $1 AND org_id = $2', p_entity_type || 's')
      USING p_entity_id, p_org_id;
    v_result := jsonb_build_object('archived', true, 'hard_deleted', true);
  ELSE
    -- Soft delete only
    EXECUTE format(
      'UPDATE %I SET deleted_at = now(), deleted_by = $3 WHERE id = $1 AND org_id = $2 AND deleted_at IS NULL',
      p_entity_type || 's'
    ) USING p_entity_id, p_org_id, auth.uid();
    v_result := jsonb_build_object('archived', true, 'hard_deleted', false);
  END IF;

  RETURN v_result;
END;
$_$;


--
-- Name: assign_client_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_client_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org  uuid := coalesce(new.org_id, public.current_org_id());
  v_next bigint;
begin
  if v_org is null then
    return new;
  end if;

  if new.client_number is not null and btrim(new.client_number) <> '' then
    if new.client_number ~ '^\s*\d+$' then
      insert into public.org_client_counters (org_id, last_number)
      values (v_org, btrim(new.client_number)::bigint)
      on conflict (org_id) do update
        set last_number = greatest(public.org_client_counters.last_number, excluded.last_number),
            updated_at  = now();
    end if;
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_org::text || ':client', 0));
  v_next := public.org_smallest_free_number(v_org, 'client');

  insert into public.org_client_counters (org_id, last_number)
  values (v_org, v_next)
  on conflict (org_id) do update
    set last_number = greatest(public.org_client_counters.last_number, excluded.last_number),
        updated_at  = now();

  new.client_number := v_next::text;
  return new;
end;
$_$;


