--
-- Name: assign_org_company_group(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_org_company_group() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.company_group_id is null then
    select o.company_group_id into new.company_group_id
    from public.orgs o
    where o.created_by = new.created_by
      and new.created_by is not null
      and o.company_group_id is not null
    limit 1;

    if new.company_group_id is null then
      new.company_group_id := gen_random_uuid();
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: audit_events_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_events_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Purge par retention : SET LOCAL app.audit_maintenance = 'on' dans la
  -- transaction. SET LOCAL est obligatoire (N7.3 : en mode pooling
  -- transaction, un SET de session fuit vers la requete suivante).
  if coalesce(current_setting('app.audit_maintenance', true), 'off') = 'on' then
    return coalesce(new, old);
  end if;

  raise exception
    'audit_events est append-only : % interdit.', tg_op
    using errcode = '42501';
end $$;


--
-- Name: FUNCTION audit_events_append_only(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.audit_events_append_only() IS 'N4.7 : rend audit_events append-only. Purge par retention : SET LOCAL app.audit_maintenance = ''on'' dans la transaction.';


--
-- Name: audit_log_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_log_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_action text;
  v_old jsonb := NULL;
  v_new jsonb := NULL;
  v_org_id uuid;
  v_entity_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_new := to_jsonb(NEW);
    v_org_id := NEW.org_id;
    v_entity_id := NEW.id;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Detect soft delete
    IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
      v_action := 'soft_delete';
    ELSE
      v_action := 'update';
    END IF;
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    v_org_id := NEW.org_id;
    v_entity_id := NEW.id;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'hard_delete';
    v_old := to_jsonb(OLD);
    v_org_id := OLD.org_id;
    v_entity_id := OLD.id;
  END IF;

  INSERT INTO audit_events (org_id, actor_id, action, entity_type, entity_id, event_type, old_values, new_values, metadata)
  VALUES (
    v_org_id,
    auth.uid(),
    v_action,
    TG_TABLE_NAME,
    v_entity_id,
    TG_TABLE_NAME || '.' || v_action,
    v_old,
    v_new,
    jsonb_build_object('trigger', TG_NAME, 'op', TG_OP)
  );

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


