--
-- Name: auto_pipeline_deal_from_quote_impl(public.quotes); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_pipeline_deal_from_quote_impl(new public.quotes) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_id uuid;
  v_stage text;
  v_value_cents integer;
BEGIN
  IF NEW.salesperson_id IS NULL THEN RETURN; END IF;
  v_stage := CASE
    WHEN NEW.status = 'approved' THEN 'closed_won'
    WHEN NEW.status IN ('awaiting_response', 'changes_requested') THEN 'quote_sent'
    WHEN NEW.status = 'declined' THEN 'closed_lost'
    ELSE NULL
  END;
  IF v_stage IS NULL THEN RETURN; END IF;
  v_value_cents := COALESCE(NEW.total_cents, 0);

  SELECT id INTO v_existing_id FROM pipeline_deals
   WHERE org_id = NEW.org_id AND quote_id = NEW.id AND deleted_at IS NULL LIMIT 1;

  IF v_existing_id IS NULL AND NEW.lead_id IS NOT NULL THEN
    SELECT id INTO v_existing_id FROM pipeline_deals
     WHERE org_id = NEW.org_id AND lead_id = NEW.lead_id AND deleted_at IS NULL
     ORDER BY created_at ASC LIMIT 1;
  END IF;

  IF v_existing_id IS NOT NULL THEN
    UPDATE pipeline_deals
       SET quote_id = COALESCE(quote_id, NEW.id),
           rep_id = COALESCE(rep_id, NEW.salesperson_id),
           stage = v_stage,
           value_cents = GREATEST(value_cents, v_value_cents),
           value = GREATEST(value, v_value_cents / 100.0),
           won_at = CASE WHEN v_stage = 'closed_won' AND won_at IS NULL THEN now() ELSE won_at END,
           lost_at = CASE WHEN v_stage = 'closed_lost' AND lost_at IS NULL THEN now() ELSE lost_at END,
           updated_at = now()
     WHERE id = v_existing_id;
  END IF;
END;
$$;


--
-- Name: auto_pipeline_deal_from_quote_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_pipeline_deal_from_quote_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing_id uuid;
  v_stage text;
  v_value_cents integer;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status
     AND NEW.salesperson_id IS NOT DISTINCT FROM OLD.salesperson_id THEN
    RETURN NEW;
  END IF;
  IF NEW.salesperson_id IS NULL THEN RETURN NEW; END IF;
  v_stage := CASE
    WHEN NEW.status IN ('accepted', 'signed', 'approved') THEN 'won'
    WHEN NEW.status IN ('sent', 'viewed') THEN 'proposal'
    WHEN NEW.status IN ('rejected', 'declined') THEN 'lost'
    ELSE NULL
  END;
  IF v_stage IS NULL THEN RETURN NEW; END IF;
  v_value_cents := COALESCE(NEW.total_cents, 0);

  SELECT id INTO v_existing_id FROM pipeline_deals
    WHERE org_id = NEW.org_id AND quote_id = NEW.id AND deleted_at IS NULL LIMIT 1;

  IF v_existing_id IS NULL AND NEW.lead_id IS NOT NULL THEN
    SELECT id INTO v_existing_id FROM pipeline_deals
      WHERE org_id = NEW.org_id AND lead_id = NEW.lead_id AND deleted_at IS NULL
      ORDER BY created_at ASC LIMIT 1;
  END IF;

  IF v_existing_id IS NOT NULL THEN
    UPDATE pipeline_deals
      SET quote_id = COALESCE(quote_id, NEW.id),
          rep_id = COALESCE(rep_id, NEW.salesperson_id),
          stage = v_stage,
          value_cents = GREATEST(value_cents, v_value_cents),
          value = GREATEST(value, v_value_cents / 100.0),
          won_at = CASE WHEN v_stage = 'won' AND won_at IS NULL THEN now() ELSE won_at END,
          lost_at = CASE WHEN v_stage = 'lost' AND lost_at IS NULL THEN now() ELSE lost_at END,
          updated_at = now()
      WHERE id = v_existing_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: automation_invoice_overdue_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_invoice_overdue_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('sent', 'partial')
    AND NEW.due_date < CURRENT_DATE
    AND (OLD.due_date IS NULL OR OLD.due_date >= CURRENT_DATE OR OLD.status != NEW.status)
    AND NEW.deleted_at IS NULL
  THEN
    INSERT INTO notifications (org_id, type, ref_id, title, body, message, entity_type, entity_id)
    VALUES (
      NEW.org_id, 'invoice_overdue', NEW.id,
      'Invoice overdue: ' || COALESCE(NEW.invoice_number, ''),
      'Invoice ' || COALESCE(NEW.invoice_number, '') || ' is past due.',
      'Invoice ' || COALESCE(NEW.invoice_number, '') || ' is past due.',
      'invoice', NEW.id
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: automation_job_completed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_job_completed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule record;
  v_start_ms bigint;
  v_invoice_result jsonb;
BEGIN
  -- Only fire on status change to 'completed'
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF NEW.status != 'completed' THEN RETURN NEW; END IF;
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;

  -- Set completed_at if not set
  IF NEW.completed_at IS NULL THEN
    NEW.completed_at := now() AT TIME ZONE 'America/Toronto';
  END IF;

  -- Check for active automation rules
  FOR v_rule IN
    SELECT * FROM automation_rules
    WHERE org_id = NEW.org_id
      AND entity_type = 'job'
      AND trigger_on = 'status_change'
      AND is_active = true
      AND deleted_at IS NULL
      AND (
        conditions->>'to_status' IS NULL
        OR conditions->>'to_status' = 'completed'
      )
    ORDER BY priority
  LOOP
    v_start_ms := extract(epoch from clock_timestamp()) * 1000;

    BEGIN
      -- Execute each action
      IF v_rule.actions @> '[{"type":"create_invoice"}]'::jsonb THEN
        SELECT create_invoice_from_job(NEW.org_id, NEW.id) INTO v_invoice_result;

        INSERT INTO automation_executions (org_id, rule_id, entity_type, entity_id, trigger_event, actions_run, status, duration_ms)
        VALUES (
          NEW.org_id, v_rule.id, 'job', NEW.id, 'status_change:completed',
          jsonb_build_array(jsonb_build_object('type', 'create_invoice', 'result', v_invoice_result)),
          'success',
          (extract(epoch from clock_timestamp()) * 1000 - v_start_ms)::int
        );
      END IF;

      IF v_rule.actions @> '[{"type":"send_notification"}]'::jsonb THEN
        INSERT INTO notifications (org_id, type, ref_id, title, body)
        VALUES (
          NEW.org_id, 'job_completed', NEW.id,
          'Job completed: ' || COALESCE(NEW.title, NEW.job_number),
          'Job #' || COALESCE(NEW.job_number, '') || ' has been marked as completed.'
        );

        INSERT INTO automation_executions (org_id, rule_id, entity_type, entity_id, trigger_event, actions_run, status, duration_ms)
        VALUES (
          NEW.org_id, v_rule.id, 'job', NEW.id, 'status_change:completed',
          '[{"type":"send_notification"}]'::jsonb,
          'success',
          (extract(epoch from clock_timestamp()) * 1000 - v_start_ms)::int
        );
      END IF;

    EXCEPTION WHEN OTHERS THEN
      INSERT INTO automation_executions (org_id, rule_id, entity_type, entity_id, trigger_event, actions_run, status, error_message, duration_ms)
      VALUES (
        NEW.org_id, v_rule.id, 'job', NEW.id, 'status_change:completed',
        v_rule.actions, 'error', SQLERRM,
        (extract(epoch from clock_timestamp()) * 1000 - v_start_ms)::int
      );
    END;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: automation_lead_stage_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_lead_stage_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.stage IS DISTINCT FROM NEW.stage AND NEW.deleted_at IS NULL THEN
    INSERT INTO notifications (org_id, type, ref_id, title, body, metadata)
    VALUES (
      NEW.org_id, 'lead_stage_change', NEW.id,
      'Lead stage: ' || COALESCE(NEW.first_name, '') || ' ' || COALESCE(NEW.last_name, ''),
      'Stage changed from ' || COALESCE(OLD.stage, 'none') || ' to ' || COALESCE(NEW.stage, 'none'),
      jsonb_build_object('from_stage', OLD.stage, 'to_stage', NEW.stage)
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: batch_restore(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_restore(p_org_id uuid, p_entity_type text, p_entity_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_count int;
BEGIN
  IF NOT has_org_admin_role(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Admin role required';
  END IF;

  EXECUTE format(
    'UPDATE %I SET deleted_at = NULL, deleted_by = NULL WHERE org_id = $1 AND id = ANY($2)',
    p_entity_type || 's'
  ) USING p_org_id, p_entity_ids;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object('restored_count', v_count);
END;
$_$;


--
-- Name: batch_soft_delete(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_soft_delete(p_org_id uuid, p_entity_type text, p_entity_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_count int;
BEGIN
  IF NOT has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  EXECUTE format(
    'UPDATE %I SET deleted_at = now(), deleted_by = $3 WHERE org_id = $1 AND id = ANY($2) AND deleted_at IS NULL',
    p_entity_type || 's'
  ) USING p_org_id, p_entity_ids, auth.uid();

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object('deleted_count', v_count);
END;
$_$;


--
-- Name: batch_soft_delete_clients(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_soft_delete_clients(p_org_id uuid, p_client_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int := 0;
  v_now timestamptz := now();
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.has_org_admin_role(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can archive clients' USING errcode = '42501';
  END IF;

  UPDATE clients
  SET deleted_at = v_now, updated_at = v_now
  WHERE id = ANY(p_client_ids)
    AND org_id = p_org_id
    AND deleted_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Also soft-delete related jobs
  UPDATE jobs
  SET deleted_at = v_now, updated_at = v_now
  WHERE client_id = ANY(p_client_ids)
    AND org_id = p_org_id
    AND deleted_at IS NULL;

  RETURN jsonb_build_object('archived_clients', v_count);
END;
$$;


--
-- Name: current_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_org_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user uuid;
  v_header_org text;
  v_claim_org text;
  v_org uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    return null;
  end if;

  -- 1. Bureau actif envoyé par le navigateur (en-tête x-lume-org), s'il en est membre.
  begin
    v_header_org := nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-lume-org';
    if v_header_org is not null and v_header_org ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_org := v_header_org::uuid;
      if public.has_org_membership(v_user, v_org) then
        return v_org;
      end if;
    end if;
  exception when others then
    null;
  end;

  -- 2. Claim JWT (déploiements qui le posent).
  v_claim_org := nullif(current_setting('request.jwt.claim.org_id', true), '');
  if v_claim_org is not null then
    begin
      v_org := v_claim_org::uuid;
      if public.has_org_membership(v_user, v_org) then
        return v_org;
      end if;
    exception when others then
      null;
    end;
  end if;

  -- 3. Repli : plus ancienne adhésion ACTIVE (compte à un seul bureau = toujours juste).
  if to_regclass('public.memberships') is not null then
    select m.org_id
      into v_org
      from public.memberships m
     where m.user_id = v_user
       and coalesce(m.status, 'active') = 'active'
     order by m.created_at asc, m.org_id asc
     limit 1;
    if v_org is not null then
      return v_org;
    end if;
  end if;

  if to_regclass('public.org_members') is not null then
    select m.org_id
      into v_org
      from public.org_members m
     where m.user_id = v_user
     order by m.org_id asc
     limit 1;
    if v_org is not null then
      return v_org;
    end if;
  end if;

  return v_user;
end;
$_$;


--
-- Name: FUNCTION current_org_id(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.current_org_id() IS 'Bureau courant : en-tête x-lume-org (bureau actif du navigateur, adhésion vérifiée) → claim JWT org_id → plus ancienne adhésion → auth.uid().';


