-- Name: clients_before_insert_set_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clients_before_insert_set_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.org_id is null then
    select o into new.org_id
    from public.current_org_ids() o
    limit 1;
  end if;

  if new.org_id is null then
    raise exception 'org_id missing: user has no org membership';
  end if;

  return new;
end;
$$;


--
-- Name: clients_portal_token_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clients_portal_token_hash() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.portal_token is null then
    new.portal_token_hash := null;
  elsif tg_op = 'INSERT'
     or new.portal_token_hash is null
     or new.portal_token is distinct from old.portal_token then
    new.portal_token_hash := encode(sha256(convert_to(new.portal_token, 'UTF8')), 'hex');
  end if;
  return new;
end $$;


