--
-- Name: convert_currency(integer, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_currency(p_amount_cents integer, p_from_currency text, p_to_currency text, p_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rate numeric;
BEGIN
  IF p_from_currency = p_to_currency THEN
    RETURN p_amount_cents;
  END IF;

  SELECT rate INTO v_rate
  FROM currency_rates
  WHERE base_currency = p_from_currency
    AND target_currency = p_to_currency
    AND valid_from <= p_date
    AND (valid_to IS NULL OR valid_to >= p_date)
  ORDER BY valid_from DESC
  LIMIT 1;

  IF v_rate IS NULL THEN
    -- Try reverse
    SELECT 1.0 / rate INTO v_rate
    FROM currency_rates
    WHERE base_currency = p_to_currency
      AND target_currency = p_from_currency
      AND valid_from <= p_date
      AND (valid_to IS NULL OR valid_to >= p_date)
    ORDER BY valid_from DESC
    LIMIT 1;
  END IF;

  IF v_rate IS NULL THEN
    RAISE EXCEPTION 'No exchange rate found for % → % on %', p_from_currency, p_to_currency, p_date;
  END IF;

  RETURN ROUND(p_amount_cents * v_rate)::int;
END;
$$;


--
-- Name: create_client_with_duplicate_handling(uuid, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_client_with_duplicate_handling(p_org_id uuid, p_mode text, p_payload jsonb, p_merge_duplicates boolean DEFAULT true) RETURNS public.clients
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_mode text := lower(coalesce(trim(p_mode), 'add'));
  v_first_name text := nullif(trim(coalesce(p_payload->>'first_name', '')), '');
  v_last_name text := nullif(trim(coalesce(p_payload->>'last_name', '')), '');
  v_company text := nullif(trim(coalesce(p_payload->>'company', '')), '');
  v_email text := nullif(trim(coalesce(p_payload->>'email', '')), '');
  v_phone text := nullif(trim(coalesce(p_payload->>'phone', '')), '');
  v_address text := nullif(trim(coalesce(p_payload->>'address', '')), '');
  v_status text := coalesce(nullif(trim(p_payload->>'status'), ''), 'active');
  v_display_as_company boolean := coalesce((p_payload->>'display_as_company')::boolean, false);
  v_street_number text := nullif(trim(coalesce(p_payload->>'street_number', '')), '');
  v_street_name text := nullif(trim(coalesce(p_payload->>'street_name', '')), '');
  v_city text := nullif(trim(coalesce(p_payload->>'city', '')), '');
  v_province text := nullif(trim(coalesce(p_payload->>'province', '')), '');
  v_postal_code text := nullif(trim(coalesce(p_payload->>'postal_code', '')), '');
  v_country text := nullif(trim(coalesce(p_payload->>'country', '')), '');
  v_latitude numeric := null;
  v_longitude numeric := null;
  v_place_id text := nullif(trim(coalesce(p_payload->>'place_id', '')), '');
  v_billing_same boolean := coalesce((p_payload->>'billing_same_as_service')::boolean, true);
  v_billing_address text := nullif(trim(coalesce(p_payload->>'billing_address', '')), '');
  v_phones jsonb := case when jsonb_typeof(p_payload->'phones') = 'array' then p_payload->'phones' else '[]'::jsonb end;
  v_email_label text := coalesce(nullif(trim(coalesce(p_payload->>'email_label', '')), ''), 'main');
  v_lead_source text := nullif(trim(coalesce(p_payload->>'lead_source', '')), '');
  v_tax_ids uuid[] := null;
  v_client_number text := nullif(trim(coalesce(p_payload->>'client_number', '')), '');
  v_next_number bigint;
  v_primary public.clients%rowtype;
  v_dup record;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null then
    raise exception 'p_org_id is required' using errcode = '22023';
  end if;

  if not public.has_org_membership(v_uid, p_org_id) then
    raise exception 'Not a member of this org' using errcode = '42501';
  end if;

  begin
    v_latitude := (p_payload->>'latitude')::numeric;
  exception when others then v_latitude := null; end;
  begin
    v_longitude := (p_payload->>'longitude')::numeric;
  exception when others then v_longitude := null; end;
  begin
    if jsonb_typeof(p_payload->'tax_ids') = 'array' then
      select array(select value::uuid from jsonb_array_elements_text(p_payload->'tax_ids'))
        into v_tax_ids;
    end if;
  exception when others then v_tax_ids := null; end;

  if v_client_number is not null then
    if v_client_number !~ '^\d+$' then
      raise exception 'Invalid client number "%"', v_client_number using errcode = '22023';
    end if;

    select greatest(
      coalesce((select c.last_number from public.org_client_counters c where c.org_id = p_org_id), 0),
      coalesce((select max(nullif(regexp_replace(cl.client_number, '\D', '', 'g'), '')::bigint)
                from public.clients cl
                where cl.org_id = p_org_id and cl.client_number ~ '\d'), 0)
    ) + 1 into v_next_number;

    if v_client_number::bigint > v_next_number then
      raise exception 'Client number % does not exist yet (next available is %)',
        v_client_number, v_next_number using errcode = '22023';
    end if;

    if exists (
      select 1 from public.clients c
      where c.org_id = p_org_id
        and c.deleted_at is null
        and c.client_number = v_client_number
    ) then
      raise exception 'Client number % is already in use', v_client_number using errcode = '23505';
    end if;
  end if;

  if v_first_name is null then
    v_first_name := 'Unknown';
  end if;
  if v_last_name is null then
    v_last_name := 'Client';
  end if;

  if v_mode not in ('add', 'replace') then
    raise exception 'Invalid mode: %', v_mode using errcode = '22023';
  end if;

  if v_mode = 'add' then
    insert into public.clients (
      org_id, first_name, last_name, company, email, phone, address, status, display_as_company,
      street_number, street_name, city, province, postal_code, country, latitude, longitude, place_id,
      billing_same_as_service, billing_address, phones, email_label, lead_source, tax_ids, client_number,
      created_by, updated_at
    )
    values (
      p_org_id, v_first_name, v_last_name, v_company, v_email, v_phone, v_address, v_status, v_display_as_company,
      v_street_number, v_street_name, v_city, v_province, v_postal_code, v_country, v_latitude, v_longitude, v_place_id,
      v_billing_same, v_billing_address, v_phones, v_email_label, v_lead_source, v_tax_ids, v_client_number,
      v_uid, now()
    )
    returning * into v_primary;

    return v_primary;
  end if;

  if v_email is null then
    raise exception 'replace mode requires email' using errcode = '22023';
  end if;

  select * into v_primary
  from public.clients c
  where c.org_id = p_org_id
    and c.deleted_at is null
    and lower(coalesce(c.email, '')) = lower(v_email)
  order by c.created_at asc, c.id asc
  limit 1
  for update;

  if v_primary.id is null then
    insert into public.clients (
      org_id, first_name, last_name, company, email, phone, address, status, display_as_company,
      street_number, street_name, city, province, postal_code, country, latitude, longitude, place_id,
      billing_same_as_service, billing_address, phones, email_label, lead_source, tax_ids, client_number,
      created_by, updated_at
    )
    values (
      p_org_id, v_first_name, v_last_name, v_company, v_email, v_phone, v_address, v_status, v_display_as_company,
      v_street_number, v_street_name, v_city, v_province, v_postal_code, v_country, v_latitude, v_longitude, v_place_id,
      v_billing_same, v_billing_address, v_phones, v_email_label, v_lead_source, v_tax_ids, v_client_number,
      v_uid, now()
    )
    returning * into v_primary;

    return v_primary;
  end if;

  update public.clients
  set
    first_name = v_first_name,
    last_name = v_last_name,
    company = v_company,
    email = v_email,
    phone = v_phone,
    address = v_address,
    status = v_status,
    display_as_company = v_display_as_company,
    street_number = v_street_number,
    street_name = v_street_name,
    city = v_city,
    province = v_province,
    postal_code = v_postal_code,
    country = v_country,
    latitude = v_latitude,
    longitude = v_longitude,
    place_id = v_place_id,
    billing_same_as_service = v_billing_same,
    billing_address = v_billing_address,
    phones = v_phones,
    email_label = v_email_label,
    lead_source = v_lead_source,
    tax_ids = v_tax_ids,
    updated_at = now()
  where id = v_primary.id
  returning * into v_primary;

  if p_merge_duplicates then
    for v_dup in
      select c.id
      from public.clients c
      where c.org_id = p_org_id
        and c.deleted_at is null
        and lower(coalesce(c.email, '')) = lower(v_email)
        and c.id <> v_primary.id
      order by c.created_at asc, c.id asc
    loop
      update public.jobs
      set client_id = v_primary.id, updated_at = now()
      where org_id = p_org_id and client_id = v_dup.id;

      if to_regclass('public.invoices') is not null then
        begin
          execute 'update public.invoices set client_id = $1, updated_at = now() where org_id = $2 and client_id = $3'
          using v_primary.id, p_org_id, v_dup.id;
        exception when others then
          null;
        end;
      end if;

      if to_regclass('public.payments') is not null then
        begin
          execute 'update public.payments set client_id = $1, updated_at = now() where org_id = $2 and client_id = $3'
          using v_primary.id, p_org_id, v_dup.id;
        exception when others then
          null;
        end;
      end if;

      update public.pipeline_deals
      set client_id = v_primary.id,
          updated_at = now()
      where org_id = p_org_id
        and client_id = v_dup.id;

      -- (retiré 2026-08-02) update public.leads : la table leads a été supprimée
      -- (modèle migré vers pipeline_deals). Ces UPDATE faisaient échouer la fusion
      -- de doublons avec 42P01. Le repointage des deals est fait ci-dessus.

      delete from public.clients
      where org_id = p_org_id
        and id = v_dup.id;
    end loop;
  end if;

  return v_primary;
end;
$_$;


--
-- Name: create_field_pin_for_client_row(public.clients); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_field_pin_for_client_row(c public.clients) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_address    text;
  v_addr_norm  text;
  v_house_id   uuid;
  v_user_id    uuid;
  v_pin_status text;
  v_pin_color  text;
  v_metadata   jsonb;
BEGIN
  IF c.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;

  v_address := nullif(btrim(coalesce(c.address, '')), '');
  IF v_address IS NULL THEN
    RETURN NULL;
  END IF;
  v_addr_norm := lower(v_address);

  -- Already linked to a house? Just make sure the pin row exists.
  SELECT fhp.id INTO v_house_id
  FROM public.field_house_profiles fhp
  WHERE fhp.org_id = c.org_id
    AND fhp.deleted_at IS NULL
    AND (fhp.client_id = c.id OR fhp.lead_id = c.id)
  LIMIT 1;

  -- Même mapping que sync_field_pin_from_client (20260746000000) :
  -- job assignée (active) → Vendu ; lead → Lead ; sinon unknown.
  IF c.status = 'active' THEN
    v_pin_status := 'sale';
  ELSIF c.status = 'lead' THEN
    v_pin_status := 'lead';
  ELSE
    v_pin_status := 'unknown';
  END IF;

  v_pin_color := CASE v_pin_status
    WHEN 'sale' THEN '#22c55e'
    WHEN 'lead' THEN '#A855F7'
    ELSE '#6b7280'
  END;

  -- field_pins.user_id is NOT NULL: creator, else org owner, else any member
  SELECT m.user_id INTO v_user_id
  FROM public.memberships m
  WHERE m.org_id = c.org_id
  ORDER BY CASE m.role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END
  LIMIT 1;
  v_user_id := coalesce(c.created_by, v_user_id);

  IF v_house_id IS NULL THEN
    v_metadata := jsonb_strip_nulls(jsonb_build_object(
      'source', 'crm_client',
      'client_id', c.id,
      'customer_name', nullif(btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')), ''),
      'customer_phone', c.phone,
      'customer_email', c.email
    ));
    IF c.latitude IS NULL OR c.longitude IS NULL THEN
      v_metadata := v_metadata || jsonb_build_object('geocode_status', 'pending');
    END IF;

    -- Find-or-create by normalized address (unique per org). When another
    -- client already owns the house at this address, keep its link — same
    -- merge semantics as the server-side upsertLeadPinForClient.
    INSERT INTO public.field_house_profiles AS fhp (
      org_id, address, address_normalized, lat, lng,
      current_status, client_id, assigned_user_id,
      visit_count, last_activity_at, metadata
    ) VALUES (
      c.org_id, v_address, v_addr_norm, c.latitude, c.longitude,
      v_pin_status, c.id, v_user_id,
      0, now(), v_metadata
    )
    ON CONFLICT (org_id, address_normalized) WHERE deleted_at IS NULL
    DO UPDATE SET
      client_id        = coalesce(fhp.client_id, EXCLUDED.client_id),
      lat              = coalesce(fhp.lat, EXCLUDED.lat),
      lng              = coalesce(fhp.lng, EXCLUDED.lng),
      last_activity_at = now(),
      updated_at       = now()
    RETURNING fhp.id INTO v_house_id;
  END IF;

  IF v_house_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Pin (UNIQUE (org_id, house_id)); never repaint an existing D2D pin here —
  -- status changes are the job of trg_clients_sync_field_pin.
  IF v_user_id IS NOT NULL THEN
    INSERT INTO public.field_pins (org_id, house_id, user_id, status, pin_color)
    VALUES (c.org_id, v_house_id, v_user_id, v_pin_status, v_pin_color)
    ON CONFLICT (org_id, house_id) DO NOTHING;
  END IF;

  INSERT INTO public.field_pin_entity_links (org_id, house_id, entity_type, entity_id)
  VALUES (c.org_id, v_house_id, 'client', c.id)
  ON CONFLICT (org_id, house_id, entity_type, entity_id) DO NOTHING;

  RETURN v_house_id;
END;
$$;


--
-- Name: create_incident(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_incident(p_title text, p_type text, p_severity text, p_description text DEFAULT NULL::text, p_detection text DEFAULT 'manual'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid;
  v_id  uuid;
begin
  v_org := (select org_id from public.memberships where user_id = auth.uid() limit 1);
  if v_org is null then raise exception 'No organization context'; end if;
  if not public.has_org_admin_role(auth.uid(), v_org) then
    raise exception 'Only org admin/owner can declare incidents';
  end if;

  insert into public.security_incidents(
    org_id, incident_type, severity, status, title, description,
    detected_by, detection_method
  ) values (
    v_org, p_type, coalesce(p_severity,'low'), 'detected', p_title, p_description,
    auth.uid(), p_detection
  ) returning id into v_id;

  insert into public.incident_timeline(incident_id, actor_id, event_type, payload)
  values (v_id, auth.uid(), 'status_change', jsonb_build_object('to','detected','via','create_incident'));

  insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
  values (v_org, auth.uid(), 'incident_declared', 'security_incident', v_id,
    jsonb_build_object('type', p_type, 'severity', p_severity));

  return v_id;
end $$;


--
-- Name: create_invoice_from_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_job(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return public.create_invoice_from_job(p_org_id, p_job_id, false);
end;
$$;


--
-- Name: create_invoice_from_job(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_job(p_org_id uuid, p_job_id uuid, p_send_now boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_job record;
  v_existing record;
  v_invoice_id uuid;
  v_invoice_status text;
  v_invoice_number text;
  v_due_date date := (current_date + interval '14 days')::date;
  v_subtotal integer := 0;
  v_line_count integer := 0;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null or p_job_id is null then
    raise exception 'p_org_id and p_job_id are required' using errcode = '22023';
  end if;

  if not public.has_org_membership(v_uid, p_org_id) then
    raise exception 'Not a member of this organization' using errcode = '42501';
  end if;

  if not public.has_org_admin_role(v_uid, p_org_id) then
    raise exception 'Only owner/admin can create invoices from jobs' using errcode = '42501';
  end if;

  select j.id, j.org_id, j.client_id, j.title, j.currency, j.total_cents, j.total_amount, j.deleted_at
    into v_job
  from public.jobs j
  where j.id = p_job_id
    and j.org_id = p_org_id
  limit 1;

  if not found or v_job.deleted_at is not null then
    raise exception 'Job not found' using errcode = 'P0002';
  end if;

  if v_job.client_id is null then
    raise exception 'Job must be linked to a client before invoicing' using errcode = '23514';
  end if;

  select i.id, i.status
    into v_existing
  from public.invoices i
  where i.org_id = p_org_id
    and i.job_id = p_job_id
    and i.billing_milestone_id is null
    and i.deleted_at is null
  order by i.created_at desc
  limit 1;

  if found then
    if p_send_now and v_existing.status = 'draft' then
      update public.invoices
         set status = 'sent',
             issued_at = coalesce(issued_at, now()),
             due_date = coalesce(due_date, v_due_date),
             updated_at = now()
       where id = v_existing.id;

      select status into v_invoice_status from public.invoices where id = v_existing.id;
    else
      v_invoice_status := v_existing.status;
    end if;

    return jsonb_build_object(
      'invoice_id', v_existing.id,
      'already_exists', true,
      'status', coalesce(v_invoice_status, v_existing.status)
    );
  end if;

  v_invoice_number := public.invoice_next_number(p_org_id);

  insert into public.invoices (
    org_id,
    created_by,
    client_id,
    job_id,
    invoice_number,
    status,
    subject,
    issued_at,
    due_date,
    subtotal_cents,
    tax_cents,
    total_cents,
    paid_cents,
    balance_cents
  )
  values (
    p_org_id,
    v_uid,
    v_job.client_id,
    p_job_id,
    v_invoice_number,
    case when p_send_now then 'sent' else 'draft' end,
    coalesce(nullif(trim(v_job.title), ''), 'Job invoice'),
    case when p_send_now then now() else null end,
    case when p_send_now then v_due_date else null end,
    0,
    0,
    0,
    0,
    0
  )
  returning id, status into v_invoice_id, v_invoice_status;

  insert into public.invoice_items (org_id, invoice_id, description, qty, unit_price_cents, line_total_cents)
  select
    p_org_id,
    v_invoice_id,
    coalesce(nullif(trim(jli.name), ''), 'Job line item'),
    greatest(coalesce(jli.qty, 1), 0),
    greatest(coalesce(jli.unit_price_cents, 0), 0),
    greatest(round(coalesce(jli.qty, 1) * coalesce(jli.unit_price_cents, 0))::integer, 0)
  from public.job_line_items jli
  where jli.org_id = p_org_id
    and jli.job_id = p_job_id;

  get diagnostics v_line_count = row_count;

  if v_line_count = 0 then
    v_subtotal := greatest(
      coalesce(v_job.total_cents, round(coalesce(v_job.total_amount, 0) * 100)::integer, 0),
      0
    );

    insert into public.invoice_items (org_id, invoice_id, description, qty, unit_price_cents, line_total_cents)
    values (
      p_org_id,
      v_invoice_id,
      coalesce(nullif(trim(v_job.title), ''), 'Job service'),
      1,
      v_subtotal,
      v_subtotal
    );
  end if;

  perform public.recalculate_invoice_totals(v_invoice_id);

  if p_send_now then
    update public.invoices
       set status = 'sent',
           issued_at = coalesce(issued_at, now()),
           due_date = coalesce(due_date, v_due_date),
           updated_at = now()
     where id = v_invoice_id;
  end if;

  select status into v_invoice_status from public.invoices where id = v_invoice_id;

  if to_regclass('public.audit_events') is not null then
    execute
      'insert into public.audit_events (org_id, actor_id, event_type, metadata, created_at)
       values ($1, $2, $3, $4::jsonb, now())'
    using p_org_id, v_uid, 'invoice.created_from_job', jsonb_build_object(
      'job_id', p_job_id,
      'invoice_id', v_invoice_id,
      'send_now', p_send_now
    );
  end if;

  return jsonb_build_object(
    'invoice_id', v_invoice_id,
    'already_exists', false,
    'status', coalesce(v_invoice_status, case when p_send_now then 'sent' else 'draft' end)
  );
exception
  when unique_violation then
    select i.id, i.status
      into v_existing
    from public.invoices i
    where i.org_id = p_org_id
      and i.job_id = p_job_id
      and i.billing_milestone_id is null
      and i.deleted_at is null
    order by i.created_at desc
    limit 1;

    if found then
      return jsonb_build_object(
        'invoice_id', v_existing.id,
        'already_exists', true,
        'status', v_existing.status
      );
    end if;

    raise;
end;
$_$;


--
-- Name: create_invoice_from_milestone(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_milestone(p_org_id uuid, p_job_id uuid, p_milestone_id uuid, p_send_now boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_job record;
  v_ms record;
  v_existing record;
  v_invoice_id uuid;
  v_invoice_status text;
  v_invoice_number text;
  v_due_date date;
  v_amount integer;
  v_label text;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null or p_job_id is null or p_milestone_id is null then
    raise exception 'p_org_id, p_job_id and p_milestone_id are required' using errcode = '22023';
  end if;

  if not public.has_org_membership(v_uid, p_org_id) then
    raise exception 'Not a member of this organization' using errcode = '42501';
  end if;

  if not public.has_org_admin_role(v_uid, p_org_id) then
    raise exception 'Only owner/admin can create invoices from jobs' using errcode = '42501';
  end if;

  select j.id, j.org_id, j.client_id, j.title, j.deleted_at
    into v_job
  from public.jobs j
  where j.id = p_job_id
    and j.org_id = p_org_id
  limit 1;

  if not found or v_job.deleted_at is not null then
    raise exception 'Job not found' using errcode = 'P0002';
  end if;

  if v_job.client_id is null then
    raise exception 'Job must be linked to a client before invoicing' using errcode = '23514';
  end if;

  select m.id, m.label, m.amount_cents, m.due_date
    into v_ms
  from public.job_billing_milestones m
  where m.id = p_milestone_id
    and m.org_id = p_org_id
    and m.job_id = p_job_id
  limit 1;

  if not found then
    raise exception 'Payment milestone not found' using errcode = 'P0002';
  end if;

  v_amount := greatest(coalesce(v_ms.amount_cents, 0), 0);
  if v_amount <= 0 then
    raise exception 'Milestone amount must be greater than zero' using errcode = '23514';
  end if;

  -- The schedule defines the due date, so it is set even on drafts.
  v_due_date := coalesce(v_ms.due_date, (current_date + interval '14 days')::date);
  v_label := coalesce(nullif(trim(v_ms.label), ''), 'Scheduled payment');

  select i.id, i.status
    into v_existing
  from public.invoices i
  where i.billing_milestone_id = p_milestone_id
    and i.deleted_at is null
  order by i.created_at desc
  limit 1;

  if found then
    if p_send_now and v_existing.status = 'draft' then
      update public.invoices
         set status = 'sent',
             issued_at = coalesce(issued_at, now()),
             due_date = coalesce(due_date, v_due_date),
             updated_at = now()
       where id = v_existing.id;

      select status into v_invoice_status from public.invoices where id = v_existing.id;
    else
      v_invoice_status := v_existing.status;
    end if;

    return jsonb_build_object(
      'invoice_id', v_existing.id,
      'already_exists', true,
      'status', coalesce(v_invoice_status, v_existing.status)
    );
  end if;

  v_invoice_number := public.invoice_next_number(p_org_id);

  insert into public.invoices (
    org_id,
    created_by,
    client_id,
    job_id,
    billing_milestone_id,
    invoice_number,
    status,
    subject,
    issued_at,
    due_date,
    subtotal_cents,
    tax_cents,
    total_cents,
    paid_cents,
    balance_cents
  )
  values (
    p_org_id,
    v_uid,
    v_job.client_id,
    p_job_id,
    p_milestone_id,
    v_invoice_number,
    case when p_send_now then 'sent' else 'draft' end,
    coalesce(nullif(trim(v_job.title), ''), 'Job invoice') || ' — ' || v_label,
    case when p_send_now then now() else null end,
    v_due_date,
    0,
    0,
    0,
    0,
    0
  )
  returning id, status into v_invoice_id, v_invoice_status;

  insert into public.invoice_items (org_id, invoice_id, description, qty, unit_price_cents, line_total_cents)
  values (
    p_org_id,
    v_invoice_id,
    v_label,
    1,
    v_amount,
    v_amount
  );

  perform public.recalculate_invoice_totals(v_invoice_id);

  if p_send_now then
    update public.invoices
       set status = 'sent',
           issued_at = coalesce(issued_at, now()),
           updated_at = now()
     where id = v_invoice_id;
  end if;

  select status into v_invoice_status from public.invoices where id = v_invoice_id;

  if to_regclass('public.audit_events') is not null then
    execute
      'insert into public.audit_events (org_id, actor_id, event_type, metadata, created_at)
       values ($1, $2, $3, $4::jsonb, now())'
    using p_org_id, v_uid, 'invoice.created_from_milestone', jsonb_build_object(
      'job_id', p_job_id,
      'milestone_id', p_milestone_id,
      'invoice_id', v_invoice_id,
      'send_now', p_send_now
    );
  end if;

  return jsonb_build_object(
    'invoice_id', v_invoice_id,
    'already_exists', false,
    'status', coalesce(v_invoice_status, case when p_send_now then 'sent' else 'draft' end)
  );
exception
  when unique_violation then
    select i.id, i.status
      into v_existing
    from public.invoices i
    where i.billing_milestone_id = p_milestone_id
      and i.deleted_at is null
    order by i.created_at desc
    limit 1;

    if found then
      return jsonb_build_object(
        'invoice_id', v_existing.id,
        'already_exists', true,
        'status', v_existing.status
      );
    end if;

    raise;
end;
$_$;


--
-- Name: create_invoice_from_visit(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_visit(p_org_id uuid, p_job_id uuid, p_visit_id uuid, p_send_now boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_job record;
  v_visit record;
  v_existing record;
  v_invoice_id uuid;
  v_invoice_status text;
  v_invoice_number text;
  v_amount integer;
  v_visit_count integer;
  v_invoiced_cents integer;
  v_invoiced_count integer;
  v_label text;
  v_visit_date date;
  v_total integer;
  v_all_sub bigint;
  v_dated_sub bigint;
  v_visit_sub bigint;
  v_same_date_events integer;
  v_weight numeric;
  v_use_items boolean := false;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null or p_job_id is null or p_visit_id is null then
    raise exception 'p_org_id, p_job_id and p_visit_id are required' using errcode = '22023';
  end if;

  -- Membre de l'org suffit : les visites sont complétées par les techniciens
  -- sur le terrain et le montant est calculé ici, jamais fourni par l'appelant.
  if not public.has_org_membership(v_uid, p_org_id) then
    raise exception 'Not a member of this organization' using errcode = '42501';
  end if;

  select j.id, j.org_id, j.client_id, j.title, j.total_cents, j.deleted_at
    into v_job
  from public.jobs j
  where j.id = p_job_id
    and j.org_id = p_org_id
  limit 1;

  if not found or v_job.deleted_at is not null then
    raise exception 'Job not found' using errcode = 'P0002';
  end if;

  if v_job.client_id is null then
    raise exception 'Job must be linked to a client before invoicing' using errcode = '23514';
  end if;

  select e.id, e.start_at, e.timezone, e.deleted_at
    into v_visit
  from public.schedule_events e
  where e.id = p_visit_id
    and e.job_id = p_job_id
    and e.org_id = p_org_id
  limit 1;

  if not found or v_visit.deleted_at is not null then
    raise exception 'Visit not found' using errcode = 'P0002';
  end if;

  -- Idempotence : une visite = au plus une facture.
  select i.id, i.status
    into v_existing
  from public.invoices i
  where i.schedule_event_id = p_visit_id
    and i.deleted_at is null
  order by i.created_at desc
  limit 1;

  if found then
    if p_send_now and v_existing.status = 'draft' then
      update public.invoices
         set status = 'sent',
             issued_at = coalesce(issued_at, now()),
             updated_at = now()
       where id = v_existing.id;
      select status into v_invoice_status from public.invoices where id = v_existing.id;
    else
      v_invoice_status := v_existing.status;
    end if;
    return jsonb_build_object(
      'invoice_id', v_existing.id,
      'already_exists', true,
      'status', coalesce(v_invoice_status, v_existing.status)
    );
  end if;

  select count(*)::int into v_visit_count
  from public.schedule_events e
  where e.job_id = p_job_id
    and e.org_id = p_org_id
    and e.deleted_at is null;

  select coalesce(sum(i.total_cents), 0)::int, count(*)::int
    into v_invoiced_cents, v_invoiced_count
  from public.invoices i
  where i.job_id = p_job_id
    and i.schedule_event_id is not null
    and i.deleted_at is null;

  if v_visit_count <= 0 then
    raise exception 'Job has no active visits' using errcode = '23514';
  end if;

  v_total := coalesce(v_job.total_cents, 0);
  v_visit_date := (v_visit.start_at at time zone coalesce(nullif(v_visit.timezone, ''), 'America/Montreal'))::date;

  -- Sous-totaux des lignes du job : toutes, et celles rattachées à une visite.
  select coalesce(sum(li.total_cents), 0),
         coalesce(sum(li.total_cents) filter (where li.visit_date is not null), 0)
    into v_all_sub, v_dated_sub
  from public.job_line_items li
  where li.job_id = p_job_id
    and li.org_id = p_org_id
    and li.deleted_at is null
    and li.included;

  if v_invoiced_count >= v_visit_count - 1 then
    -- Dernière visite non facturée : reste exact (somme = total du job).
    v_amount := greatest(v_total - v_invoiced_cents, 0);
    -- Les lignes de la visite restent affichées si elles existent (ci-dessous).
    select coalesce(sum(li.total_cents), 0) into v_visit_sub
    from public.job_line_items li
    where li.job_id = p_job_id and li.org_id = p_org_id
      and li.deleted_at is null and li.included
      and li.visit_date = v_visit_date;
    v_use_items := v_dated_sub > 0 and v_visit_sub > 0 and v_visit_sub <= v_amount;
  elsif v_dated_sub > 0 and v_all_sub > 0 then
    -- Services personnalisés par visite : part au prorata des lignes de CETTE
    -- visite (les lignes sans visite se répartissent également). Si plusieurs
    -- visites actives partagent la même date, elles se partagent son poids.
    select coalesce(sum(li.total_cents), 0) into v_visit_sub
    from public.job_line_items li
    where li.job_id = p_job_id and li.org_id = p_org_id
      and li.deleted_at is null and li.included
      and li.visit_date = v_visit_date;

    select count(*)::int into v_same_date_events
    from public.schedule_events e
    where e.job_id = p_job_id and e.org_id = p_org_id
      and e.deleted_at is null
      and (e.start_at at time zone coalesce(nullif(e.timezone, ''), 'America/Montreal'))::date = v_visit_date;

    v_weight := v_visit_sub::numeric / greatest(v_same_date_events, 1)
      + (v_all_sub - v_dated_sub)::numeric / v_visit_count;
    v_amount := least(
      round(v_total::numeric * v_weight / v_all_sub)::int,
      greatest(v_total - v_invoiced_cents, 0)
    );

    if v_amount <= 0 then
      -- Visite sans services (poids nul) : rien à facturer — on saute sans
      -- erreur pour ne pas gêner la complétion de la visite sur le terrain.
      return jsonb_build_object(
        'invoice_id', null,
        'already_exists', false,
        'skipped', true,
        'status', 'skipped'
      );
    end if;

    v_use_items := v_same_date_events = 1 and v_visit_sub > 0 and v_visit_sub <= v_amount;
  else
    -- Comportement historique : part égale du total du job.
    v_amount := round(v_total::numeric / v_visit_count)::int;
  end if;

  if v_amount <= 0 then
    raise exception 'Nothing left to invoice for this job' using errcode = '23514';
  end if;

  v_label := coalesce(nullif(trim(v_job.title), ''), 'Job')
    || ' — Visite du ' || to_char(v_visit_date, 'YYYY-MM-DD');

  v_invoice_number := public.invoice_next_number(p_org_id);

  insert into public.invoices (
    org_id,
    created_by,
    client_id,
    job_id,
    schedule_event_id,
    invoice_number,
    status,
    subject,
    issued_at,
    due_date,
    subtotal_cents,
    tax_cents,
    total_cents,
    paid_cents,
    balance_cents
  )
  values (
    p_org_id,
    v_uid,
    v_job.client_id,
    p_job_id,
    p_visit_id,
    v_invoice_number,
    case when p_send_now then 'sent' else 'draft' end,
    v_label,
    case when p_send_now then now() else null end,
    (current_date + interval '14 days')::date,
    0,
    case when v_use_items then v_amount - v_visit_sub::int else 0 end,
    0, 0, 0
  )
  returning id, status into v_invoice_id, v_invoice_status;

  if v_use_items then
    -- Les services réels de la visite ; l'écart TTC (taxes) est dans tax_cents.
    insert into public.invoice_items (org_id, invoice_id, description, qty, unit_price_cents, line_total_cents, sort_order)
    select p_org_id, v_invoice_id, li.name, li.qty, li.unit_price_cents, li.total_cents,
           row_number() over (order by li.created_at)
    from public.job_line_items li
    where li.job_id = p_job_id and li.org_id = p_org_id
      and li.deleted_at is null and li.included
      and li.visit_date = v_visit_date;
  else
    insert into public.invoice_items (org_id, invoice_id, description, qty, unit_price_cents, line_total_cents)
    values (p_org_id, v_invoice_id, v_label, 1, v_amount, v_amount);
  end if;

  perform public.recalculate_invoice_totals(v_invoice_id);

  if p_send_now then
    update public.invoices
       set status = 'sent',
           issued_at = coalesce(issued_at, now()),
           updated_at = now()
     where id = v_invoice_id;
  end if;

  select status into v_invoice_status from public.invoices where id = v_invoice_id;

  if to_regclass('public.audit_events') is not null then
    execute
      'insert into public.audit_events (org_id, actor_id, event_type, metadata, created_at)
       values ($1, $2, $3, $4::jsonb, now())'
    using p_org_id, v_uid, 'invoice.created_from_visit', jsonb_build_object(
      'job_id', p_job_id,
      'visit_id', p_visit_id,
      'invoice_id', v_invoice_id,
      'send_now', p_send_now
    );
  end if;

  return jsonb_build_object(
    'invoice_id', v_invoice_id,
    'already_exists', false,
    'status', coalesce(v_invoice_status, case when p_send_now then 'sent' else 'draft' end)
  );
exception
  when unique_violation then
    select i.id, i.status
      into v_existing
    from public.invoices i
    where i.schedule_event_id = p_visit_id
      and i.deleted_at is null
    order by i.created_at desc
    limit 1;

    if found then
      return jsonb_build_object(
        'invoice_id', v_existing.id,
        'already_exists', true,
        'status', v_existing.status
      );
    end if;

    raise;
end;
$_$;


--
-- Name: create_job_from_intent(uuid, uuid, text, text, text, integer, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_job_from_intent(p_intent_id uuid, p_lead_id uuid, p_title text, p_address text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_estimated_minutes integer DEFAULT NULL::integer, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_timezone text DEFAULT 'America/Montreal'::text, p_force_create_another boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_intent public.job_intents%rowtype;
  v_client public.clients%rowtype;
  v_job_id uuid;
  v_end_at timestamptz;
  v_status text;
BEGIN
  SELECT * INTO v_intent
  FROM public.job_intents
  WHERE id = p_intent_id AND deleted_at IS NULL
  FOR UPDATE;

  IF v_intent.id IS NULL THEN
    RAISE EXCEPTION 'Intent not found';
  END IF;

  IF v_intent.status != 'pending' AND NOT p_force_create_another THEN
    RAISE EXCEPTION 'Intent already consumed';
  END IF;

  SELECT * INTO v_client
  FROM public.clients
  WHERE id = p_lead_id AND deleted_at IS NULL;

  IF v_client.id IS NULL THEN
    RAISE EXCEPTION 'Client not found. Cannot create job.';
  END IF;

  v_end_at := NULL;
  IF p_start_at IS NOT NULL AND p_estimated_minutes IS NOT NULL THEN
    v_end_at := p_start_at + (p_estimated_minutes || ' minutes')::interval;
  END IF;

  v_status := CASE WHEN p_start_at IS NOT NULL THEN 'scheduled' ELSE 'draft' END;

  INSERT INTO public.jobs (
    org_id, created_by, client_id, lead_id, title, property_address, notes,
    scheduled_at, end_at, status
  ) VALUES (
    v_client.org_id, v_uid, v_client.id, v_client.id,
    COALESCE(NULLIF(trim(p_title), ''), 'New Job'),
    COALESCE(NULLIF(trim(p_address), ''), v_client.address, ''),
    NULLIF(trim(COALESCE(p_notes, '')), ''),
    p_start_at, v_end_at, v_status
  )
  RETURNING id INTO v_job_id;

  IF p_start_at IS NOT NULL AND v_end_at IS NOT NULL THEN
    INSERT INTO public.schedule_events (
      org_id, created_by, job_id, start_time, end_time, timezone, status
    ) VALUES (
      v_client.org_id, v_uid, v_job_id, p_start_at, v_end_at,
      COALESCE(p_timezone, 'America/Montreal'), 'scheduled'
    );
  END IF;

  UPDATE public.job_intents
  SET status = 'consumed', consumed_at = now()
  WHERE id = p_intent_id;

  RETURN jsonb_build_object(
    'job_id', v_job_id,
    'client_id', v_client.id,
    'lead_id', v_client.id,
    'status', v_status
  );
END;
$$;


--
-- Name: create_or_get_invoice_from_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_get_invoice_from_job(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_job record;
  v_existing record;
  v_invoice_id uuid;
  v_invoice_number text;
  v_due_date date := (current_date + interval '14 days')::date;
  v_subtotal_cents integer := 0;
  v_tax_cents integer := 0;
  v_total_cents integer := 0;
  v_line_count integer := 0;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null or p_job_id is null then
    raise exception 'p_org_id and p_job_id are required' using errcode = '22023';
  end if;

  if not public.crm_is_org_admin(p_org_id, v_uid) then
    raise exception 'Only owner/admin can create invoice from job' using errcode = '42501';
  end if;

  select *
    into v_job
  from public.jobs j
  where j.id = p_job_id
    and j.org_id = p_org_id
    and j.deleted_at is null
  for update;

  if not found then
    raise exception 'Job not found' using errcode = 'P0002';
  end if;

  if v_job.client_id is null then
    raise exception 'Job must have client_id' using errcode = '23514';
  end if;

  select i.id, i.status
    into v_existing
  from public.invoices i
  where i.org_id = p_org_id
    and i.job_id = p_job_id
    and i.deleted_at is null
  order by i.created_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'ok', true,
      'invoice_id', v_existing.id,
      'already_exists', true,
      'status', v_existing.status
    );
  end if;

  v_subtotal_cents := greatest(
    coalesce(
      (v_job.subtotal * 100)::integer,
      v_job.total_cents,
      round(coalesce(v_job.total_amount, 0) * 100)::integer,
      0
    ),
    0
  );

  v_tax_cents := greatest(
    coalesce((v_job.tax_total * 100)::integer, 0),
    0
  );

  v_total_cents := greatest(
    coalesce(
      (v_job.total * 100)::integer,
      v_subtotal_cents + v_tax_cents,
      0
    ),
    0
  );

  v_invoice_number := public.crm_next_invoice_number(p_org_id);

  insert into public.invoices (
    org_id,
    created_by,
    client_id,
    job_id,
    invoice_number,
    status,
    subject,
    issued_at,
    due_date,
    subtotal_cents,
    tax_cents,
    total_cents,
    paid_cents,
    balance_cents,
    currency
  )
  values (
    p_org_id,
    v_uid,
    v_job.client_id,
    p_job_id,
    v_invoice_number,
    'draft',
    coalesce(nullif(trim(v_job.title), ''), 'Job invoice'),
    null,
    v_due_date,
    v_subtotal_cents,
    v_tax_cents,
    v_total_cents,
    0,
    v_total_cents,
    coalesce(v_job.currency, 'CAD')
  )
  returning id into v_invoice_id;

  -- Essaye de copier les lignes job_line_items si la table existe
  begin
    insert into public.invoice_items (org_id, invoice_id, description, qty, unit_price_cents, line_total_cents)
    select
      p_org_id,
      v_invoice_id,
      coalesce(nullif(trim(jli.name), ''), 'Job line item'),
      greatest(coalesce(jli.qty, 1), 0),
      greatest(coalesce(jli.unit_price_cents, 0), 0),
      greatest(round(coalesce(jli.qty, 1) * coalesce(jli.unit_price_cents, 0))::integer, 0)
    from public.job_line_items jli
    where jli.job_id = p_job_id
      and (jli.org_id = p_org_id or jli.org_id is null);

    get diagnostics v_line_count = row_count;
  exception
    when undefined_table then
      v_line_count := 0;
  end;

  -- Fallback: une ligne unique si aucune ligne item
  if v_line_count = 0 then
    insert into public.invoice_items (org_id, invoice_id, description, qty, unit_price_cents, line_total_cents)
    values (
      p_org_id,
      v_invoice_id,
      coalesce(nullif(trim(v_job.title), ''), 'Job service'),
      1,
      v_total_cents,
      v_total_cents
    );
  end if;

  -- Si la fonction existe, recalcul officiel
  if to_regprocedure('public.recalculate_invoice_totals(uuid)') is not null then
    perform public.recalculate_invoice_totals(v_invoice_id);
  end if;

  return jsonb_build_object(
    'ok', true,
    'invoice_id', v_invoice_id,
    'already_exists', false,
    'status', 'draft'
  );

exception
  when unique_violation then
    select i.id, i.status
      into v_existing
    from public.invoices i
    where i.org_id = p_org_id
      and i.job_id = p_job_id
      and i.deleted_at is null
    order by i.created_at desc
    limit 1;

    if found then
      return jsonb_build_object(
        'ok', true,
        'invoice_id', v_existing.id,
        'already_exists', true,
        'status', v_existing.status
      );
    end if;

    raise;
end;
$$;


--
-- Name: create_pipeline_deal(uuid, text, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pipeline_deal(p_lead_id uuid, p_title text, p_value numeric, p_stage text DEFAULT 'new'::text, p_notes text DEFAULT NULL::text, p_pipeline_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client public.clients%rowtype;
  v_stage text;
  v_deal_id uuid;
BEGIN
  SELECT * INTO v_client
  FROM public.clients
  WHERE id = p_lead_id
    AND deleted_at IS NULL
  LIMIT 1;

  IF v_client.id IS NULL THEN
    RAISE EXCEPTION 'Client not found';
  END IF;

  v_stage := CASE lower(trim(coalesce(p_stage, '')))
    WHEN 'new'           THEN 'new'
    WHEN 'contacted'     THEN 'contacted'
    WHEN 'estimate_sent' THEN 'estimate_sent'
    WHEN 'estimate sent' THEN 'estimate_sent'
    WHEN 'follow_up'     THEN 'follow_up'
    WHEN 'follow-up'     THEN 'follow_up'
    WHEN 'won'           THEN 'won'
    WHEN 'closed'        THEN 'closed'
    WHEN 'lost'          THEN 'lost'
    WHEN 'qualified'     THEN 'new'
    WHEN 'contact'       THEN 'contacted'
    WHEN 'quote_sent'    THEN 'estimate_sent'
    WHEN 'quote sent'    THEN 'estimate_sent'
    ELSE 'new'
  END;

  INSERT INTO public.pipeline_deals (
    org_id, created_by, lead_id, client_id, stage, value, title, notes, lost_at
  )
  VALUES (
    coalesce(v_client.org_id, public.current_org_id()),
    coalesce(auth.uid(), v_client.created_by),
    v_client.id,
    v_client.id,
    v_stage,
    coalesce(p_value, 0),
    coalesce(nullif(trim(p_title), ''), 'New deal'),
    nullif(trim(p_notes), ''),
    CASE WHEN v_stage = 'lost' THEN now() ELSE NULL END
  )
  RETURNING id INTO v_deal_id;

  RETURN v_deal_id;
END;
$$;


--
-- Name: creer_pipeline_sur_mesure(text, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creer_pipeline_sur_mesure(p_nom text, p_etapes jsonb, p_color_mode text DEFAULT 'none'::text, p_use_deal_probability boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org      uuid := current_org_id();
  v_uid      uuid := auth.uid();
  v_pipeline uuid;
  v_nom      text := btrim(coalesce(p_nom, ''));
  v_etape    jsonb;
  v_position integer := 0;
  v_a_gagne  boolean := false;
  v_a_perdu  boolean := false;
  v_kind     text;
  v_nb       integer := 0;
  v_mode     text := coalesce(nullif(btrim(coalesce(p_color_mode, '')), ''), 'none');
begin
  if v_org is null or v_uid is null then
    raise exception 'Aucune session';
  end if;

  -- Créer un pipeline est un geste d'administration : il s'impose à toute
  -- l'équipe et décide où atterrissent les leads.
  if not has_org_admin_role(v_uid, v_org) then
    raise exception 'Seuls les administrateurs peuvent créer un pipeline';
  end if;

  if v_nom = '' then
    raise exception 'Le nom du pipeline est requis';
  end if;

  if v_mode not in ('none', 'dot', 'tint') then
    raise exception 'Mode de couleur inconnu : %', v_mode;
  end if;

  if jsonb_typeof(p_etapes) is distinct from 'array' then
    raise exception 'Les étapes doivent être une liste';
  end if;

  insert into public.pipelines_ventes (org_id, name, is_default, color_mode, use_deal_probability)
  values (v_org, v_nom, false, v_mode, coalesce(p_use_deal_probability, false))
  returning id into v_pipeline;

  for v_etape in select * from jsonb_array_elements(p_etapes)
  loop
    v_kind := coalesce(v_etape ->> 'kind', 'open');
    if v_kind not in ('open', 'won', 'lost') then
      raise exception 'Type d''étape inconnu : %', v_kind;
    end if;
    if btrim(coalesce(v_etape ->> 'nom_fr', '')) = '' then
      raise exception 'Chaque étape doit avoir un nom';
    end if;

    v_position := v_position + 1;
    v_nb := v_nb + 1;
    if v_kind = 'won'  then v_a_gagne := true; end if;
    if v_kind = 'lost' then v_a_perdu := true; end if;

    insert into public.pipeline_stages (
      org_id, pipeline_id, name_fr, name_en, guidance_fr, guidance_en,
      position, kind, probability, show_in_reports
    )
    values (
      v_org, v_pipeline,
      btrim(v_etape ->> 'nom_fr'),
      coalesce(nullif(btrim(coalesce(v_etape ->> 'nom_en', '')), ''), btrim(v_etape ->> 'nom_fr')),
      coalesce(v_etape ->> 'guidance_fr', ''),
      coalesce(v_etape ->> 'guidance_en', ''),
      v_position,
      v_kind::public.pipeline_stage_kind,
      -- Gagné et perdu valent 100 % et 0 % : des faits, pas des estimations.
      case v_kind
        when 'won'  then 100
        when 'lost' then 0
        else nullif(v_etape ->> 'probability', '')::integer
      end,
      coalesce((v_etape ->> 'show_in_reports')::boolean, true)
    );
  end loop;

  if v_nb = 0 then
    raise exception 'Un pipeline a besoin d''au moins une étape';
  end if;

  -- Les deux étapes terminales, ajoutées si elles manquent. Un pipeline
  -- qu'on ne peut pas terminer casse le closing, le badge « Job à créer » et
  -- la raison de perte — c'est un état dont on ne sort plus.
  if not v_a_gagne then
    v_position := v_position + 1;
    insert into public.pipeline_stages (org_id, pipeline_id, name_fr, name_en, position, kind, probability)
    values (v_org, v_pipeline, 'Gagné', 'Won', v_position, 'won', 100);
  end if;

  if not v_a_perdu then
    v_position := v_position + 1;
    insert into public.pipeline_stages (org_id, pipeline_id, name_fr, name_en, position, kind, probability)
    values (v_org, v_pipeline, 'Perdu', 'Lost', v_position, 'lost', 0);
  end if;

  return v_pipeline;
end;
$$;


--
-- Name: FUNCTION creer_pipeline_sur_mesure(p_nom text, p_etapes jsonb, p_color_mode text, p_use_deal_probability boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.creer_pipeline_sur_mesure(p_nom text, p_etapes jsonb, p_color_mode text, p_use_deal_probability boolean) IS 'Crée un pipeline avec ses propres étapes, son mode de couleur et sa source de probabilité. L''organisation vient de la session, jamais d''un paramètre. Les étapes « gagné » et « perdu » sont ajoutées si elles manquent : un pipeline qu''on ne peut pas terminer casse le closing et la raison de perte.';


--
-- Name: creer_pipeline_ventes(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creer_pipeline_ventes(p_nom text, p_modele text DEFAULT 'generique'::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org      uuid;
  v_pipeline uuid;
  v_nom      text;
begin
  v_org := public.current_org_id();
  if v_org is null then
    raise exception 'Aucune organisation pour la session en cours';
  end if;

  v_nom := btrim(coalesce(p_nom, ''));
  if v_nom = '' then
    raise exception 'Le nom du pipeline ne peut pas être vide';
  end if;

  if p_modele not in ('generique', 'nettoyage', 'construction') then
    raise exception 'Modèle inconnu : % (attendu generique, nettoyage ou construction)', p_modele;
  end if;

  -- `is_default` reste false : créer un pipeline ne déplace jamais le défaut.
  -- C'est `pipeline_definir_defaut` qui le fait, explicitement.
  insert into public.pipelines_ventes (org_id, name, is_default)
  values (v_org, v_nom, false)
  returning id into v_pipeline;

  if p_modele = 'construction' then
    insert into public.pipeline_stages
      (org_id, pipeline_id, name_fr, name_en, guidance_fr, guidance_en, position, kind)
    values
      (v_org, v_pipeline, 'Nouveau lead', 'New lead',
       'Rappelle dans les 15 minutes : c''est là que la majorité des contrats se gagnent. Note le type de travaux et l''échéance souhaitée dès le premier appel.',
       'Call back within 15 minutes — that''s where most contracts are won. Capture the type of work and the target timeline on the first call.',
       1, 'open'),
      (v_org, v_pipeline, 'Visite planifiée', 'Site visit booked',
       'Confirme la visite la veille. Sur place, photographie tout : une estimation faite de mémoire se révise toujours à la hausse, et c''est le client qui le prend mal.',
       'Confirm the visit the day before. On site, photograph everything: an estimate made from memory always gets revised upward, and the client is the one who resents it.',
       2, 'open'),
      (v_org, v_pipeline, 'Estimation envoyée', 'Estimate sent',
       'Appelle le lendemain pour valider que le montant est compris. Une estimation envoyée sans appel de suivi se ferme deux fois moins souvent.',
       'Call the next day to confirm the amount is understood. An estimate sent without a follow-up call closes half as often.',
       3, 'open'),
      (v_org, v_pipeline, 'Négociation', 'Negotiation',
       'Ajuste le contenu avant le prix : retire une option, étale les travaux. Baisser le prix à contenu égal dévalue tout ce que tu chiffreras ensuite.',
       'Adjust scope before price: drop an option, phase the work. Cutting the price at equal scope devalues everything you quote afterwards.',
       4, 'open'),
      (v_org, v_pipeline, 'Gagné', 'Won',
       'Crée la job tout de suite pour bloquer la date. Confirme les accès, le stationnement et la gestion des débris avant le premier jour.',
       'Create the job right away to lock the date. Confirm access, parking and debris handling before day one.',
       5, 'won'),
      (v_org, v_pipeline, 'Perdu', 'Lost',
       'Note la vraie raison, pas « pas intéressé » : c''est ce qui ajuste tes prix. Remets un rappel à 6 mois si le client a seulement reporté.',
       'Log the real reason, not "not interested" — that''s what tunes your pricing. Set a 6-month reminder if the client merely postponed.',
       6, 'lost');

  elsif p_modele = 'nettoyage' then
    insert into public.pipeline_stages
      (org_id, pipeline_id, name_fr, name_en, guidance_fr, guidance_en, position, kind)
    values
      (v_org, v_pipeline, 'Nouveau lead', 'New lead',
       'Appelle dans les 15 minutes : c''est là que la majorité des soumissions se gagnent. Note le type de surface et la superficie approximative dès le premier contact.',
       'Call within 15 minutes — that''s where most quotes are won. Capture the surface type and rough square footage on the first contact.',
       1, 'open'),
      (v_org, v_pipeline, 'Contacté', 'Contacted',
       'Qualifie le besoin : fréquence souhaitée, budget, accès au bâtiment. Fixe tout de suite la visite, ou envoie la soumission si le besoin est standard.',
       'Qualify the need: desired frequency, budget, building access. Book the site visit right away, or send the quote if the job is standard.',
       2, 'open'),
      (v_org, v_pipeline, 'Soumission envoyée', 'Quote sent',
       'Confirme la réception par téléphone le lendemain. Une soumission ouverte sans appel de suivi se ferme deux fois moins souvent.',
       'Confirm receipt by phone the next day. An open quote with no follow-up call closes half as often.',
       3, 'open'),
      (v_org, v_pipeline, 'Relance', 'Follow-up',
       'Trois relances maximum, espacées de trois jours, puis tranche. Propose un rabais première visite ou un essai d''un mois plutôt que de baisser le prix récurrent.',
       'Three follow-ups max, three days apart, then decide. Offer a first-visit discount or a one-month trial instead of cutting the recurring price.',
       4, 'open'),
      (v_org, v_pipeline, 'Gagné', 'Won',
       'Crée la job immédiatement pour bloquer la date dans l''horaire. Confirme les accès (codes, clés, stationnement) avant la première visite.',
       'Create the job right away to lock the date in the schedule. Confirm access (codes, keys, parking) before the first visit.',
       5, 'won'),
      (v_org, v_pipeline, 'Perdu', 'Lost',
       'Note la vraie raison, pas « pas intéressé » : c''est ce qui ajuste les prix. Remets un rappel à 6 mois si le client a simplement reporté.',
       'Log the real reason, not "not interested" — that''s what tunes pricing. Set a 6-month reminder if the client merely postponed.',
       6, 'lost');

  else
    insert into public.pipeline_stages
      (org_id, pipeline_id, name_fr, name_en, guidance_fr, guidance_en, position, kind)
    values
      (v_org, v_pipeline, 'Nouveau lead', 'New lead',
       'Contacte le plus vite possible : le délai de première réponse est le facteur qui pèse le plus sur le taux de closing.',
       'Reach out as fast as you can: first-response time is the single biggest factor in your closing rate.',
       1, 'open'),
      (v_org, v_pipeline, 'Contacté', 'Contacted',
       'Qualifie le besoin et le budget, puis fixe la prochaine étape avec une date. Un lead sans prochaine étape datée retombe au fond de la pile.',
       'Qualify the need and budget, then set the next step with a date. A lead with no dated next step sinks to the bottom of the pile.',
       2, 'open'),
      (v_org, v_pipeline, 'Soumission envoyée', 'Quote sent',
       'Confirme la réception, et vérifie que le prix est compris — pas seulement reçu.',
       'Confirm receipt, and check the price is understood — not just delivered.',
       3, 'open'),
      (v_org, v_pipeline, 'Relance', 'Follow-up',
       'Fixe-toi une limite de relances, puis tranche. Un deal qui traîne sans décision occupe la place d''un deal vivant.',
       'Set yourself a follow-up limit, then decide. A deal that drags with no decision takes the place of a live one.',
       4, 'open'),
      (v_org, v_pipeline, 'Gagné', 'Won',
       'Crée la job tout de suite : c''est ce qui relie la vente au travail réel et alimente tes revenus par source.',
       'Create the job right away: it links the sale to the actual work and feeds your revenue-by-source figures.',
       5, 'won'),
      (v_org, v_pipeline, 'Perdu', 'Lost',
       'Note la vraie raison : c''est la seule matière qui permet d''ajuster les prix et les relances.',
       'Log the real reason: it''s the only material you have to tune pricing and follow-ups.',
       6, 'lost');
  end if;

  return v_pipeline;
end;
$$;


--
-- Name: FUNCTION creer_pipeline_ventes(p_nom text, p_modele text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.creer_pipeline_ventes(p_nom text, p_modele text) IS 'Crée un pipeline SUPPLÉMENTAIRE (is_default = false) avec ses étapes, dans l''organisation de la session. Contrairement à seed_pipeline_ventes, ne court-circuite pas si un pipeline existe déjà. SECURITY INVOKER : la RLS admin de pipelines_ventes et pipeline_stages fait le contrôle. Modèles : generique, nettoyage, construction.';


--
-- Name: crm_enforce_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_enforce_scope() RETURNS trigger
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid;
  v_org uuid;
begin
  v_user := auth.uid();

  -- SQL editor/service role path: require explicit values.
  if v_user is null then
    if new.org_id is null then
      raise exception 'org_id is required when no auth context' using errcode = '23502';
    end if;
    if to_jsonb(new) ? 'created_by' and new.created_by is null then
      raise exception 'created_by is required when no auth context' using errcode = '23502';
    end if;
    return new;
  end if;

  v_org := public.current_org_id();
  if v_org is null then
    raise exception 'unable to resolve org_id for authenticated user' using errcode = '42501';
  end if;

  new.org_id := v_org;
  if to_jsonb(new) ? 'created_by' then
    new.created_by := v_user;
  end if;
  return new;
end;
$$;


--
-- Name: crm_invoices_ensure_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_invoices_ensure_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.invoice_number is null or btrim(new.invoice_number) = '' then
    new.invoice_number := public.crm_next_invoice_number(new.org_id);
  end if;

  if new.created_at is null then
    new.created_at := now();
  end if;
  if new.updated_at is null then
    new.updated_at := now();
  end if;

  return new;
end;
$$;


--
-- Name: crm_is_org_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_is_org_admin(p_org_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.memberships m
    where m.org_id = p_org_id
      and m.user_id = coalesce(p_user_id, auth.uid())
      and m.role in ('owner','admin')
  );
$$;


--
-- Name: crm_is_org_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_is_org_member(p_org_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.memberships m
    where m.org_id = p_org_id
      and m.user_id = coalesce(p_user_id, auth.uid())
  );
$$;


--
-- Name: crm_leads_stage_timestamps(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_leads_stage_timestamps() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.stage := public.crm_normalize_lead_stage(new.stage);

  if new.stage = 'lost' then
    new.lost_at := coalesce(new.lost_at, now());
  elsif tg_op = 'update' and old.stage = 'lost' and new.stage <> 'lost' then
    new.lost_at := null;
  end if;

  if new.stage = 'closed' then
    new.closed_at := coalesce(new.closed_at, now());
  elsif tg_op = 'update' and old.stage = 'closed' and new.stage <> 'closed' then
    new.closed_at := null;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: crm_next_invoice_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_next_invoice_number(p_org_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_next text;
  v_max_num bigint := 0;
begin
  if p_org_id is null then
    raise exception 'p_org_id is required' using errcode = '22023';
  end if;

  -- N4.6 — L'invariant « lire puis ecrire » exige un verrou explicite.
  -- MEME cle que invoice_next_number() : les deux chemins se serialisent
  -- mutuellement par org. Verrou de transaction : libere au commit/rollback.
  perform pg_advisory_xact_lock(hashtextextended(p_org_id::text || ':invoice', 0));

  -- Chemin nominal : la fonction officielle, deja verrouillee et testee.
  if to_regprocedure('public.invoice_next_number(uuid)') is not null then
    execute 'select public.invoice_next_number($1)' into v_next using p_org_id;
    if v_next is not null and btrim(v_next) <> '' then
      return v_next;
    end if;
  end if;

  -- Repli : max + 1, desormais sous verrou (auparavant en lecture sale).
  -- Ne compte que les factures vivantes, coherent avec l'index unique partiel
  -- invoices_org_number_uniq ... where deleted_at is null (20260751100300).
  select coalesce(max(
           case
             when regexp_replace(coalesce(i.invoice_number, ''), '[^0-9]', '', 'g') <> ''
               then regexp_replace(i.invoice_number, '[^0-9]', '', 'g')::bigint
             else 0
           end), 0)
    into v_max_num
    from public.invoices i
   where i.org_id = p_org_id
     and i.deleted_at is null;

  return (v_max_num + 1)::text;
end $_$;


--
-- Name: FUNCTION crm_next_invoice_number(p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crm_next_invoice_number(p_org_id uuid) IS 'N3.7/N4.6 — Chemin de REPLI appele par le trigger crm_invoices_ensure_number et par create_or_get_invoice_from_job. Delegue a invoice_next_number() et partage son verrou consultatif par org. NE PAS supprimer : trigger actif.';


--
-- Name: crm_normalize_lead_stage(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_normalize_lead_stage(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v text := lower(trim(coalesce(p_value, '')));
begin
  if v in ('qualified','new','lead') then return 'qualified'; end if;
  if v in ('contacted','contact') then return 'contacted'; end if;
  if v in ('quote_sent','quote sent','proposal') then return 'quote_sent'; end if;
  if v in ('closed','won','converted') then return 'closed'; end if;
  if v in ('lost','dead','cancelled','canceled') then return 'lost'; end if;
  return 'qualified';
end;
$$;


--
-- Name: current_org_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_org_ids() RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  claim_orgs jsonb;
begin
  -- Fast path : org_ids depuis le claim JWT (posé par custom_access_token_hook),
  -- re-vérifiés contre les adhésions ACTIVES : un jeton émis avant une
  -- suspension ne rouvre rien (clé primaire (user_id, org_id) → lookup direct).
  begin
    claim_orgs := auth.jwt() -> 'app_metadata' -> 'org_ids';
  exception when others then
    claim_orgs := null;
  end;
  if claim_orgs is not null and jsonb_typeof(claim_orgs) = 'array' and jsonb_array_length(claim_orgs) > 0 then
    return query
      select c.org_id
        from (select (jsonb_array_elements_text(claim_orgs))::uuid as org_id) c
       where exists (
         select 1 from public.memberships m
          where m.user_id = auth.uid()
            and m.org_id = c.org_id
            and coalesce(m.status, 'active') = 'active'
       );
    return;
  end if;
  -- Fallback (vieux token sans claim) : requête memberships. Aucun lockout.
  if to_regclass('public.memberships') is not null then
    return query select m.org_id from public.memberships m
      where m.user_id = auth.uid() and coalesce(m.status, 'active') = 'active';
  end if;
  return;
end;
$$;


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  claims jsonb;
  user_orgs uuid[];
begin
  -- Blindé : ne JAMAIS casser le login. Toute erreur => token inchangé.
  begin
    select array_agg(distinct m.org_id) into user_orgs
    from public.memberships m
    where m.user_id = (event->>'user_id')::uuid
      and coalesce(m.status, 'active') = 'active';

    claims := coalesce(event->'claims', '{}'::jsonb);
    if coalesce(claims->'app_metadata', 'null'::jsonb) = 'null'::jsonb then
      claims := jsonb_set(claims, '{app_metadata}', '{}'::jsonb);
    end if;
    if user_orgs is not null then
      claims := jsonb_set(claims, '{app_metadata,org_ids}', to_jsonb(user_orgs));
      claims := jsonb_set(claims, '{app_metadata,org_id}', to_jsonb(user_orgs[1]));
    else
      -- Plus aucune adhésion active : on retire les org_ids d'un ancien jeton.
      claims := claims #- '{app_metadata,org_ids}';
      claims := claims #- '{app_metadata,org_id}';
    end if;
    event := jsonb_set(event, '{claims}', claims);
  exception when others then
    null; -- on avale toute erreur, login jamais bloqué
  end;
  return event;
end;
$$;


--
-- Name: deals_deduire_statut(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_deduire_statut() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind public.pipeline_stage_kind;
begin
  -- Le statut a été fixé explicitement dans CETTE écriture : on n'y touche pas.
  if tg_op = 'UPDATE' and new.statut is distinct from old.statut then
    return new;
  end if;

  if tg_op = 'UPDATE' and new.stage_id is not distinct from old.stage_id then
    return new;
  end if;

  select kind into v_kind from public.pipeline_stages where id = new.stage_id;

  new.statut := case v_kind
    when 'won'  then 'gagne'::public.deal_statut
    -- Un deal déjà abandonné qui change d'étape perdue le reste.
    when 'lost' then (case when tg_op = 'UPDATE' and old.statut = 'abandonne'
                           then 'abandonne'::public.deal_statut
                           else 'perdu'::public.deal_statut end)
    else 'ouvert'::public.deal_statut
  end;

  return new;
end;
$$;


--
-- Name: FUNCTION deals_deduire_statut(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.deals_deduire_statut() IS 'Trigger : déduit le statut du deal à partir du kind de l''étape, sauf statut posé explicitement. Non exécutable directement (révoquée à anon/authenticated — moindre privilège).';


--
-- Name: deals_ecrire_historique(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_ecrire_historique() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.stage_id is not distinct from old.stage_id then
    return null;
  end if;

  insert into public.deal_stage_history (org_id, deal_id, from_stage_id, to_stage_id, actor_type, actor_id)
  values (
    new.org_id,
    new.id,
    case when tg_op = 'UPDATE' then old.stage_id else null end,
    new.stage_id,
    case when auth.uid() is null then 'system'::public.deal_actor_type
         else 'user'::public.deal_actor_type end,
    auth.uid()
  );

  return null;
end;
$$;


--
-- Name: deals_emettre_evenements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_emettre_evenements() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.stage_id is not distinct from old.stage_id then
    return null;
  end if;

  if tg_op = 'UPDATE' and old.stage_id is not null then
    insert into public.pipeline_events (org_id, deal_id, type, payload, cle_unicite)
    values (
      new.org_id, new.id, 'deal.stage_exited',
      jsonb_build_object(
        'deal_id', new.id,
        'stage_id', old.stage_id,
        'to_stage_id', new.stage_id,
        'pipeline_id', new.pipeline_id,
        'source', new.source,
        'utm_campaign', new.utm_campaign,
        'assigned_user_id', new.assigned_user_id
      ),
      'exit:' || new.id::text || ':' || old.stage_id::text || ':'
        || extract(epoch from old.stage_entered_at)::bigint::text
    )
    on conflict (org_id, cle_unicite) do nothing;
  end if;

  insert into public.pipeline_events (org_id, deal_id, type, payload, cle_unicite)
  values (
    new.org_id, new.id, 'deal.stage_entered',
    jsonb_build_object(
      'deal_id', new.id,
      'stage_id', new.stage_id,
      'from_stage_id', case when tg_op = 'UPDATE' then old.stage_id else null end,
      'pipeline_id', new.pipeline_id,
      'source', new.source,
      'utm_campaign', new.utm_campaign,
      'assigned_user_id', new.assigned_user_id
    ),
    'enter:' || new.id::text || ':' || new.stage_id::text || ':'
      || extract(epoch from new.stage_entered_at)::bigint::text
  )
  on conflict (org_id, cle_unicite) do nothing;

  return null;
end;
$$;


--
-- Name: deals_figer_premier_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_figer_premier_contact() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.first_contacted_at is not null then
    new.first_contacted_at := old.first_contacted_at;
  end if;
  return new;
end;
$$;


--
-- Name: deals_horodater_etape(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_horodater_etape() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind public.pipeline_stage_kind;
begin
  if tg_op = 'UPDATE' and new.stage_id is not distinct from old.stage_id then
    return new;
  end if;

  select kind into v_kind from public.pipeline_stages where id = new.stage_id;

  new.stage_entered_at := now();
  new.last_activity_at := now();

  if v_kind = 'won' then
    new.won_at := coalesce(new.won_at, now());
    new.lost_at := null;
    new.lost_reason := null;
  elsif v_kind = 'lost' then
    new.lost_at := coalesce(new.lost_at, now());
    new.won_at := null;
    if tg_op = 'UPDATE' then
      new.lost_from_stage_id := coalesce(new.lost_from_stage_id, old.stage_id);
    end if;
  else
    new.won_at := null;
    new.lost_at := null;
    new.lost_reason := null;
  end if;

  return new;
end;
$$;


--
-- Name: deals_mesurer_glissement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_mesurer_glissement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE'
     and new.expected_close_date is distinct from old.expected_close_date
     and old.expected_close_date is not null
     and new.expected_close_date is not null
     and new.expected_close_date > old.expected_close_date
  then
    new.slippage_count := coalesce(old.slippage_count, 0) + 1;
    new.slippage_days := coalesce(old.slippage_days, 0)
      + (new.expected_close_date - old.expected_close_date);
  end if;
  return new;
end;
$$;


--
-- Name: deals_verifier_etape(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_verifier_etape() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pipeline uuid;
  v_archivee timestamptz;
begin
  select pipeline_id, archived_at into v_pipeline, v_archivee
  from public.pipeline_stages
  where id = new.stage_id and org_id = new.org_id;

  if v_pipeline is null then
    raise exception 'Étape introuvable dans cette organisation';
  end if;

  if v_pipeline <> new.pipeline_id then
    raise exception 'L''étape appartient à un autre pipeline';
  end if;

  -- Une étape archivée ne reçoit plus de deal (mais garde les siens).
  if v_archivee is not null
     and (tg_op = 'INSERT' or new.stage_id is distinct from old.stage_id) then
    raise exception 'Cette étape est archivée : elle ne peut plus recevoir de deal';
  end if;

  return new;
end;
$$;


--
-- Name: delete_client_cascade(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_client_cascade(p_org_id uuid, p_client_id uuid, p_deleted_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_client integer := 0;
  v_jobs integer := 0;
  v_pipeline_deals integer := 0;
  v_invoices integer := 0;
  v_invoice_items integer := 0;
  v_payments integer := 0;
  v_schedule_events integer := 0;
  v_job_line_items integer := 0;
BEGIN
  -- Garde : un appel utilisateur exige owner/admin de l'org.
  IF v_uid IS NOT NULL AND NOT public.has_org_admin_role(v_uid, p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can permanently delete clients' USING errcode = '42501';
  END IF;

  DELETE FROM public.schedule_events
  WHERE job_id IN (SELECT id FROM public.jobs WHERE client_id = p_client_id AND org_id = p_org_id);
  GET DIAGNOSTICS v_schedule_events = ROW_COUNT;

  DELETE FROM public.job_line_items
  WHERE job_id IN (SELECT id FROM public.jobs WHERE client_id = p_client_id AND org_id = p_org_id);
  GET DIAGNOSTICS v_job_line_items = ROW_COUNT;

  DELETE FROM public.payments
  WHERE invoice_id IN (SELECT id FROM public.invoices WHERE client_id = p_client_id AND org_id = p_org_id);
  GET DIAGNOSTICS v_payments = ROW_COUNT;

  DELETE FROM public.invoice_items
  WHERE invoice_id IN (SELECT id FROM public.invoices WHERE client_id = p_client_id AND org_id = p_org_id);
  GET DIAGNOSTICS v_invoice_items = ROW_COUNT;

  DELETE FROM public.invoices WHERE client_id = p_client_id AND org_id = p_org_id;
  GET DIAGNOSTICS v_invoices = ROW_COUNT;

  DELETE FROM public.pipeline_deals
  WHERE client_id = p_client_id AND org_id = p_org_id;
  GET DIAGNOSTICS v_pipeline_deals = ROW_COUNT;

  DELETE FROM public.jobs WHERE client_id = p_client_id AND org_id = p_org_id;
  GET DIAGNOSTICS v_jobs = ROW_COUNT;

  DELETE FROM public.clients WHERE id = p_client_id AND org_id = p_org_id;
  GET DIAGNOSTICS v_client = ROW_COUNT;

  RETURN jsonb_build_object(
    'client', v_client,
    'jobs', v_jobs,
    'leads', 0,
    'pipeline_deals', v_pipeline_deals,
    'invoices', v_invoices,
    'invoice_items', v_invoice_items,
    'payments', v_payments,
    'schedule_events', v_schedule_events,
    'job_line_items', v_job_line_items
  );
END;
$$;


--
-- Name: delete_invoice_cascade(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_invoice_cascade(p_org_id uuid, p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.has_org_admin_role(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can permanently delete invoices' USING errcode = '42501';
  END IF;

  -- Delete payments linked to this invoice
  DELETE FROM public.payments WHERE invoice_id = p_invoice_id AND org_id = p_org_id;

  -- DB ON DELETE CASCADE handles: invoice_items
  DELETE FROM public.invoices WHERE id = p_invoice_id AND org_id = p_org_id;
END;
$$;


--
-- Name: delete_job_cascade(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_job_cascade(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_events int := 0;
  v_line_items int := 0;
BEGIN
  IF v_uid IS NOT NULL AND NOT public.has_org_admin_role(v_uid, p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can permanently delete jobs' USING errcode = '42501';
  END IF;

  -- Unlink quotes (don't delete them — they belong to the client)
  UPDATE public.quotes SET job_id = NULL WHERE job_id = p_job_id AND org_id = p_org_id;

  -- Delete schedule events
  DELETE FROM public.schedule_events WHERE job_id = p_job_id AND org_id = p_org_id;
  GET DIAGNOSTICS v_events = ROW_COUNT;

  -- Delete line items (scopées via le job de l'org)
  DELETE FROM public.job_line_items
  WHERE job_id = p_job_id
    AND EXISTS (SELECT 1 FROM public.jobs j WHERE j.id = p_job_id AND j.org_id = p_org_id);
  GET DIAGNOSTICS v_line_items = ROW_COUNT;

  -- Delete the job itself
  DELETE FROM public.jobs WHERE id = p_job_id AND org_id = p_org_id;

  RETURN jsonb_build_object(
    'job', p_job_id,
    'schedule_events', v_events,
    'line_items', v_line_items
  );
END;
$$;


--
-- Name: delete_lead_and_optional_client(uuid, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_lead_and_optional_client(p_org_id uuid, p_lead_id uuid, p_also_delete_client boolean DEFAULT false, p_deleted_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := coalesce(auth.uid(), p_deleted_by);
  v_deals int := 0;
  v_tasks int := 0;
  v_lead_lists int := 0;
  v_job_intents int := 0;
  v_client_deleted int := 0;
  v_client_result jsonb := '{}'::jsonb;
  v_exists int := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING errcode = '42501';
  END IF;
  IF p_org_id IS NULL OR p_lead_id IS NULL THEN
    RAISE EXCEPTION 'p_org_id and p_lead_id are required' USING errcode = '22023';
  END IF;
  IF NOT public.has_org_membership(v_uid, p_org_id) THEN
    RAISE EXCEPTION 'Not a member of this org' USING errcode = '42501';
  END IF;

  SELECT count(*) INTO v_exists
  FROM public.clients WHERE id = p_lead_id AND org_id = p_org_id;
  IF v_exists = 0 THEN
    RAISE EXCEPTION 'Lead not found' USING errcode = 'P0002';
  END IF;

  IF to_regclass('public.tasks') IS NOT NULL THEN
    BEGIN
      EXECUTE 'delete from public.tasks where org_id = $1 and lead_id = $2' USING p_org_id, p_lead_id;
      GET DIAGNOSTICS v_tasks = ROW_COUNT;
    EXCEPTION WHEN others THEN v_tasks := 0; END;
  END IF;

  IF to_regclass('public.lead_lists') IS NOT NULL THEN
    BEGIN
      EXECUTE 'delete from public.lead_lists where lead_id = $1' USING p_lead_id;
      GET DIAGNOSTICS v_lead_lists = ROW_COUNT;
    EXCEPTION WHEN others THEN v_lead_lists := 0; END;
  END IF;

  DELETE FROM public.job_intents WHERE org_id = p_org_id AND lead_id = p_lead_id;
  GET DIAGNOSTICS v_job_intents = ROW_COUNT;

  DELETE FROM public.pipeline_deals WHERE org_id = p_org_id AND lead_id = p_lead_id;
  GET DIAGNOSTICS v_deals = ROW_COUNT;

  IF p_also_delete_client THEN
    v_client_result := public.delete_client_cascade(p_org_id, p_lead_id, v_uid);
    v_client_deleted := coalesce((v_client_result->>'client')::int, 0);
  END IF;

  INSERT INTO public.audit_events (org_id, actor_id, action, entity_type, entity_id, metadata)
  VALUES (
    p_org_id, v_uid, 'lead.deleted', 'lead', p_lead_id,
    jsonb_build_object(
      'deals', v_deals, 'tasks', v_tasks, 'lead_lists', v_lead_lists,
      'job_intents', v_job_intents, 'client_deleted', v_client_deleted
    )
  );

  RETURN jsonb_build_object(
    'lead', 1,
    'deals', v_deals,
    'jobs_unlinked', 0,
    'tasks', v_tasks,
    'lead_lists', v_lead_lists,
    'job_intents', v_job_intents,
    'client_deleted', v_client_deleted
  );
END;
$_$;


--
-- Name: delete_lead_cascade(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_lead_cascade(p_org_id uuid, p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_deals int := 0;
BEGIN
  IF v_uid IS NOT NULL AND NOT public.has_org_admin_role(v_uid, p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can permanently delete leads' USING errcode = '42501';
  END IF;

  DELETE FROM public.pipeline_deals WHERE lead_id = p_lead_id AND org_id = p_org_id;
  GET DIAGNOSTICS v_deals = ROW_COUNT;

  BEGIN EXECUTE 'delete from public.tasks where lead_id = $1 and org_id = $2' USING p_lead_id, p_org_id; EXCEPTION WHEN others THEN NULL; END;
  BEGIN EXECUTE 'delete from public.lead_lists where lead_id = $1' USING p_lead_id; EXCEPTION WHEN others THEN NULL; END;
  DELETE FROM public.job_intents WHERE lead_id = p_lead_id AND org_id = p_org_id;

  RETURN jsonb_build_object('deals', v_deals);
END;
$_$;


--
-- Name: delete_quote_cascade(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_quote_cascade(p_org_id uuid, p_quote_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.has_org_admin_role(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can permanently delete quotes' USING errcode = '42501';
  END IF;

  -- DB ON DELETE CASCADE handles: quote_line_items, quote_sections,
  -- quote_send_log, quote_status_history, quote_attachments
  DELETE FROM public.quotes WHERE id = p_quote_id AND org_id = p_org_id;
END;
$$;


--
-- Name: detect_brute_force(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_brute_force(p_user_id uuid, p_window_minutes integer DEFAULT 15, p_threshold integer DEFAULT 5) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*) >= p_threshold
  FROM login_history
  WHERE user_id = p_user_id AND success = false
    AND created_at > now() - (p_window_minutes || ' minutes')::interval;
$$;


--
-- Name: FUNCTION detect_brute_force(p_user_id uuid, p_window_minutes integer, p_threshold integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.detect_brute_force(p_user_id uuid, p_window_minutes integer, p_threshold integer) IS 'Detect brute force login attempts for a user';


--
-- Name: detect_excessive_exports(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_excessive_exports(p_user_id uuid, p_org_id uuid, p_window_minutes integer DEFAULT 10, p_threshold integer DEFAULT 3) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*) >= p_threshold FROM audit_events
  WHERE actor_id = p_user_id AND org_id = p_org_id
    AND action IN ('export', 'bulk_export', 'download')
    AND created_at > now() - (p_window_minutes || ' minutes')::interval;
$$;


--
-- Name: detect_impossible_travel(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_impossible_travel(p_user_id uuid, p_country text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      SELECT EXISTS (SELECT 1 FROM login_history WHERE user_id = p_user_id AND success = true AND country_code IS NOT NULL AND country_code != p_country AND created_at > now() - interval '1 hour');
    $$;


--
-- Name: FUNCTION detect_impossible_travel(p_user_id uuid, p_country text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.detect_impossible_travel(p_user_id uuid, p_country text) IS 'Detect logins from different countries within 1 hour';


--
-- Name: detect_login_anomalies(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_login_anomalies(p_minutes integer DEFAULT 15) RETURNS TABLE(kind text, key text, count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with attempts as (
    select email, ip_address from public.failed_login_attempts
     where created_at > now() - make_interval(mins => p_minutes)
  )
  select 'brute_force_email'::text, email, count(*)::bigint
    from attempts where email <> '' group by email having count(*) >= 5
  union all
  select 'brute_force_ip'::text, host(ip_address), count(*)::bigint
    from attempts where ip_address is not null group by ip_address having count(*) >= 20;
$$;


--
-- Name: detect_mass_deletion(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_mass_deletion(p_user_id uuid, p_org_id uuid, p_window_minutes integer DEFAULT 5, p_threshold integer DEFAULT 20) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*) >= p_threshold FROM audit_events
  WHERE actor_id = p_user_id AND org_id = p_org_id AND action = 'delete'
    AND created_at > now() - (p_window_minutes || ' minutes')::interval;
$$;


--
-- Name: email_deliveries_enregistrer_suivi(text, text, timestamp with time zone, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_deliveries_enregistrer_suivi(p_email_id text, p_evenement text, p_quand timestamp with time zone, p_url text DEFAULT NULL::text, p_types_exclus text[] DEFAULT '{}'::text[]) RETURNS TABLE(id uuid, org_id uuid, entity_type text, entity_id uuid)
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  update public.email_deliveries d
  set
    opened_at        = case when p_evenement = 'opened'  then coalesce(d.opened_at, p_quand)  else d.opened_at  end,
    open_count       = d.open_count  + (p_evenement = 'opened')::int,
    clicked_at       = case when p_evenement = 'clicked' then coalesce(d.clicked_at, p_quand) else d.clicked_at end,
    click_count      = d.click_count + (p_evenement = 'clicked')::int,
    last_clicked_url = case when p_evenement = 'clicked' and p_url is not null then left(p_url, 2000) else d.last_clicked_url end
  where p_evenement in ('opened', 'clicked')
    and (d.message_id = p_email_id or d.message_id like p_email_id || '#%')
    and d.entity_type is not null
    and not (d.entity_type = any (coalesce(p_types_exclus, '{}'::text[])))
  returning d.id, d.org_id, d.entity_type, d.entity_id;
$$;


--
-- Name: FUNCTION email_deliveries_enregistrer_suivi(p_email_id text, p_evenement text, p_quand timestamp with time zone, p_url text, p_types_exclus text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.email_deliveries_enregistrer_suivi(p_email_id text, p_evenement text, p_quand timestamp with time zone, p_url text, p_types_exclus text[]) IS 'Webhook Resend (service_role) : première ouverture / premier clic + compteurs, jamais sur les courriels de compte Lume.';


--
-- Name: enforce_invoice_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_invoice_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(old.status, 'draft') = 'draft' then
    return new;
  end if;

  if new.total_cents    is distinct from old.total_cents
  or new.subtotal_cents is distinct from old.subtotal_cents
  or new.tax_cents      is distinct from old.tax_cents
  or new.invoice_number is distinct from old.invoice_number
  or (new.client_id is distinct from old.client_id
      and coalesce(current_setting('app.fusion_clients', true), '') <> 'on')
  or new.due_date       is distinct from old.due_date
  or new.issued_at      is distinct from old.issued_at
  or new.subject        is distinct from old.subject
  then
    raise exception
      'Cette facture a deja ete emise (statut %). Ses montants et son numero ne peuvent plus etre modifies : creez une note de credit ou annulez-la, puis emettez une nouvelle facture.',
      old.status
      using errcode = '42501';
  end if;

  return new;
end $$;


--
-- Name: enforce_membership_role_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_membership_role_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sensitive_change boolean;
begin
  v_sensitive_change :=
       (new.role        is distinct from old.role)
    or (new.permissions is distinct from old.permissions)
    or (new.scope       is distinct from old.scope)
    or (new.status      is distinct from old.status);

  if v_sensitive_change then
    -- Opérations serveur (service_role) : pas de session utilisateur.
    if auth.uid() is null then
      return new;
    end if;
    -- Personne ne modifie ses PROPRES droits (rôle, permissions, portée, statut).
    if auth.uid() = old.user_id then
      raise exception 'You cannot change your own role, permissions or status.' using errcode = '42501';
    end if;
    -- Seuls owner/admin (actifs) modifient les droits des autres.
    if not public.has_org_admin_role(auth.uid(), new.org_id) then
      raise exception 'Only org owners or admins can change member roles or permissions.' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_soft_delete_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_soft_delete_admin() RETURNS trigger
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF old.deleted_at IS NULL AND new.deleted_at IS NOT NULL THEN
    -- Allow service_role (no auth context)
    IF auth.uid() IS NULL THEN
      RETURN new;
    END IF;
    -- Allow any ACTIVE org member (not just admin/owner)
    IF EXISTS (SELECT 1 FROM memberships WHERE user_id = auth.uid() AND org_id = new.org_id
                AND coalesce(status, 'active') = 'active') THEN
      IF new.deleted_by IS NULL THEN
        new.deleted_by := auth.uid();
      END IF;
      RETURN new;
    END IF;
    RAISE EXCEPTION 'Only owner/admin can soft-delete records.' USING errcode = '42501';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: enforce_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tenant() RETURNS trigger
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
begin
  v_org := public.current_org_id();
  if v_org is null then
    raise exception 'No org membership found for current user' using errcode = '42501';
  end if;

  if to_jsonb(new) ? 'org_id' then
    new.org_id := v_org;
  end if;

  if to_jsonb(new) ? 'created_by' and new.created_by is null then
    new.created_by := auth.uid();
  end if;

  return new;
end;
$$;


