--
-- Name: enforce_zone_exclusivity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_zone_exclusivity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid; v_role text; z record;
begin
  v_uid := auth.uid();
  if v_uid is null then return new; end if;
  if new.lat is null or new.lng is null then return new; end if;
  select role into v_role from public.memberships
   where org_id = new.org_id and user_id = v_uid limit 1;
  if v_role in ('owner', 'admin') then return new; end if;
  for z in
    select name, polygon_geojson from public.field_territories
     where org_id = new.org_id and deleted_at is null
       and assigned_user_id is not null and assigned_user_id <> v_uid
  loop
    if public._point_in_zone_ring(new.lng, new.lat, z.polygon_geojson) then
      raise exception 'Zone « % » réservée — assignée à un autre représentant.', z.name
        using errcode = 'P0001';
    end if;
  end loop;
  return new;
end $$;


--
-- Name: ensure_field_pin_for_client(); Type: FUNCTION; Schema: public; Owner: -
