--
-- Name: ensure_payment_settings_row(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_payment_settings_row(p_org uuid) RETURNS public.payment_provider_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.payment_provider_settings;
begin
  if p_org is null then
    raise exception 'p_org is required';
  end if;

  insert into public.payment_provider_settings (org_id)
  values (p_org)
  on conflict (org_id) do nothing;

  select *
    into v_row
    from public.payment_provider_settings
   where org_id = p_org;

  return v_row;
end;
$$;


--
-- Name: execute_scheduled_member_deletions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_scheduled_member_deletions() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rec record;
  v_count bigint := 0;
begin
  for v_rec in
    select id, org_id, user_id from public.team_members
     where deletion_scheduled_at is not null
       and deletion_scheduled_at < now()
  loop
    -- Delete memberships (FK cascade from team_members if configured, else explicit)
    delete from public.memberships where user_id = v_rec.user_id and org_id = v_rec.org_id;
    -- Delete the team_member row
    delete from public.team_members where id = v_rec.id;

    insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
    values (v_rec.org_id, null, 'execute_hard_delete', 'team_member', v_rec.id,
      jsonb_build_object('target_user', v_rec.user_id, 'method', 'scheduled_30d'));

    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;


--
-- Name: expire_ai_reservations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_ai_reservations(p_minutes integer DEFAULT 5) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n integer := 0;
  r record;
begin
  for r in
    select id, org_id, period, cents from public.ai_reservations
     where settled_at is null and created_at < now() - make_interval(mins => greatest(1, p_minutes))
     for update skip locked
  loop
    update public.ai_reservations set settled_at = now() where id = r.id;
    update public.ai_usage_monthly
       set reserved_cents = greatest(0, reserved_cents - r.cents), updated_at = now()
     where org_id = r.org_id and period = r.period;
    n := n + 1;
  end loop;
  return n;
end;
$$;


--
-- Name: export_client_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_client_data(p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid;
  v_result jsonb;
begin
  select org_id into v_org from public.clients where id = p_client_id;
  if v_org is null then
    raise exception 'Client not found';
  end if;

  -- Appel utilisateur : garde d'appartenance. Appel serveur (auth.uid() NULL) :
  -- l'autorisation est faite en amont dans server/routes/dsr.ts.
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'exported_at', now(),
    'client_id',   p_client_id,
    'client',      (select to_jsonb(c) from public.clients c where c.id = p_client_id),
    'contact',     (select to_jsonb(co) from public.contacts co where co.id = (select contact_id from public.clients where id = p_client_id)),
    'jobs',        (select coalesce(jsonb_agg(to_jsonb(j)), '[]'::jsonb) from public.jobs j where j.client_id = p_client_id),
    'invoices',    (select coalesce(jsonb_agg(to_jsonb(i)), '[]'::jsonb) from public.invoices i where i.client_id = p_client_id),
    'payments',    (select coalesce(jsonb_agg(to_jsonb(pm)), '[]'::jsonb) from public.payments pm where pm.client_id = p_client_id),
    'consents',    (select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) from public.consents c where c.subject_type='client' and c.subject_id = p_client_id),
    -- champs personnalisés (2026-09-26)
    'custom_fields', public.cf_valeurs_lisibles(p_client_id)
  ) into v_result;

  insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
  values (v_org, auth.uid(), 'dsr_export', 'client', p_client_id, '{}'::jsonb);

  return v_result;
end $$;


--
-- Name: FUNCTION export_client_data(p_client_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.export_client_data(p_client_id uuid) IS 'Loi 25 art. 27 / RGPD art. 20 — export de portabilite d''un client. Garde d''appartenance sur appel utilisateur ; sur appel serveur (auth.uid() NULL) l''autorisation est faite dans server/routes/dsr.ts.';


--
-- Name: export_user_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_user_data(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_result jsonb;
  v_org    uuid;
begin
  -- Appel serveur (service_role) : auth.uid() est NULL et l'autorisation est
  -- faite en amont dans server/routes/dsr.ts. Appel utilisateur : la
  -- verification v_caller != p_user_id ci-dessous s'applique normalement.
  if v_caller is not null and v_caller <> p_user_id then
    if not exists (
      select 1 from public.memberships m1
      join public.memberships m2 on m1.org_id = m2.org_id
      where m1.user_id = v_caller
        and m2.user_id = p_user_id
        and public.has_org_admin_role(v_caller, m1.org_id)
    ) then
      raise exception 'Not authorized to export this user data' using errcode = '42501';
    end if;
  end if;

  select jsonb_build_object(
    'exported_at',       now(),
    'user_id',           p_user_id,
    'profile',           (select to_jsonb(p) from public.profiles p where p.id = p_user_id),
    'memberships',       (select coalesce(jsonb_agg(to_jsonb(m)), '[]'::jsonb) from public.memberships m where m.user_id = p_user_id),
    'consents',          (select coalesce(jsonb_agg(to_jsonb(c) order by c.created_at), '[]'::jsonb) from public.consents c where c.subject_type = 'user' and c.subject_id = p_user_id),
    'audit_events_as_actor', (select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at), '[]'::jsonb) from public.audit_events a where a.actor_id = p_user_id),
    'dsar_requests',     (select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at), '[]'::jsonb) from public.dsar_requests d where d.requested_by = p_user_id or (d.subject_type='user' and d.subject_id = p_user_id))
  ) into v_result;

  -- N3.1 — org_id etait code en dur a NULL : la ligne d'audit n'etait
  -- rattachee a aucun tenant, donc invisible dans toute consultation filtree.
  select m.org_id into v_org
    from public.memberships m
   where m.user_id = p_user_id
     and (v_caller is null or m.org_id in (
           select m2.org_id from public.memberships m2 where m2.user_id = v_caller))
   order by m.created_at
   limit 1;

  if v_org is null then
    select m.org_id into v_org
      from public.memberships m
     where m.user_id = p_user_id
     order by m.created_at
     limit 1;
  end if;

  -- Compte sans aucune org : on n'echoue pas. L'export est un droit legal
  -- (Loi 25 art. 27), il ne doit pas dependre de sa propre journalisation.
  if v_org is not null then
    insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
    values (v_org, v_caller, 'dsr_export', 'user', p_user_id,
            jsonb_build_object('requested_by', v_caller));
  end if;

  return v_result;
end $$;


--
-- Name: FUNCTION export_user_data(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.export_user_data(p_user_id uuid) IS 'Loi 25 art. 27 / RGPD art. 20 — export de portabilite d''un utilisateur. Garde d''appartenance sur appel utilisateur ; sur appel serveur (auth.uid() NULL) l''autorisation est faite dans server/routes/dsr.ts.';


--
-- Name: field_compute_house_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_compute_house_score(p_house_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_visit_count       int;
  v_has_lead_status   boolean;
  v_last_activity     timestamptz;
BEGIN
  -- Count events in the last 30 days for this house
  SELECT COUNT(*)
  INTO v_visit_count
  FROM field_house_events
  WHERE house_id = p_house_id
    AND created_at >= now() - interval '30 days';

  -- Check whether the house currently has a lead-level status
  SELECT
    (current_status = 'lead'),
    last_activity_at
  INTO v_has_lead_status, v_last_activity
  FROM field_house_profiles
  WHERE id = p_house_id;

  -- Score logic
  IF v_visit_count >= 3 AND v_has_lead_status IS TRUE THEN
    RETURN 'hot';
  ELSIF v_visit_count >= 2
     OR (v_last_activity IS NOT NULL AND v_last_activity >= now() - interval '7 days')
  THEN
    RETURN 'warm';
  ELSE
    RETURN 'cold';
  END IF;
END;
$$;


--
-- Name: field_compute_next_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_compute_next_action(p_house_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status text;
BEGIN
  SELECT current_status
  INTO v_status
  FROM field_house_profiles
  WHERE id = p_house_id;

  RETURN CASE v_status
    WHEN 'no_answer'   THEN 'Revisit in 2 days'
    WHEN 'lead'        THEN 'Follow up'
    WHEN 'quote_sent'  THEN 'Check if quote opened'
    WHEN 'callback'    THEN 'Call back'
    WHEN 'sale'        THEN 'Send thank you'
    ELSE NULL
  END;
END;
$$;


--
-- Name: fill_property_id_from_job_or_client(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_property_id_from_job_or_client() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.property_id is null and new.job_id is not null then
    select j.property_id into new.property_id from public.jobs j where j.id = new.job_id;
  end if;
  if new.property_id is null and new.client_id is not null then
    new.property_id := public.resolve_primary_property(new.client_id);
  end if;
  return new;
end;
$$;


--
-- Name: find_duplicate_clients(uuid, text, text, text, text, real); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_duplicate_clients(p_org_id uuid, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_threshold real DEFAULT 0.3) RETURNS TABLE(client_id uuid, first_name text, last_name text, email text, phone text, company text, similarity_score real)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id, c.first_name, c.last_name, c.email, c.phone, c.company,
    GREATEST(
      CASE WHEN p_email IS NOT NULL AND c.email IS NOT NULL THEN
        CASE WHEN lower(c.email) = lower(p_email) THEN 1.0 ELSE similarity(c.email, p_email) END
      ELSE 0 END,
      CASE WHEN p_phone IS NOT NULL AND c.phone IS NOT NULL THEN
        similarity(regexp_replace(c.phone, '[^0-9]', '', 'g'), regexp_replace(p_phone, '[^0-9]', '', 'g'))
      ELSE 0 END,
      CASE WHEN p_first_name IS NOT NULL AND p_last_name IS NOT NULL THEN
        (similarity(c.first_name, p_first_name) + similarity(c.last_name, p_last_name)) / 2.0
      ELSE 0 END
    )::real AS similarity_score
  FROM clients c
  WHERE c.org_id = p_org_id AND c.deleted_at IS NULL
    AND (
      (p_email IS NOT NULL AND c.email IS NOT NULL AND (lower(c.email) = lower(p_email) OR similarity(c.email, p_email) > p_threshold))
      OR (p_phone IS NOT NULL AND c.phone IS NOT NULL AND similarity(regexp_replace(c.phone, '[^0-9]', '', 'g'), regexp_replace(p_phone, '[^0-9]', '', 'g')) > p_threshold)
      OR (p_first_name IS NOT NULL AND p_last_name IS NOT NULL AND (similarity(c.first_name, p_first_name) + similarity(c.last_name, p_last_name)) / 2.0 > p_threshold)
    )
  ORDER BY similarity_score DESC
  LIMIT 10;
END;
$$;


--
-- Name: finish_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_job(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_job_id uuid;
begin
  if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if not public.crm_is_org_admin(p_org_id, v_user) then raise exception 'Only owner/admin can finish job' using errcode='42501'; end if;

  update public.jobs
  set status = 'completed',
      completed_at = coalesce(completed_at, now()),
      updated_at = now()
  where id = p_job_id and org_id = p_org_id and deleted_at is null
  returning id into v_job_id;

  if v_job_id is null then
    return jsonb_build_object('ok', false, 'error', 'Job not found');
  end if;

  return jsonb_build_object('ok', true, 'job_id', v_job_id);
end;
$$;


--
-- Name: finish_job_and_prepare_invoice(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_job_and_prepare_invoice(p_org_id uuid, p_job_id uuid) RETURNS TABLE(ok boolean, invoice_id uuid, already_exists boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_org_id uuid := coalesce(p_org_id, public.current_org_id());
  v_payload jsonb := '{}'::jsonb;
  v_invoice_id uuid;
  v_already_exists boolean := false;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if v_org_id is null or p_job_id is null then
    raise exception 'p_org_id and p_job_id are required' using errcode = '22023';
  end if;

  -- Allow every CRM member in org to finish jobs.
  if not public.has_org_membership(v_uid, v_org_id) then
    raise exception 'Forbidden for this organization.' using errcode = '42501';
  end if;

  perform 1
  from public.jobs j
  where j.id = p_job_id
    and j.org_id = v_org_id
    and j.deleted_at is null
  for update;

  if not found then
    raise exception 'Job not found.' using errcode = 'P0002';
  end if;

  update public.jobs
  set status = 'completed',
      completed_at = coalesce(completed_at, now()),
      updated_at = now()
  where id = p_job_id
    and org_id = v_org_id
    and deleted_at is null;

  if to_regprocedure('public.create_invoice_from_job(uuid,uuid,boolean)') is not null then
    execute 'select public.create_invoice_from_job($1,$2,$3)'
      into v_payload
      using v_org_id, p_job_id, false;
  elsif to_regprocedure('public.create_invoice_from_job(uuid,uuid)') is not null then
    execute 'select public.create_invoice_from_job($1,$2)'
      into v_payload
      using v_org_id, p_job_id;
  end if;

  begin
    v_invoice_id := nullif(v_payload->>'invoice_id', '')::uuid;
  exception when others then
    v_invoice_id := null;
  end;

  if v_invoice_id is null then
    select i.id
      into v_invoice_id
    from public.invoices i
    where i.org_id = v_org_id
      and i.job_id = p_job_id
      and i.deleted_at is null
    order by i.created_at desc
    limit 1;

    v_already_exists := v_invoice_id is not null;
  else
    v_already_exists := coalesce((v_payload->>'already_exists')::boolean, false);
  end if;

  if v_invoice_id is null then
    raise exception 'Unable to prepare invoice from job.' using errcode = 'P0001';
  end if;

  return query
  select true, v_invoice_id, v_already_exists;
end;
$_$;


--
-- Name: fn_field_daily_stats_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_field_daily_stats_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d date := (NEW.created_at AT TIME ZONE 'UTC')::date;
BEGIN
  INSERT INTO public.field_daily_stats (org_id, user_id, date,
    knocks, no_answers, leads, quotes_sent, sales, callbacks)
  VALUES (NEW.org_id, NEW.user_id, d,
    CASE WHEN NEW.event_type = 'knock'      THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'no_answer'  THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'lead'       THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'quote_sent' THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'sale'       THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'callback'   THEN 1 ELSE 0 END)
  ON CONFLICT (org_id, user_id, date) DO UPDATE SET
    knocks      = public.field_daily_stats.knocks      + EXCLUDED.knocks,
    no_answers  = public.field_daily_stats.no_answers  + EXCLUDED.no_answers,
    leads       = public.field_daily_stats.leads       + EXCLUDED.leads,
    quotes_sent = public.field_daily_stats.quotes_sent + EXCLUDED.quotes_sent,
    sales       = public.field_daily_stats.sales       + EXCLUDED.sales,
    callbacks   = public.field_daily_stats.callbacks   + EXCLUDED.callbacks;

  -- Recompute conversion rate (sales / knocks).
  UPDATE public.field_daily_stats
     SET conversion_rate = CASE WHEN knocks > 0
            THEN ROUND((sales::numeric / knocks::numeric) * 100, 2) ELSE 0 END
   WHERE org_id = NEW.org_id AND user_id = NEW.user_id AND date = d;

  RETURN NEW;
END;
$$;


--
-- Name: fn_push_on_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_push_on_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'net'
    AS $$
DECLARE
  msgs jsonb;
BEGIN
  -- Build one Expo push message per target device (only Expo tokens).
  SELECT COALESCE(
    jsonb_agg(jsonb_build_object(
      'to', pt.token,
      'title', NEW.title,
      'body', COALESCE(NEW.body, ''),
      'sound', 'default'
    )), '[]'::jsonb)
  INTO msgs
  FROM public.push_tokens pt
  WHERE pt.org_id = NEW.org_id
    AND (NEW.user_id IS NULL OR pt.user_id = NEW.user_id)
    AND pt.token LIKE 'ExponentPushToken%';

  IF msgs <> '[]'::jsonb THEN
    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := msgs
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: format_montreal_date(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.format_montreal_date(ts timestamp with time zone, fmt text DEFAULT 'YYYY-MM-DD HH24:MI'::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT to_char(ts AT TIME ZONE 'America/Toronto', fmt);
$$;


--
-- Name: fusionner_clients(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fusionner_clients(p_org uuid, p_garder uuid, p_absorber uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_garder clients%rowtype;
  v_absorber clients%rowtype;
  v_cible record;
  v_n int;
  v_total int := 0;
  v_detail jsonb := '{}'::jsonb;
  v_ignores int := 0;
  v_row record;
begin
  if p_garder = p_absorber then
    raise exception 'fusionner_clients: les deux fiches sont identiques';
  end if;
  if v_uid is not null and not public.member_has_permission(v_uid, p_org, 'clients.delete') then
    raise exception 'fusionner_clients: permission clients.delete requise' using errcode = '42501';
  end if;
  select * into v_garder from clients where id = p_garder and org_id = p_org and deleted_at is null for update;
  if not found then raise exception 'fusionner_clients: fiche à garder introuvable'; end if;
  select * into v_absorber from clients where id = p_absorber and org_id = p_org and deleted_at is null for update;
  if not found then raise exception 'fusionner_clients: fiche à absorber introuvable'; end if;

  -- Drapeau local à la transaction : le trigger d'immuabilité laisse passer client_id (et rien d'autre).
  perform set_config('app.fusion_clients', 'on', true);

  for v_cible in
    select c.conrelid::regclass::text as tbl, a.attname as col
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any(c.conkey)
     where c.contype = 'f' and c.confrelid = 'public.clients'::regclass
       and a.attname <> 'org_id'
     group by 1, 2
  loop
    begin
      execute format('update %s set %I = $1 where %I = $2', v_cible.tbl, v_cible.col, v_cible.col) using p_garder, p_absorber;
      get diagnostics v_n = row_count;
    exception when unique_violation then
      v_n := 0;
      for v_row in execute format('select ctid from %s where %I = $1', v_cible.tbl, v_cible.col) using p_absorber loop
        begin
          execute format('update %s set %I = $1 where ctid = $2', v_cible.tbl, v_cible.col) using p_garder, v_row.ctid;
          v_n := v_n + 1;
        exception when unique_violation then
          v_ignores := v_ignores + 1;
        end;
      end loop;
    end;
    if v_n > 0 then
      v_detail := v_detail || jsonb_build_object(v_cible.tbl || '.' || v_cible.col, v_n);
      v_total := v_total + v_n;
    end if;
  end loop;

  update clients set
    email      = coalesce(nullif(email, ''), v_absorber.email),
    phone      = coalesce(nullif(phone, ''), v_absorber.phone),
    company    = coalesce(nullif(company, ''), v_absorber.company),
    address    = coalesce(nullif(address, ''), v_absorber.address),
    city       = coalesce(nullif(city, ''), v_absorber.city),
    notes      = case
                   when coalesce(v_absorber.notes, '') = '' then notes
                   when coalesce(notes, '') = '' then v_absorber.notes
                   else notes || E'\n' || v_absorber.notes
                 end,
    updated_at = now()
  where id = p_garder;

  update clients set deleted_at = now(), updated_at = now() where id = p_absorber;

  return jsonb_build_object(
    'merged', true, 'kept_client_id', p_garder, 'absorbed_client_id', p_absorber,
    'rows_reassigned', v_total, 'rows_skipped_unique', v_ignores, 'detail', v_detail
  );
end;
$_$;


--
-- Name: FUNCTION fusionner_clients(p_org uuid, p_garder uuid, p_absorber uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fusionner_clients(p_org uuid, p_garder uuid, p_absorber uuid) IS 'Fusionne deux fiches clients : réassigne toute clé étrangère vers la fiche gardée (catalogue relu), complète ses champs vides, efface en douceur l''absorbée. clients.delete requis (ou service_role).';


--
-- Name: garde_suppression_douce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.garde_suppression_douce() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cle text := tg_argv[0];
  uid uuid := auth.uid();
begin
  if new.deleted_at is not distinct from old.deleted_at then return new; end if;
  if uid is null then return new; end if;  -- service_role / postgres
  if not public.member_has_permission(uid, new.org_id, cle) then
    raise exception 'Permission refusée : % requise pour supprimer', cle
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: generate_invoice_from_template(uuid, uuid, uuid, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_invoice_from_template(p_org_id uuid, p_template_id uuid, p_client_id uuid, p_job_id uuid DEFAULT NULL::uuid, p_items jsonb DEFAULT '[]'::jsonb, p_due_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_template invoice_templates;
  v_inv_number text;
  v_inv_id uuid;
  v_subtotal int := 0;
  v_tax_cents int := 0;
  v_tps_rate numeric;
  v_tvq_rate numeric;
  v_item jsonb;
  v_line_total int;
BEGIN
  IF NOT has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT * INTO v_template FROM invoice_templates
  WHERE id = p_template_id AND org_id = p_org_id AND deleted_at IS NULL;

  IF v_template.id IS NULL THEN
    RAISE EXCEPTION 'Template not found';
  END IF;

  v_tps_rate := COALESCE((v_template.tax_config->>'tps_rate')::numeric, 5.0);
  v_tvq_rate := COALESCE((v_template.tax_config->>'tvq_rate')::numeric, 9.975);

  -- Calculate subtotal from items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_line_total := (COALESCE((v_item->>'qty')::numeric, 1) * COALESCE((v_item->>'unit_price_cents')::int, 0))::int;
    v_subtotal := v_subtotal + v_line_total;
  END LOOP;

  -- Calculate taxes (Quebec TPS + TVQ)
  v_tax_cents := ROUND(v_subtotal * (v_tps_rate + v_tvq_rate) / 100)::int;

  -- Get next invoice number
  SELECT invoice_next_number(p_org_id) INTO v_inv_number;

  -- Create invoice
  INSERT INTO invoices (
    org_id, created_by, client_id, job_id, invoice_number, status,
    subject, issued_at, due_date, subtotal_cents, tax_cents, total_cents,
    paid_cents, balance_cents, currency
  ) VALUES (
    p_org_id, auth.uid(), p_client_id, p_job_id, v_inv_number, 'draft',
    COALESCE(v_template.name, 'Invoice'),
    now(), CURRENT_DATE + p_due_days,
    v_subtotal, v_tax_cents, v_subtotal + v_tax_cents,
    0, v_subtotal + v_tax_cents,
    COALESCE(v_template.currency, 'CAD')
  ) RETURNING id INTO v_inv_id;

  -- Insert line items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO invoice_items (org_id, invoice_id, description, qty, unit_price_cents)
    VALUES (
      p_org_id, v_inv_id,
      COALESCE(v_item->>'description', ''),
      COALESCE((v_item->>'qty')::numeric, 1),
      COALESCE((v_item->>'unit_price_cents')::int, 0)
    );
  END LOOP;

  RETURN jsonb_build_object(
    'invoice_id', v_inv_id,
    'invoice_number', v_inv_number,
    'subtotal_cents', v_subtotal,
    'tax_cents', v_tax_cents,
    'total_cents', v_subtotal + v_tax_cents,
    'currency', COALESCE(v_template.currency, 'CAD'),
    'tax_breakdown', jsonb_build_object('tps', ROUND(v_subtotal * v_tps_rate / 100), 'tvq', ROUND(v_subtotal * v_tvq_rate / 100))
  );
END;
$$;


--
-- Name: generate_task_public_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_task_public_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  next_num integer;
begin
  select coalesce(max(
    cast(replace(public_id, 'TASK-', '') as integer)
  ), 1000) + 1
  into next_num
  from public.tasks
  where org_id = NEW.org_id
    and public_id like 'TASK-%';

  NEW.public_id := 'TASK-' || next_num;
  return NEW;
end;
$$;


--
-- Name: get_audit_log(uuid, text, uuid, text, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_log(p_org_id uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, actor_id uuid, action text, entity_type text, entity_id uuid, event_type text, old_values jsonb, new_values jsonb, metadata jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT ae.id, ae.actor_id, ae.action, ae.entity_type, ae.entity_id,
         ae.event_type, ae.old_values, ae.new_values, ae.metadata, ae.created_at
  FROM audit_events ae
  WHERE ae.org_id = p_org_id
    AND (p_entity_type IS NULL OR ae.entity_type = p_entity_type)
    AND (p_entity_id IS NULL OR ae.entity_id = p_entity_id)
    AND (p_action IS NULL OR ae.action = p_action)
    AND (p_from IS NULL OR ae.created_at >= p_from)
    AND (p_to IS NULL OR ae.created_at <= p_to)
  ORDER BY ae.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: get_available_slots(uuid, uuid, date, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_slots(p_org_id uuid, p_team_id uuid DEFAULT NULL::uuid, p_start_date date DEFAULT CURRENT_DATE, p_days integer DEFAULT 14, p_slot_minutes integer DEFAULT 30, p_timezone text DEFAULT 'America/Toronto'::text) RETURNS TABLE(slot_start timestamp with time zone, slot_end timestamp with time zone, team_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_days int := greatest(1, least(coalesce(p_days, 14), 31));
  v_slot int := greatest(15, least(coalesce(p_slot_minutes, 30), 180));
  v_tz text := coalesce(nullif(trim(p_timezone), ''), 'America/Toronto');
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null then
    raise exception 'p_org_id is required' using errcode = '22023';
  end if;

  if not public.has_org_membership(v_uid, p_org_id) then
    raise exception 'Not a member of this org' using errcode = '42501';
  end if;

  return query
  with days as (
    select (p_start_date + g.d)::date as day_local
    from generate_series(0, v_days - 1) as g(d)
  ),
  windows as (
    select
      d.day_local,
      a.team_id,
      a.start_minute,
      a.end_minute,
      coalesce(nullif(trim(a.timezone), ''), v_tz) as tz
    from days d
    join public.team_availability a
      on a.org_id = p_org_id
     and a.deleted_at is null
     and a.weekday = extract(dow from d.day_local)::int
     and (p_team_id is null or a.team_id = p_team_id)
  ),
  slots as (
    select
      ((w.day_local::timestamp + make_interval(mins => m.minute_val)) at time zone w.tz) as s_start,
      ((w.day_local::timestamp + make_interval(mins => m.minute_val + v_slot)) at time zone w.tz) as s_end,
      w.team_id as t_id
    from windows w
    cross join lateral generate_series(w.start_minute, w.end_minute - v_slot, v_slot) as m(minute_val)
  )
  select s.s_start, s.s_end, s.t_id
  from slots s
  where not exists (
    select 1
    from public.schedule_events se
    left join public.jobs j on j.id = se.job_id
    where se.org_id = p_org_id
      and se.deleted_at is null
      and coalesce(se.start_at, se.start_time) < s.s_end
      and coalesce(se.end_at, se.end_time) > s.s_start
      and (
        p_team_id is null
        or coalesce(se.team_id, j.team_id) = p_team_id
      )
  )
  order by s.s_start asc;
end;
$$;


--
-- Name: get_entity_activity(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_entity_activity(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(event_id uuid, action text, event_type text, actor_id uuid, metadata jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT ae.id, ae.action, ae.event_type, ae.actor_id, ae.metadata, ae.created_at
  FROM audit_events ae
  WHERE ae.org_id = p_org_id
    AND ae.entity_type = p_entity_type
    AND ae.entity_id = p_entity_id
  ORDER BY ae.created_at DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: get_invoice_next_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invoice_next_number(p_org uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_last integer;
begin
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), p_org) then
    raise exception 'Not a member of this organization.' using errcode = '42501';
  end if;
  select last_value into v_last from public.invoice_sequences where org_id = p_org;
  return coalesce(v_last, 0) + 1;
end;
$$;


--
-- Name: get_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_job jsonb;
begin
  if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if not public.crm_is_org_member(p_org_id, v_user) then raise exception 'Forbidden' using errcode='42501'; end if;

  select to_jsonb(j.*) into v_job
  from public.jobs j
  where j.id = p_job_id and j.org_id = p_org_id and j.deleted_at is null;

  if v_job is null then
    return jsonb_build_object('ok', false, 'error', 'Job not found');
  end if;

  return jsonb_build_object('ok', true, 'job', v_job);
end;
$$;


--
-- Name: get_job_kpis(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_kpis(p_org_id uuid, p_status text DEFAULT NULL::text, p_job_type text DEFAULT NULL::text, p_q text DEFAULT NULL::text) RETURNS TABLE(ending_within_30 integer, late integer, requires_invoicing integer, action_required integer, unscheduled integer, recent_visits integer, recent_visits_prev integer, visits_scheduled integer, visits_scheduled_prev integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  return query
  with base as (
    select *
    from public.jobs
    where org_id = p_org_id
      and (p_status is null or status = p_status)
      and (p_job_type is null or job_type = p_job_type)
      and (
        p_q is null
        or job_number ilike '%' || p_q || '%'
        or title ilike '%' || p_q || '%'
        or property_address ilike '%' || p_q || '%'
        or coalesce(client_name, '') ilike '%' || p_q || '%'
      )
  )
  select
    count(*) filter (where scheduled_at is not null and scheduled_at >= now() and scheduled_at < now() + interval '30 days') as ending_within_30,
    count(*) filter (where status = 'Late') as late,
    count(*) filter (where status = 'Requires Invoicing') as requires_invoicing,
    count(*) filter (where status = 'Action Required') as action_required,
    count(*) filter (where status = 'Unscheduled' or scheduled_at is null) as unscheduled,
    count(*) filter (where scheduled_at >= now() - interval '30 days' and scheduled_at < now()) as recent_visits,
    count(*) filter (where scheduled_at >= now() - interval '60 days' and scheduled_at < now() - interval '30 days') as recent_visits_prev,
    count(*) filter (where scheduled_at >= now() and scheduled_at < now() + interval '30 days') as visits_scheduled,
    count(*) filter (where scheduled_at >= now() + interval '30 days' and scheduled_at < now() + interval '60 days') as visits_scheduled_prev
  from base;
end;
$$;


