--
-- Name: has_org_role(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_org_role(p_user uuid, p_org uuid, p_roles text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_exists boolean := false;
begin
  if p_user is null or p_org is null then
    return false;
  end if;

  if to_regclass('public.memberships') is not null then
    select exists (
      select 1
      from public.memberships m
      where m.user_id = p_user
        and m.org_id = p_org
        and m.role = any(p_roles)
        and coalesce(m.status, 'active') = 'active'
    ) into v_exists;
    if v_exists then return true; end if;
  end if;

  if to_regclass('public.org_memberships') is not null then
    execute $q$
      select exists(
        select 1 from public.org_memberships m
        where m.user_id = $1 and m.org_id = $2 and m.role = any($3)
      )
    $q$ into v_exists using p_user, p_org, p_roles;
    if v_exists then return true; end if;
  end if;

  if to_regclass('public.org_members') is not null then
    execute $q$
      select exists(
        select 1 from public.org_members m
        where m.user_id = $1 and m.org_id = $2 and m.role = any($3)
      )
    $q$ into v_exists using p_user, p_org, p_roles;
    if v_exists then return true; end if;
  end if;

  return false;
end;
$_$;


--
-- Name: haversine_distance(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.haversine_distance(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  R constant double precision := 6371000;
  dlat double precision;
  dlng double precision;
  a double precision;
BEGIN
  dlat := radians(lat2 - lat1);
  dlng := radians(lng2 - lng1);
  a := sin(dlat/2)^2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng/2)^2;
  RETURN R * 2 * atan2(sqrt(a), sqrt(1 - a));
END;
$$;


--
-- Name: increment_unread_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_unread_count(p_conversation_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  UPDATE public.conversations
  SET unread_count = COALESCE(unread_count, 0) + 1,
      last_message_at = now()
  WHERE id = p_conversation_id;
$$;


--
-- Name: ingest_lead(uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, text, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_lead(p_org_id uuid, p_source text, p_external_id text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_company text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_utm_source text DEFAULT NULL::text, p_utm_medium text DEFAULT NULL::text, p_utm_campaign text DEFAULT NULL::text, p_utm_content text DEFAULT NULL::text, p_fbclid text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb, p_dedup boolean DEFAULT true, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pipeline    uuid;
  v_etape       uuid;
  v_client      uuid;
  v_deal        uuid;
  v_deal_ouvert uuid;
  v_tel         text := public.normaliser_telephone(p_phone);
  v_courriel    text := nullif(lower(btrim(coalesce(p_email, ''))), '');
  v_fusionne    boolean := false;
  v_nom         text;
  v_auteur      uuid := coalesce(p_created_by, auth.uid());
begin
  if p_org_id is null then
    raise exception 'org_id requis';
  end if;

  -- Sans session, il faut un auteur explicite : c'est ce qu'exige
  -- `crm_enforce_scope` sur clients et deals.
  if v_auteur is null then
    select user_id into v_auteur
    from public.memberships
    where org_id = p_org_id and role in ('owner', 'admin')
    order by case role when 'owner' then 0 else 1 end, created_at
    limit 1;
  end if;

  if v_auteur is null then
    raise exception 'Aucun auteur : passer p_created_by, ou avoir un propriétaire dans l''organisation';
  end if;

  -- 2a. Idempotence : la même soumission ne crée jamais deux deals.
  --     C'est la première chose vérifiée, avant toute écriture.
  if p_external_id is not null then
    select id into v_deal
    from public.deals
    where org_id = p_org_id and source = p_source
      and external_id = p_external_id and deleted_at is null
    limit 1;

    if v_deal is not null then
      return jsonb_build_object(
        'deal_id', v_deal, 'client_id', (select client_id from public.deals where id = v_deal),
        'cree', false, 'fusionne', false, 'deal_existant', true, 'raison', 'deja_ingere');
    end if;
  end if;

  -- 2b. Le pipeline par défaut de l'organisation, et sa première étape
  --     ouverte PAR POSITION — jamais par nom (décision 5 du plan).
  select id into v_pipeline
  from public.pipelines_ventes
  where org_id = p_org_id and is_default
  limit 1;

  if v_pipeline is null then
    v_pipeline := public.seed_pipeline_ventes(p_org_id, 'generique');
  end if;

  select id into v_etape
  from public.pipeline_stages
  where org_id = p_org_id and pipeline_id = v_pipeline
    and kind = 'open' and archived_at is null
  order by position
  limit 1;

  if v_etape is null then
    raise exception 'Aucune étape ouverte dans le pipeline de cette organisation';
  end if;

  -- 2c. Rapprochement (Q4) : téléphone E.164 OU courriel en minuscules,
  --     dans la même organisation. Le plus récemment actif gagne.
  if p_dedup and (v_tel is not null or v_courriel is not null) then
    select id into v_client
    from public.clients
    where org_id = p_org_id
      and deleted_at is null
      and (
        (v_tel is not null and public.normaliser_telephone(phone) = v_tel)
        or (v_courriel is not null and lower(email) = v_courriel)
      )
    order by coalesce(last_client_activity_at, updated_at, created_at) desc
    limit 1;

    v_fusionne := v_client is not null;
  end if;

  -- 2d. Aucun contact retrouvé : on en crée un.
  if v_client is null then
    v_nom := btrim(coalesce(p_first_name, '') || ' ' || coalesce(p_last_name, ''));

    insert into public.clients (
      org_id, first_name, last_name, company, email, phone, address, notes,
      status, lead_status, source, title, value, created_by
    )
    values (
      p_org_id,
      nullif(btrim(coalesce(p_first_name, '')), ''),
      nullif(btrim(coalesce(p_last_name, '')), ''),
      nullif(btrim(coalesce(p_company, '')), ''),
      v_courriel,
      nullif(btrim(coalesce(p_phone, '')), ''),
      nullif(btrim(coalesce(p_address, '')), ''),
      nullif(btrim(coalesce(p_notes, '')), ''),
      'lead', 'new_prospect', p_source,
      nullif(btrim(coalesce(p_company, '')), ''),
      0, v_auteur
    )
    returning id into v_client;
  else
    -- Contact retrouvé : on complète les trous, on n'écrase jamais.
    update public.clients set
      email   = coalesce(email, v_courriel),
      phone   = coalesce(phone, nullif(btrim(coalesce(p_phone, '')), '')),
      address = coalesce(address, nullif(btrim(coalesce(p_address, '')), '')),
      company = coalesce(company, nullif(btrim(coalesce(p_company, '')), '')),
      last_client_activity_at = now(),
      updated_at = now()
    where id = v_client;
  end if;

  -- 2e. Un deal OUVERT existe déjà pour ce contact ? On n'en crée pas un
  --     second : le nouveau lead devient une activité sur celui-là.
  select d.id into v_deal_ouvert
  from public.deals d
  join public.pipeline_stages s on s.id = d.stage_id
  where d.org_id = p_org_id and d.client_id = v_client
    and d.deleted_at is null and s.kind = 'open'
  order by d.created_at desc
  limit 1;

  if v_deal_ouvert is not null then
    update public.deals set
      last_activity_at = now(),
      raw_payload = raw_payload || jsonb_build_object(
        'relances', coalesce(raw_payload -> 'relances', '[]'::jsonb) ||
          jsonb_build_array(jsonb_build_object(
            'a', now(), 'source', p_source, 'external_id', p_external_id,
            'utm_campaign', p_utm_campaign, 'payload', p_payload))
      ),
      updated_at = now()
    where id = v_deal_ouvert;

    return jsonb_build_object(
      'deal_id', v_deal_ouvert, 'client_id', v_client,
      'cree', false, 'fusionne', v_fusionne, 'deal_existant', true,
      'raison', 'deal_ouvert_existant');
  end if;

  -- 2f. Nouveau deal. NON ASSIGNÉ, première étape ouverte (décision 5).
  --     Les horodatages, l'historique et l'événement sont posés par les
  --     triggers : ce chemin produit exactement le même résultat qu'un
  --     glisser-déposer dans l'écran.
  insert into public.deals (
    org_id, pipeline_id, stage_id, client_id, source, external_id,
    utm_source, utm_medium, utm_campaign, utm_content, fbclid, raw_payload,
    created_by
  )
  values (
    p_org_id, v_pipeline, v_etape, v_client, p_source, p_external_id,
    p_utm_source, p_utm_medium, p_utm_campaign, p_utm_content, p_fbclid,
    coalesce(p_payload, '{}'::jsonb), v_auteur
  )
  returning id into v_deal;

  return jsonb_build_object(
    'deal_id', v_deal, 'client_id', v_client,
    'cree', true, 'fusionne', v_fusionne, 'deal_existant', false,
    'raison', case when v_fusionne then 'contact_retrouve' else 'nouveau_contact' end);
end;
$$;


--
-- Name: FUNCTION ingest_lead(p_org_id uuid, p_source text, p_external_id text, p_first_name text, p_last_name text, p_company text, p_email text, p_phone text, p_address text, p_notes text, p_utm_source text, p_utm_medium text, p_utm_campaign text, p_utm_content text, p_fbclid text, p_payload jsonb, p_dedup boolean, p_created_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ingest_lead(p_org_id uuid, p_source text, p_external_id text, p_first_name text, p_last_name text, p_company text, p_email text, p_phone text, p_address text, p_notes text, p_utm_source text, p_utm_medium text, p_utm_campaign text, p_utm_content text, p_fbclid text, p_payload jsonb, p_dedup boolean, p_created_by uuid) IS 'Porte d''entrée unique des leads (formulaire public, création manuelle, futurs canaux), en UNE transaction. Idempotente sur (org, source, external_id). Rapproche sur téléphone E.164 ou courriel (décision Q4) ; si le contact a un deal ouvert, le lead s''y ajoute au lieu de créer un doublon.';


--
-- Name: invalidate_all_sessions(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_all_sessions(p_user_id uuid, p_reason text DEFAULT 'manual'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE v_count int;
    BEGIN
      UPDATE active_sessions SET is_valid = false, invalidated_reason = p_reason WHERE user_id = p_user_id AND is_valid = true;
      GET DIAGNOSTICS v_count = ROW_COUNT;
      INSERT INTO security_events (user_id, event_type, severity, source, details)
      VALUES (p_user_id, 'sessions_invalidated', 'high', 'auth', jsonb_build_object('reason', p_reason, 'count', v_count));
      RETURN v_count;
    END;
    $$;


--
-- Name: FUNCTION invalidate_all_sessions(p_user_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invalidate_all_sessions(p_user_id uuid, p_reason text) IS 'Force-invalidate all sessions for a user';


--
-- Name: invalidate_user_sessions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_user_sessions(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n integer;
begin
  if p_user_id is null then return 0; end if;
  delete from auth.sessions where user_id = p_user_id;
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: FUNCTION invalidate_user_sessions(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invalidate_user_sessions(p_user_id uuid) IS 'Déconnexion forcée : supprime toutes les sessions auth d''un utilisateur. Réservée au serveur (service_role).';


--
-- Name: invoice_items_recalculate_parent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_items_recalculate_parent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice_id uuid;
begin
  v_invoice_id := coalesce(new.invoice_id, old.invoice_id);
  perform public.recalculate_invoice_totals(v_invoice_id);
  return coalesce(new, old);
end;
$$;


--
-- Name: invoice_items_set_line_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_items_set_line_total() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.qty := greatest(coalesce(new.qty, 1), 0);
  new.unit_price_cents := greatest(coalesce(new.unit_price_cents, 0), 0);
  new.line_total_cents := greatest(round(new.qty * new.unit_price_cents)::integer, 0);
  return new;
end;
$$;


--
-- Name: invoice_items_sync_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_items_sync_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
begin
  select org_id
    into v_org
  from public.invoices
  where id = new.invoice_id
    and deleted_at is null
  limit 1;

  if v_org is null then
    raise exception 'Invoice not found for item';
  end if;

  new.org_id := v_org;
  return new;
end;
$$;


--
-- Name: invoice_next_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_next_number(p_org uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_next bigint;
begin
  -- Garde cross-org conservée du fix 20260620.
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), p_org) then
    raise exception 'Not allowed for this organization';
  end if;

  -- Sérialise l'attribution par org (deux créations simultanées ne peuvent
  -- pas recevoir le même « plus petit numéro libre »).
  perform pg_advisory_xact_lock(hashtextextended(p_org::text || ':invoice', 0));

  v_next := public.org_smallest_free_number(p_org, 'invoice');

  insert into public.invoice_sequences (org_id, last_value)
  values (p_org, v_next)
  on conflict (org_id) do update
    set last_value = greatest(public.invoice_sequences.last_value, excluded.last_value),
        updated_at = now();

  return v_next::text;
end;
$$;


--
-- Name: FUNCTION invoice_next_number(p_org uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invoice_next_number(p_org uuid) IS 'N3.7 — CHEMIN OFFICIEL de numerotation des factures. Serialise par org via pg_advisory_xact_lock. Source de verite : invoice_sequences. Toute nouvelle numerotation DOIT passer par ici.';


--
-- Name: invoices_apply_status_logic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoices_apply_status_logic() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.subtotal_cents := greatest(coalesce(new.subtotal_cents, 0), 0);
  new.tax_cents := greatest(coalesce(new.tax_cents, 0), 0);
  -- Même règle que invoiceCalc.calculateInvoiceTotals : le rabais est plafonné au sous-total.
  new.total_cents := greatest(
    new.subtotal_cents - least(greatest(coalesce(new.discount_cents, 0), 0), new.subtotal_cents) + new.tax_cents, 0);
  new.paid_cents := greatest(coalesce(new.paid_cents, 0), 0);

  if new.paid_cents > new.total_cents then
    new.paid_cents := new.total_cents;
  end if;

  new.balance_cents := greatest(new.total_cents - new.paid_cents, 0);

  if coalesce(new.status, '') = 'void' then
    if new.paid_cents = 0 then
      new.paid_at := null;
    end if;
    return new;
  end if;

  -- De l'argent est entré : la facture a de fait été émise. Sans cette
  -- ligne, « marquer payée » sur un brouillon laissait la facture en
  -- brouillon, solde 0, invisible des payées et des revenus.
  if new.issued_at is null and new.paid_cents > 0 then
    new.issued_at := coalesce(new.paid_at, now());
  end if;

  if new.issued_at is null then
    new.status := 'draft';
    if new.paid_cents = 0 then
      new.paid_at := null;
    end if;
    return new;
  end if;

  if new.balance_cents = 0 then
    new.status := 'paid';
    if new.paid_at is null then
      new.paid_at := now();
    end if;
    return new;
  end if;

  if new.paid_cents > 0 then
    new.status := 'partial';
  else
    new.status := 'sent';
  end if;

  if new.balance_cents > 0 then
    new.paid_at := null;
  end if;

  return new;
end;
$$;


--
-- Name: is_email_opted_out(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_email_opted_out(p_email text, p_org_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from public.email_opt_outs
     where email = lower(trim(p_email))
       and (p_org_id is null or org_id = p_org_id or org_id is null));
$$;


--
-- Name: is_ip_blocked(inet, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_ip_blocked(check_ip inet, check_org_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM ip_blocklist
    WHERE ip_address = check_ip
      AND (org_id IS NULL OR org_id = check_org_id)
      AND (expires_at IS NULL OR expires_at > now())
  );
$$;


--
-- Name: FUNCTION is_ip_blocked(check_ip inet, check_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_ip_blocked(check_ip inet, check_org_id uuid) IS 'Check if an IP address is currently blocked';


--
-- Name: is_sms_opted_out(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_sms_opted_out(p_org uuid, p_phone text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_norm text;
begin
  v_norm := public.normalize_phone(p_phone);
  if v_norm is null then return false; end if;
  return exists (
    select 1 from public.sms_opt_outs
    where org_id = p_org
      and public.normalize_phone(phone) = v_norm
  );
end; $$;


--
-- Name: is_valid_timezone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_timezone(p_tz text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if p_tz is null then
    return false;
  end if;
  perform timestamptz '2000-01-01' at time zone p_tz;
  return true;
exception when others then
  return false;
end $$;


--
-- Name: FUNCTION is_valid_timezone(p_tz text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_valid_timezone(p_tz text) IS 'Valide un identifiant de fuseau IANA en tentant la conversion. Utilisee en CHECK : Postgres interdit les sous-requetes sur pg_timezone_names.';


--
-- Name: job_agreements_enforce_job_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_agreements_enforce_job_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  -- New agreements can never attach to a quote.
  if (tg_op = 'INSERT' and new.quote_id is not null)
     or (tg_op = 'UPDATE' and new.quote_id is not null
         and new.quote_id is distinct from old.quote_id) then
    raise exception 'Agreements can no longer be attached to quotes. The signed quote itself is the approved contract.';
  end if;

  -- New agreements must attach to a job.
  if tg_op = 'INSERT' and new.job_id is null then
    raise exception 'An agreement must be attached to a job.';
  end if;

  -- A job that already has an associated (converted) quote cannot receive
  -- an agreement — the quote serves as the approved contract. Checked on
  -- insert, on re-parenting, and on un-archiving.
  if new.job_id is not null
     and new.deleted_at is null
     and (
       tg_op = 'INSERT'
       or new.job_id is distinct from old.job_id
       or (old.deleted_at is not null and new.deleted_at is null)
     )
     and exists (
       select 1 from public.quotes q
       where q.job_id = new.job_id
         and q.deleted_at is null
     ) then
    raise exception 'This job already has an associated quote. An agreement cannot be added because the quote serves as the approved contract for this job.';
  end if;

  return new;
end;
$$;


--
-- Name: job_line_items_set_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_line_items_set_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.qty := greatest(coalesce(new.qty,1),0);
  new.unit_price_cents := greatest(coalesce(new.unit_price_cents,0),0);
  new.total_cents := greatest(round(new.qty * new.unit_price_cents)::int,0);
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: jobs_delier_deal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_delier_deal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Soft delete : la job passe de vivante à effacée.
  if old.deleted_at is null and new.deleted_at is not null then
    update public.deals
    set job_id = null, updated_at = now()
    where job_id = new.id
      and deleted_at is null;
  end if;

  -- Restauration : on ne re-lie RIEN. Le deal a pu être rattaché à une autre
  -- job entre-temps, et deviner lequel reprendre créerait un lien inventé.
  return new;
end;
$$;


--
-- Name: FUNCTION jobs_delier_deal(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.jobs_delier_deal() IS 'Une job supprimée délie le deal qui la portait : sans ça `deals.job_id` pointait dans le vide et le badge « Job à créer » ne réapparaissait jamais (2026-09-25).';


