-- Name: jobs_set_completed_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_set_completed_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status = 'completed' and new.completed_at is null then
    new.completed_at := now();
  end if;
  return new;
end $$;


--
-- Name: jobs_sync_address(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_sync_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    BEGIN
      IF NEW.property_address IS DISTINCT FROM OLD.property_address
         AND (NEW.address IS NULL OR NEW.address = OLD.address) THEN
        NEW.address := NEW.property_address;
      END IF;
      IF NEW.address IS DISTINCT FROM OLD.address
         AND (NEW.property_address IS NULL OR NEW.property_address = OLD.property_address) THEN
        NEW.property_address := NEW.address;
      END IF;
      RETURN NEW;
    END;
    $$;


--
-- Name: jobs_sync_client_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_sync_client_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.sync_client_status_from_jobs(new.client_id);
  elsif tg_op = 'DELETE' then
    perform public.sync_client_status_from_jobs(old.client_id);
  else
    -- UPDATE : couvre la mise de côté, la restauration, et le changement
    -- de client — auquel cas les DEUX clients doivent être recalculés.
    perform public.sync_client_status_from_jobs(new.client_id);
    if old.client_id is distinct from new.client_id then
      perform public.sync_client_status_from_jobs(old.client_id);
    end if;
  end if;
  return null;
end;
$$;


--
-- Name: jobs_sync_future_events_team(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_sync_future_events_team() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  if old.team_id is not distinct from new.team_id then
    return new;
  end if;

  update public.schedule_events se
  set team_id = new.team_id,
      updated_at = now()
  where se.job_id = new.id
    and se.org_id = new.org_id
    and se.deleted_at is null
    and se.start_at >= now();

  return new;
end;
$$;


--
-- Name: jobs_sync_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_sync_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'app'
    AS $$
begin
  if new.total_cents is null and new.total_amount is not null then
    new.total_cents := round(new.total_amount * 100)::integer;
  end if;
  if new.total_amount is null and new.total_cents is not null then
    new.total_amount := round(new.total_cents::numeric / 100, 2);
  end if;
  new.total_cents := coalesce(new.total_cents, 0);
  new.total_amount := coalesce(new.total_amount, round(new.total_cents::numeric / 100, 2));
  return new;
end;
$$;


--
-- Name: lead_converti_gagne_pipeline(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_converti_gagne_pipeline(p_org_id uuid, p_client_id uuid, p_job_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pipeline uuid;
  v_won uuid;
  v_deal uuid;
begin
  if p_org_id is null or p_client_id is null or p_job_id is null then
    return null;
  end if;

  -- Déjà fait ? On ressort le deal tel quel : rappeler la conversion ne doit
  -- pas créer un second deal pour la même job.
  select id into v_deal
  from public.deals
  where org_id = p_org_id and job_id = p_job_id and deleted_at is null
  limit 1;
  if v_deal is not null then
    return v_deal;
  end if;

  -- Le pipeline par défaut de l'organisation, sinon le plus ancien : une org
  -- a toujours un défaut en production, mais s'en remettre à ça seul ferait
  -- échouer la conversion en silence le jour où ce n'est plus vrai.
  select id into v_pipeline
  from public.pipelines_ventes
  where org_id = p_org_id
  order by is_default desc, created_at asc
  limit 1;
  if v_pipeline is null then
    return null;  -- Pas de pipeline de ventes : rien à gagner, ce n'est pas une erreur.
  end if;

  select id into v_won
  from public.pipeline_stages
  where pipeline_id = v_pipeline and kind = 'won' and archived_at is null
  order by position asc
  limit 1;
  if v_won is null then
    return null;
  end if;

  -- Un deal vivant pour ce client ? On le fait gagner plutôt que d'en ouvrir
  -- un second : la vente est la même, et deux cartes pour un client feraient
  -- compter la vente en double dans les prévisions.
  select id into v_deal
  from public.deals
  where org_id = p_org_id and client_id = p_client_id and deleted_at is null
  order by created_at desc
  limit 1;

  if v_deal is not null then
    update public.deals
    set stage_id = v_won,
        job_id = p_job_id,
        won_at = coalesce(won_at, now()),
        stage_entered_at = now(),
        last_activity_at = now(),
        updated_at = now()
    where id = v_deal;
  else
    insert into public.deals (
      org_id, pipeline_id, stage_id, client_id, source, job_id, won_at
    )
    values (
      p_org_id, v_pipeline, v_won, p_client_id, 'lead', p_job_id, now()
    )
    returning id into v_deal;
  end if;

  return v_deal;
end;
$$;


--
-- Name: FUNCTION lead_converti_gagne_pipeline(p_org_id uuid, p_client_id uuid, p_job_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_converti_gagne_pipeline(p_org_id uuid, p_client_id uuid, p_job_id uuid) IS 'Convertir un lead en job gagne le deal du pipeline de ventes (`deals`) : sans ça la vente n''était inscrite que dans l''ancien `pipeline_deals`, invisible dans /ventes (2026-09-25).';


--
-- Name: leads_before_insert_enforce_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_before_insert_enforce_scope() RETURNS trigger
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid;
  v_org uuid;
begin
  v_user := auth.uid();

  -- SQL Editor / service role: exige valeurs explicites
  if v_user is null then
    if new.org_id is null then
      raise exception 'org_id is required when no auth context' using errcode = '23502';
    end if;
    if new.created_by is null then
      raise exception 'created_by is required when no auth context' using errcode = '23502';
    end if;
    return new;
  end if;

  v_org := public.current_org_id();
  if v_org is null then
    v_org := v_user;
  end if;

  new.org_id := v_org;
  new.created_by := v_user;

  return new;
end;
$$;


--
-- Name: leads_force_org_id(); Type: FUNCTION; Schema: public; Owner: -
