COMMENT ON TABLE public.audit_events IS '[System] Audit trail for sensitive operations';


--
-- Name: list_member_audit_events(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_member_audit_events(p_user_id uuid, p_limit integer DEFAULT 200) RETURNS SETOF public.audit_events
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_org uuid;
begin
  -- Find an org where both caller and target are members
  select m1.org_id into v_org
    from public.memberships m1
    join public.memberships m2 on m1.org_id = m2.org_id
   where m1.user_id = auth.uid()
     and m2.user_id = p_user_id
     and public.has_org_admin_role(auth.uid(), m1.org_id)
   limit 1;
  -- Chemin serveur (service_role) : auth.uid() y est NULL, la jointure
  -- ci-dessus ne peut donc RIEN trouver et la fonction refusait tout le monde.
  -- La route team-compliance.ts:170-175 a deja verifie que la cible appartient
  -- a l'org de l'appelant ET que celui-ci est admin. On resout donc l'org
  -- depuis la cible seule.
  if v_org is null and auth.uid() is null then
    if (select count(distinct m.org_id) from public.memberships m
         where m.user_id = p_user_id) > 1 then
      -- On ne devine pas : servir les evenements de la mauvaise org serait une
      -- fuite. Le cas n'existe pas aujourd'hui, le schema l'autorise pourtant.
      raise exception 'Member belongs to several organizations — org is ambiguous'
        using errcode = '22023';
    end if;
    select m.org_id into v_org
      from public.memberships m
     where m.user_id = p_user_id
     limit 1;
  end if;
  if v_org is null then raise exception 'Not authorized'; end if;

  return query
    select * from public.audit_events
     where org_id = v_org
       and (actor_id = p_user_id or entity_id = p_user_id)
     order by created_at desc
     limit greatest(1, least(p_limit, 1000));
end $$;


--
-- Name: log_invoice_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_invoice_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.total_cents is distinct from old.total_cents then
    insert into public.activity_log (org_id, entity_type, entity_id, related_entity_type, related_entity_id, event_type, actor_id, metadata)
    values (new.org_id, 'invoice', new.id,
      case when new.client_id is not null then 'client' else null end, new.client_id,
      'invoice_updated', auth.uid(),
      jsonb_build_object('invoice_number', coalesce(new.invoice_number, ''),
        'old_total_cents', coalesce(old.total_cents, 0), 'new_total_cents', coalesce(new.total_cents, 0)));
  end if;
  return new;
end; $$;


