--
-- Name: log_job_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_job_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.deleted_at is null and (new.scheduled_at is distinct from old.scheduled_at or new.total_amount is distinct from old.total_amount) then
    insert into public.activity_log (org_id, entity_type, entity_id, related_entity_type, related_entity_id, event_type, actor_id, metadata)
    values (new.org_id, 'job', new.id,
      case when new.client_id is not null then 'client' else null end, new.client_id,
      'job_updated', auth.uid(),
      jsonb_build_object('title', coalesce(new.title, ''),
        'scheduled_changed', (new.scheduled_at is distinct from old.scheduled_at),
        'amount_changed', (new.total_amount is distinct from old.total_amount)));
  end if;
  return new;
end; $$;


