--
-- Name: recalculate_invoice_from_payments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_invoice_from_payments(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_paid_cents bigint := 0;
  v_latest_paid_at timestamptz := null;
  v_total_cents integer := 0;
  v_balance_cents integer := 0;
  v_status text := 'sent';
  v_prev_status text;
begin
  if p_invoice_id is null then
    return;
  end if;

  select
    coalesce(sum(p.amount_cents), 0)::bigint,
    max(p.payment_date)
  into v_paid_cents, v_latest_paid_at
  from public.payments p
  where p.invoice_id = p_invoice_id
    and p.deleted_at is null
    and p.status = 'succeeded';

  select i.total_cents, i.status
    into v_total_cents, v_prev_status
  from public.invoices i
  where i.id = p_invoice_id
    and i.deleted_at is null
  for update;

  if not found then
    return;
  end if;

  v_paid_cents := greatest(0, least(v_paid_cents, v_total_cents));
  v_balance_cents := greatest(v_total_cents - v_paid_cents::integer, 0);

  if v_prev_status = 'void' then
    v_status := 'void';
  elsif v_total_cents = 0 then
    v_status := 'draft';
  elsif v_balance_cents = 0 then
    v_status := 'paid';
  elsif v_paid_cents > 0 then
    v_status := 'partial';
  elsif v_prev_status = 'draft' then
    v_status := 'draft';
  else
    v_status := 'sent';
  end if;

  update public.invoices i
  set
    paid_cents = v_paid_cents::integer,
    balance_cents = v_balance_cents,
    status = v_status,
    paid_at = case when v_status = 'paid' then coalesce(v_latest_paid_at, i.paid_at, now()) else null end,
    updated_at = now()
  where i.id = p_invoice_id;
end;
$$;


--
-- Name: recalculate_invoice_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_invoice_totals(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sub bigint; v_disc bigint; v_tax bigint; v_tot bigint; v_paid bigint;
begin
  select coalesce(sum(line_total_cents),0) into v_sub
  from public.invoice_items where invoice_id = p_invoice_id and deleted_at is null;

  select coalesce(discount_cents,0), coalesce(tax_cents,0), coalesce(paid_cents,0)
    into v_disc, v_tax, v_paid
  from public.invoices where id = p_invoice_id;

  v_disc := least(v_disc, v_sub);
  v_tot  := greatest(0, v_sub - v_disc + v_tax);

  update public.invoices
  set subtotal_cents = v_sub, total_cents = v_tot,
      balance_cents = greatest(0, v_tot - v_paid), updated_at = now()
  where id = p_invoice_id;
end; $$;


--
-- Name: recalculate_job_totals_from_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_job_totals_from_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job_id uuid;
  v_subtotal_cents bigint;
begin
  if tg_op = 'DELETE' then v_job_id := old.job_id;
  else v_job_id := new.job_id; end if;
  if v_job_id is null then return coalesce(new, old); end if;

  select coalesce(sum(greatest(round(qty * unit_price_cents), 0)), 0)
    into v_subtotal_cents
    from public.job_line_items
   where job_id = v_job_id
     and deleted_at is null;

  -- Source de vérité : *_cents. Les colonnes en dollars (subtotal, total,
  -- total_amount, tax_total) sont des projections posées par
  -- sync_legacy_money_columns, BEFORE UPDATE sur jobs — jamais ici.
  update public.jobs
     set subtotal_cents = v_subtotal_cents,
         total_cents    = v_subtotal_cents + coalesce(tax_cents, 0),
         updated_at     = now()
   where id = v_job_id;

  return coalesce(new, old);
end;
$$;


--
-- Name: recompute_job_schedule(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_job_schedule(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.jobs%rowtype;
  v_ev  public.schedule_events%rowtype;
begin
  select * into v_job from public.jobs where id = p_job_id for update;
  if v_job.id is null then return; end if;

  select * into v_ev
  from public.schedule_events
  where job_id = p_job_id and deleted_at is null
  order by (start_at >= now()) desc,
           case when start_at >= now() then start_at end asc,
           start_at desc
  limit 1;

  if v_ev.id is not null then
    update public.jobs
    set scheduled_at = v_ev.start_at, end_at = v_ev.end_at,
        status = case when v_job.status in ('draft','Draft') then 'scheduled' else v_job.status end,
        updated_at = now()
    where id = p_job_id;
  else
    update public.jobs
    set scheduled_at = null, end_at = null,
        status = case when v_job.status = 'scheduled' then 'draft' else v_job.status end,
        updated_at = now()
    where id = p_job_id;
  end if;
end;
$$;


