--
-- Name: request_hard_delete_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_hard_delete_member(p_member_id uuid, p_reassign_to uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_org       uuid;
  v_target    uuid;
  v_reassign_org uuid;
begin
  select org_id, user_id into v_org, v_target
    from public.team_members where id = p_member_id;
  if v_org is null then raise exception 'Team member not found'; end if;

  -- Caller must be admin or owner of this org
  if auth.uid() is not null and not public.has_org_admin_role(auth.uid(), v_org) then
    raise exception 'Only org admin/owner can request member deletion';
  end if;

  -- Cannot delete yourself via this flow
  if v_target = auth.uid() then
    raise exception 'Cannot request deletion of your own account here';
  end if;

  -- Reassignment target must be in the same org
  select org_id into v_reassign_org from public.memberships
    where user_id = p_reassign_to and org_id = v_org limit 1;
  if v_reassign_org is null then
    raise exception 'Reassignment target must be a member of the same organization';
  end if;

  -- Reassign ownership of records owned by this user in this org
  -- (retiré 2026-08-02 : update public.leads — table supprimée, plantait en 42P01)
  update public.clients set created_by = p_reassign_to
    where org_id = v_org and created_by = v_target;
  update public.jobs   set created_by = p_reassign_to
    where org_id = v_org and created_by = v_target;

  -- Best-effort reassignment for assigned_to fields (ignore if columns don't exist)
  -- (retiré 2026-08-02 : update public.leads — table supprimée)
  begin execute 'update public.tasks set assigned_to = $1 where org_id = $2 and assigned_to = $3'
    using p_reassign_to, v_org, v_target; exception when undefined_column then null; end;

  -- Suspend team_member + schedule hard delete in 30 days
  update public.team_members
     set status = 'inactive',
         suspended_at = now(),
         deletion_scheduled_at = now() + interval '30 days',
         deletion_requested_by = auth.uid(),
         updated_at = now()
   where id = p_member_id;

  -- Revoke membership so they lose RLS access immediately
  update public.memberships
     set status = 'suspended'
   where user_id = v_target and org_id = v_org;

  insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
  values (v_org, auth.uid(), 'request_hard_delete', 'team_member', p_member_id,
    jsonb_build_object('target_user', v_target, 'reassigned_to', p_reassign_to, 'scheduled_at', now() + interval '30 days'));
end $_$;


--
-- Name: reserve_ai_budget(uuid, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_ai_budget(p_org uuid, p_cents numeric, p_proactive boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_periode     text := public.lumi_periode_courante();
  v_groupe      uuid;
  v_budget      numeric := 0;
  v_includes    boolean := false;
  v_spent       numeric := 0;
  v_spent_pro   numeric := 0;
  v_reserved    numeric := 0;
  v_reserved_pro numeric := 0;
  v_part_pro    numeric := 0.20;   -- sous-budget proactif : 20 % du plafond
  v_id          uuid;
  v_status      text;
begin
  if p_cents is null or p_cents < 0 then
    raise exception 'reserve_ai_budget: montant invalide';
  end if;
  select company_group_id into v_groupe from public.orgs where id = p_org;
  -- Un seul réservataire à la fois par groupe : c'est ce qui rend le plafond dur.
  perform pg_advisory_xact_lock(hashtext('lumi_budget:' || coalesce(v_groupe::text, p_org::text)));

  select coalesce(p.ai_monthly_budget_cents, 0), coalesce(p.includes_ai, false)
    into v_budget, v_includes
    from public.subscriptions s
    join public.plans p on p.id = s.plan_id
   where s.org_id in (select public.lumi_groupe_orgs(p_org))
     and s.status in ('active', 'trialing', 'past_due')
   order by s.created_at desc
   limit 1;

  if not v_includes then
    return jsonb_build_object('status', 'plan_sans_lumi', 'reservation_id', null, 'budget_cents', 0, 'spent_cents', 0, 'reserved_cents', 0);
  end if;

  select coalesce(sum(cost_cents), 0)
    into v_spent
    from public.ai_usage
   where org_id in (select public.lumi_groupe_orgs(p_org))
     and created_at >= date_trunc('month', now() at time zone 'America/Montreal') at time zone 'America/Montreal';
  select coalesce(sum(spent_proactive_cents), 0) into v_spent_pro
    from public.ai_usage_monthly
   where org_id in (select public.lumi_groupe_orgs(p_org)) and period = v_periode;
  select coalesce(sum(cents), 0), coalesce(sum(cents) filter (where is_proactive), 0)
    into v_reserved, v_reserved_pro
    from public.ai_reservations
   where org_id in (select public.lumi_groupe_orgs(p_org)) and period = v_periode and settled_at is null;

  if v_budget > 0 then
    if v_spent + v_reserved + p_cents > v_budget then
      return jsonb_build_object('status', 'capped', 'reservation_id', null, 'budget_cents', v_budget, 'spent_cents', v_spent, 'reserved_cents', v_reserved);
    end if;
    if p_proactive and v_spent_pro + v_reserved_pro + p_cents > v_budget * v_part_pro then
      return jsonb_build_object('status', 'capped', 'reservation_id', null, 'budget_cents', v_budget, 'spent_cents', v_spent, 'reserved_cents', v_reserved, 'proactive', true);
    end if;
    if v_spent + v_reserved + p_cents >= v_budget * 0.9 then v_status := 'restreint';
    elsif v_spent + v_reserved + p_cents >= v_budget * 0.7 then v_status := 'econome';
    else v_status := 'ok';
    end if;
  else
    v_status := 'ok';
  end if;

  insert into public.ai_reservations (org_id, period, cents, is_proactive)
  values (p_org, v_periode, p_cents, p_proactive)
  returning id into v_id;
  insert into public.ai_usage_monthly (org_id, period, reserved_cents)
  values (p_org, v_periode, p_cents)
  on conflict (org_id, period) do update
    set reserved_cents = public.ai_usage_monthly.reserved_cents + excluded.reserved_cents, updated_at = now();

  return jsonb_build_object('status', v_status, 'reservation_id', v_id, 'budget_cents', v_budget, 'spent_cents', v_spent, 'reserved_cents', v_reserved + p_cents);
end;
$$;


--
-- Name: resolve_primary_property(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_primary_property(p_client_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.id
  from public.properties p
  where p.client_id = p_client_id
    and p.deleted_at is null
    and p.kind = 'service'
  order by p.is_primary desc, p.created_at asc
  limit 1
$$;


--
-- Name: restore_archived_record(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_archived_record(p_org_id uuid, p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NOT has_org_admin_role(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Admin role required to restore records';
  END IF;

  -- Un-soft-delete
  EXECUTE format(
    'UPDATE %I SET deleted_at = NULL, deleted_by = NULL WHERE id = $1 AND org_id = $2',
    p_entity_type || 's'
  ) USING p_entity_id, p_org_id;

  -- Remove from archive
  DELETE FROM archived_records
  WHERE org_id = p_org_id AND entity_type = p_entity_type AND entity_id = p_entity_id;

  RETURN jsonb_build_object('restored', true);
END;
$_$;


--
-- Name: restore_client(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_client(p_org_id uuid, p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_client integer := 0;
  v_jobs integer := 0;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.has_org_admin_role(v_uid, p_org_id) then
    raise exception 'Only owner/admin can restore clients' using errcode = '42501';
  end if;

  update public.clients
  set deleted_at = null, deleted_by = null,
      archived_at = null, archived_by = null
  where id = p_client_id and org_id = p_org_id and archived_at is not null;
  get diagnostics v_client = row_count;

  -- Also restore related jobs
  update public.jobs
  set deleted_at = null, deleted_by = null,
      archived_at = null, archived_by = null
  where client_id = p_client_id and org_id = p_org_id and archived_at is not null;
  get diagnostics v_jobs = row_count;

  return jsonb_build_object('client', v_client, 'jobs', v_jobs);
end;
$$;


--
-- Name: restore_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

