      archived_at = null, archived_by = null
  where id = p_job_id and org_id = p_org_id and archived_at is not null;
  get diagnostics v_job = row_count;

  return jsonb_build_object('job', v_job);
end;
$$;


--
-- Name: restore_lead(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_lead(p_org_id uuid, p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_lead integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING errcode = '42501';
  END IF;
  IF NOT public.has_org_admin_role(v_uid, p_org_id) THEN
    RAISE EXCEPTION 'Only owner/admin can restore leads' USING errcode = '42501';
  END IF;

  UPDATE public.clients
  SET deleted_at = null, deleted_by = null, archived_at = null, archived_by = null
  WHERE id = p_lead_id AND org_id = p_org_id AND archived_at IS NOT NULL;
  GET DIAGNOSTICS v_lead = ROW_COUNT;

  UPDATE public.pipeline_deals
  SET deleted_at = null, archived_at = null, archived_by = null
  WHERE lead_id = p_lead_id AND org_id = p_org_id AND archived_at IS NOT NULL;

  RETURN jsonb_build_object('lead', v_lead);
END;
$$;


--
-- Name: reverse_invoice_payment(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_invoice_payment(p_invoice_id uuid, p_org_id uuid, p_amount_cents integer) RETURNS TABLE(id uuid, paid_cents integer, balance_cents integer, status text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.invoices
  SET
    paid_cents = GREATEST(0, COALESCE(paid_cents, 0) - p_amount_cents),
    balance_cents = GREATEST(0, total_cents - GREATEST(0, COALESCE(paid_cents, 0) - p_amount_cents)),
    status = CASE
      WHEN GREATEST(0, COALESCE(paid_cents, 0) - p_amount_cents) <= 0 THEN 'sent'
      ELSE 'partial'
    END,
    paid_at = NULL,
    updated_at = now()
  WHERE id = p_invoice_id AND org_id = p_org_id
  RETURNING id, paid_cents, balance_cents, status;
$$;


--
-- Name: rpc_add_visit(uuid, timestamp with time zone, timestamp with time zone, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_add_visit(p_job_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_team_id uuid DEFAULT NULL::uuid, p_timezone text DEFAULT 'America/Montreal'::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.jobs%rowtype; v_team public.teams%rowtype; v_event public.schedule_events%rowtype;
  v_overlaps integer := 0; v_team_for_overlap uuid;
begin
  if p_end_at <= p_start_at then raise exception 'end_at must be after start_at'; end if;
  select * into v_job from public.jobs where id = p_job_id and deleted_at is null for update;
  if v_job.id is null then raise exception 'Job not found'; end if;
  if not public.has_org_membership(auth.uid(), v_job.org_id) then raise exception 'Not allowed for this organization'; end if;
  if p_team_id is not null then
    select * into v_team from public.teams where id = p_team_id and org_id = v_job.org_id and deleted_at is null limit 1;
    if v_team.id is null then raise exception 'Team not found in organization'; end if;
  end if;

  insert into public.schedule_events (org_id, created_by, job_id, team_id, start_at, end_at, timezone, status, notes)
  values (v_job.org_id, coalesce(auth.uid(), v_job.created_by), v_job.id, coalesce(p_team_id, v_job.team_id),
          p_start_at, p_end_at, coalesce(nullif(trim(p_timezone), ''), 'America/Montreal'), 'scheduled', coalesce(p_notes, v_job.notes))
  returning * into v_event;

  perform public.recompute_job_schedule(v_job.id);

  v_team_for_overlap := coalesce(v_event.team_id, '00000000-0000-0000-0000-000000000000'::uuid);
  select count(*) into v_overlaps from public.schedule_events se
  where se.id <> v_event.id and se.deleted_at is null
    and coalesce(se.team_id, '00000000-0000-0000-0000-000000000000'::uuid) = v_team_for_overlap
    and tstzrange(se.start_at, se.end_at, '[)') && tstzrange(v_event.start_at, v_event.end_at, '[)');

  return jsonb_build_object('event', to_jsonb(v_event), 'overlaps', v_overlaps);
end;
$$;


--
-- Name: rpc_create_invoice_draft(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_invoice_draft(p_client_id uuid, p_subject text DEFAULT NULL::text, p_due_date date DEFAULT NULL::date, p_invoice_number text DEFAULT NULL::text) RETURNS TABLE(id uuid, invoice_number text, status text, subject text, due_date date, total_cents integer, balance_cents integer, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_number text;
  v_client public.clients%rowtype;
  v_invoice public.invoices%rowtype;
  v_digits text;
  v_wanted bigint;
  v_next bigint;
begin
  v_org := public.current_org_id();
  if v_org is null then
    raise exception 'Unable to resolve org_id for authenticated user';
  end if;

  select *
    into v_client
  from public.clients AS c
  where c.id = p_client_id
    and c.deleted_at is null
  limit 1;

  if v_client.id is null then
    raise exception 'Client not found';
  end if;

  if v_client.org_id <> v_org then
    raise exception 'Client does not belong to your organization';
  end if;

  if lower(coalesce(v_client.status, 'active')) = 'inactive' then
    raise exception 'Client is inactive';
  end if;

  if p_invoice_number is not null and btrim(p_invoice_number) <> '' then
    v_digits := nullif(regexp_replace(p_invoice_number, '\D', '', 'g'), '');
    if v_digits is null then
      raise exception 'Invalid invoice number "%"', p_invoice_number;
    end if;
    v_wanted := v_digits::bigint;

    select greatest(
      coalesce((select s.last_value from public.invoice_sequences s where s.org_id = v_org), 0),
      coalesce((select max(nullif(regexp_replace(i.invoice_number, '\D', '', 'g'), '')::bigint)
                from public.invoices i
                where i.org_id = v_org and i.invoice_number ~ '\d'), 0)
    ) + 1 into v_next;

    if v_wanted > v_next then
      raise exception 'Invoice number % does not exist yet (next available is %)', v_wanted, v_next;
    end if;

    v_number := v_wanted::text;

    if exists (
      select 1 from public.invoices i
      where i.org_id = v_org
        and i.invoice_number ~ '\d'
        and nullif(regexp_replace(i.invoice_number, '\D', '', 'g'), '')::bigint = v_wanted
    ) then
      raise exception 'Invoice number % is already in use', v_number;
    end if;

    insert into public.invoice_sequences (org_id, last_value)
    values (v_org, v_wanted)
    on conflict (org_id) do update
      set last_value = greatest(invoice_sequences.last_value, excluded.last_value),
          updated_at = now();
  else
    v_number := public.invoice_next_number(v_org);
  end if;

  insert into public.invoices (
    org_id,
    created_by,
    client_id,
    invoice_number,
    status,
    subject,
    issued_at,
    due_date,
    subtotal_cents,
    tax_cents,
    total_cents,
    paid_cents,
    balance_cents
  )
  values (
    v_org,
    auth.uid(),
    p_client_id,
    v_number,
    'draft',
    nullif(trim(p_subject), ''),
    null,
    p_due_date,
    0,
    0,
    0,
    0,
    0
  )
  returning * into v_invoice;

  return query
  select
    v_invoice.id,
    v_invoice.invoice_number,
    v_invoice.status,
    v_invoice.subject,
    v_invoice.due_date,
    v_invoice.total_cents,
    v_invoice.balance_cents,
    v_invoice.created_at;
end;
$$;


--
-- Name: rpc_create_job_with_optional_schedule(uuid, uuid, uuid, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_job_with_optional_schedule(p_lead_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_job_number text DEFAULT NULL::text, p_job_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_timezone text DEFAULT 'America/Montreal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_job_id uuid;
  v_event_id uuid;
  v_existing_job uuid;
  v_status text;
begin
  if v_org_id is null then
    raise exception 'No organization context';
  end if;

  if p_lead_id is not null then
    select id into v_existing_job
    from public.jobs
    where org_id = v_org_id
      and lead_id = p_lead_id
      and deleted_at is null
      and lower(coalesce(status, 'draft')) not in ('canceled', 'cancelled', 'completed', 'done')
    limit 1;

    if v_existing_job is not null then
      return jsonb_build_object('job_id', v_existing_job, 'event_id', null, 'existing', true);
    end if;
  end if;

  v_status := case
    when lower(coalesce(trim(p_status), '')) in ('scheduled') then 'scheduled'
    when lower(coalesce(trim(p_status), '')) in ('in_progress', 'in progress') then 'in_progress'
    when lower(coalesce(trim(p_status), '')) in ('completed', 'closed', 'done') then 'completed'
    when lower(coalesce(trim(p_status), '')) in ('cancelled', 'canceled', 'lost') then 'cancelled'
    when lower(coalesce(trim(p_status), '')) in ('draft', 'unscheduled', 'late', 'action_required', 'requires_invoicing', 'qualified', 'quote_sent', 'new') then 'draft'
    when p_scheduled_at is null then 'draft'
    else 'scheduled'
  end;

  insert into public.jobs (
    org_id, created_by, lead_id, client_id, team_id, title, job_number, job_type,
    status, property_address, notes, scheduled_at, end_at
  )
  values (
    v_org_id,
    coalesce(v_user_id, gen_random_uuid()),
    p_lead_id,
    p_client_id,
    p_team_id,
    coalesce(nullif(trim(p_title), ''), 'New job'),
    nullif(trim(p_job_number), ''),
    nullif(trim(p_job_type), ''),
    v_status,
    nullif(trim(p_address), ''),
    nullif(trim(p_notes), ''),
    p_scheduled_at,
    p_end_at
  )
  returning id into v_job_id;

  if p_scheduled_at is not null then
    insert into public.schedule_events (
      org_id, created_by, job_id, team_id, start_at, end_at, timezone, status, notes
    )
    values (
      v_org_id,
      coalesce(v_user_id, gen_random_uuid()),
      v_job_id,
      p_team_id,
      p_scheduled_at,
      coalesce(p_end_at, p_scheduled_at + interval '1 hour'),
      coalesce(nullif(trim(p_timezone), ''), 'America/Montreal'),
      'scheduled',
      nullif(trim(p_notes), '')
    )
    returning id into v_event_id;
  end if;

  return jsonb_build_object(
    'job_id', v_job_id,
    'event_id', v_event_id,
    'existing', false
  );
end;
$$;


--
-- Name: rpc_create_quote(uuid, uuid, text, uuid, text, text, integer, text, text, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_quote(p_lead_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_title text DEFAULT ''::text, p_salesperson_id uuid DEFAULT NULL::uuid, p_context_type text DEFAULT 'lead'::text, p_currency text DEFAULT 'CAD'::text, p_valid_days integer DEFAULT 30, p_notes text DEFAULT NULL::text, p_contract text DEFAULT NULL::text, p_deposit_required boolean DEFAULT false, p_require_payment_method boolean DEFAULT false, p_quote_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid;
  v_quote_number text;
  v_quote_id uuid;
  v_valid_until date;
  v_wanted bigint;
  v_next bigint;
begin
  v_org_id := public.current_org_id();
  if v_org_id is null then
    raise exception 'No organization context';
  end if;

  if p_quote_number is not null and btrim(p_quote_number) <> '' then
    if btrim(p_quote_number) !~ '^\d+$' then
      raise exception 'Invalid quote number "%"', p_quote_number;
    end if;
    v_wanted := btrim(p_quote_number)::bigint;

    select greatest(
      coalesce((select s.last_value from public.quote_sequences s where s.org_id = v_org_id), 0),
      coalesce((select max(nullif(regexp_replace(q.quote_number, '\D', '', 'g'), '')::bigint)
                from public.quotes q
                where q.org_id = v_org_id and q.quote_number ~ '\d'), 0)
    ) + 1 into v_next;

    if v_wanted > v_next then
      raise exception 'Quote number % does not exist yet (next available is %)', v_wanted, v_next;
    end if;
    if exists (
      select 1 from public.quotes q
      where q.org_id = v_org_id
        and q.deleted_at is null
        and btrim(q.quote_number) = v_wanted::text
    ) then
      raise exception 'Quote number % is already in use', v_wanted;
    end if;

    insert into public.quote_sequences (org_id, last_value, updated_at)
    values (v_org_id, v_wanted, now())
    on conflict (org_id) do update
      set last_value = greatest(quote_sequences.last_value, excluded.last_value),
          updated_at = now();

    v_quote_number := v_wanted::text;
  else
    perform pg_advisory_xact_lock(hashtextextended(v_org_id::text || ':quote', 0));
    v_wanted := public.org_smallest_free_number(v_org_id, 'quote');

    insert into public.quote_sequences (org_id, last_value, updated_at)
    values (v_org_id, v_wanted, now())
    on conflict (org_id) do update
      set last_value = greatest(quote_sequences.last_value, excluded.last_value),
          updated_at = now();

    v_quote_number := v_wanted::text;
  end if;

  v_valid_until := current_date + p_valid_days;

  insert into public.quotes (
    org_id, quote_number, title, lead_id, client_id,
    status, context_type, salesperson_id, created_by,
    currency, valid_until, notes, contract_disclaimer,
    deposit_required, require_payment_method
  ) values (
    v_org_id, v_quote_number, p_title, p_lead_id, p_client_id,
    'draft', p_context_type, p_salesperson_id, auth.uid(),
    p_currency, v_valid_until, p_notes, p_contract,
    p_deposit_required, p_require_payment_method
  )
  returning id into v_quote_id;

  insert into public.quote_status_history (quote_id, old_status, new_status, changed_by)
  values (v_quote_id, null, 'draft', auth.uid());

  return jsonb_build_object(
    'quote_id', v_quote_id,
    'quote_number', v_quote_number,
    'valid_until', v_valid_until
  );
end;
$_$;


--
-- Name: rpc_find_free_slots(uuid, date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_find_free_slots(p_team_id uuid DEFAULT NULL::uuid, p_date date DEFAULT CURRENT_DATE, p_days integer DEFAULT 7, p_duration_minutes integer DEFAULT 60) RETURNS TABLE(slot_date date, team_id uuid, team_name text, team_color text, slot_start timestamp with time zone, slot_end timestamp with time zone, duration_minutes integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_day    date;
  v_weekday int;
  v_avail  record;
  v_slot_start timestamptz;
  v_slot_end   timestamptz;
  v_has_conflict boolean;
begin
  -- Get org context
  v_org_id := public.current_org_id();
  if v_org_id is null then
    raise exception 'No organization context';
  end if;

  -- Iterate each day in the requested range
  for v_day in select generate_series(p_date, p_date + (p_days - 1), '1 day'::interval)::date
  loop
    v_weekday := extract(dow from v_day)::int;  -- 0=Sunday, 6=Saturday

    -- For each availability rule that matches this weekday
    for v_avail in
      select ta.team_id, ta.start_minute, ta.end_minute, ta.timezone,
             t.name as tname, t.color_hex as tcolor
      from public.team_availability ta
      join public.teams t on t.id = ta.team_id and t.deleted_at is null
      where ta.deleted_at is null
        and ta.weekday = v_weekday
        and t.org_id = v_org_id
        and (p_team_id is null or ta.team_id = p_team_id)
      order by ta.team_id, ta.start_minute
    loop
      -- Generate slots within this availability window
      declare
        v_minute int := v_avail.start_minute;
      begin
        while v_minute + p_duration_minutes <= v_avail.end_minute loop
          v_slot_start := (v_day || ' 00:00:00')::timestamp at time zone coalesce(v_avail.timezone, 'America/Toronto')
                          + (v_minute * interval '1 minute');
          v_slot_end   := v_slot_start + (p_duration_minutes * interval '1 minute');

          -- Skip past slots
          if v_slot_start >= now() then
            -- Check for conflicts with existing events
            select exists(
              select 1
              from public.schedule_events se
              where se.deleted_at is null
                and se.team_id = v_avail.team_id
                and tstzrange(se.start_at, se.end_at, '[)') && tstzrange(v_slot_start, v_slot_end, '[)')
            ) into v_has_conflict;

            if not v_has_conflict then
              slot_date := v_day;
              team_id := v_avail.team_id;
              team_name := v_avail.tname;
              team_color := v_avail.tcolor;
              slot_start := v_slot_start;
              slot_end := v_slot_end;
              duration_minutes := p_duration_minutes;
              return next;
            end if;
          end if;

          v_minute := v_minute + 30;  -- 30-minute slot increments
        end loop;
      end;
    end loop;
  end loop;
end;
$$;


--
-- Name: rpc_insights_budget_vs_actual(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_budget_vs_actual(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(month_label text, metric text, target_value bigint, actual_value bigint, variance_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_from date; v_to date;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;
  v_from := coalesce(p_from, date_trunc('year',current_date)::date);
  v_to := coalesce(p_to, current_date);

  RETURN QUERY
  WITH months AS (SELECT generate_series(date_trunc('month',v_from)::date, date_trunc('month',v_to)::date, '1 month'::interval)::date AS m),
  tg AS (SELECT month, metric AS tm, target_value FROM budget_targets WHERE org_id=v_org AND month>=v_from AND month<=v_to),
  ra AS (SELECT date_trunc('month',coalesce(i.paid_at,i.issued_at))::date AS m, coalesce(sum(i.total_cents),0)::bigint AS v FROM invoices i WHERE i.org_id=v_org AND i.deleted_at IS NULL AND i.status='paid' AND coalesce(i.paid_at,i.issued_at)>=v_from::timestamptz AND coalesce(i.paid_at,i.issued_at)<(v_to+1)::timestamptz GROUP BY 1),
  ja AS (SELECT date_trunc('month',j.created_at)::date AS m, count(*)::bigint AS v FROM jobs j WHERE j.org_id=v_org AND j.deleted_at IS NULL AND j.created_at>=v_from::timestamptz AND j.created_at<(v_to+1)::timestamptz GROUP BY 1),
  la AS (SELECT date_trunc('month',l.created_at)::date AS m, count(*)::bigint AS v FROM clients l WHERE l.org_id=v_org AND l.status='lead' AND l.deleted_at IS NULL AND l.created_at>=v_from::timestamptz AND l.created_at<(v_to+1)::timestamptz GROUP BY 1)
  SELECT to_char(mo.m,'Mon YY'), 'revenue'::text, coalesce(t.target_value,0), coalesce(r.v,0), CASE WHEN coalesce(t.target_value,0)>0 THEN round(((coalesce(r.v,0)-t.target_value)::numeric/t.target_value)*100,1) ELSE NULL END
  FROM months mo LEFT JOIN tg t ON t.month=mo.m AND t.tm='revenue' LEFT JOIN ra r ON r.m=mo.m WHERE coalesce(t.target_value,0)>0 OR coalesce(r.v,0)>0
  UNION ALL
  SELECT to_char(mo.m,'Mon YY'), 'jobs', coalesce(t.target_value,0), coalesce(j.v,0), CASE WHEN coalesce(t.target_value,0)>0 THEN round(((coalesce(j.v,0)-t.target_value)::numeric/t.target_value)*100,1) ELSE NULL END
  FROM months mo LEFT JOIN tg t ON t.month=mo.m AND t.tm='jobs' LEFT JOIN ja j ON j.m=mo.m WHERE coalesce(t.target_value,0)>0 OR coalesce(j.v,0)>0
  UNION ALL
  SELECT to_char(mo.m,'Mon YY'), 'leads', coalesce(t.target_value,0), coalesce(l.v,0), CASE WHEN coalesce(t.target_value,0)>0 THEN round(((coalesce(l.v,0)-t.target_value)::numeric/t.target_value)*100,1) ELSE NULL END
  FROM months mo LEFT JOIN tg t ON t.month=mo.m AND t.tm='leads' LEFT JOIN la l ON l.m=mo.m WHERE coalesce(t.target_value,0)>0 OR coalesce(l.v,0)>0
  ORDER BY 1, 2;
END;
$$;


--
-- Name: rpc_insights_churn_risk(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_churn_risk(p_org uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS TABLE(client_id uuid, client_name text, email text, total_jobs bigint, total_revenue_cents bigint, last_activity_at timestamp with time zone, days_inactive integer, overdue_invoices bigint, overdue_amount_cents bigint, churn_risk_score numeric, risk_level text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;

  RETURN QUERY
  WITH ca AS (
    SELECT c.id AS cid, concat(c.first_name,' ',c.last_name) AS cname, c.email, count(j.id) AS jc, coalesce(sum(j.total_cents),0) AS rev, max(coalesce(j.updated_at,j.created_at)) AS last_act
    FROM clients c LEFT JOIN jobs j ON j.client_id=c.id AND j.org_id=c.org_id AND j.deleted_at IS NULL
    WHERE c.org_id=v_org AND c.deleted_at IS NULL GROUP BY c.id, c.first_name, c.last_name, c.email HAVING count(j.id)>0
  ),
  od AS (
    SELECT i.client_id AS cid, count(*) AS oc, coalesce(sum(i.balance_cents),0) AS oa
    FROM invoices i WHERE i.org_id=v_org AND i.deleted_at IS NULL AND i.status IN ('sent','partial') AND i.balance_cents>0 AND i.due_date<current_date GROUP BY i.client_id
  ),
  scored AS (
    SELECT ca.*, coalesce(od.oc,0) AS overdue_c, coalesce(od.oa,0) AS overdue_a,
      least(100,
        CASE WHEN extract(day FROM (now()-coalesce(ca.last_act,now())))>=180 THEN 50 WHEN extract(day FROM (now()-coalesce(ca.last_act,now())))>=90 THEN 40 WHEN extract(day FROM (now()-coalesce(ca.last_act,now())))>=60 THEN 25 WHEN extract(day FROM (now()-coalesce(ca.last_act,now())))>=30 THEN 10 ELSE 0 END
        + least(coalesce(od.oc,0)::numeric*10,30)
        + CASE WHEN ca.jc<=1 THEN 15 WHEN ca.jc<=2 THEN 8 ELSE 0 END
      ) AS score
    FROM ca LEFT JOIN od ON od.cid=ca.cid
  )
  SELECT s.cid, s.cname, s.email, s.jc::bigint, s.rev::bigint, s.last_act,
    extract(day FROM (now()-coalesce(s.last_act,now())))::int,
    s.overdue_c::bigint, s.overdue_a::bigint, round(s.score,1),
    CASE WHEN s.score>=60 THEN 'high' WHEN s.score>=30 THEN 'medium' ELSE 'low' END::text
  FROM scored s ORDER BY s.score DESC LIMIT p_limit;
END;
$$;


--
-- Name: rpc_insights_client_lifetime_value(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_client_lifetime_value(p_org uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS TABLE(client_id uuid, client_name text, first_job_at timestamp with time zone, tenure_days integer, total_jobs bigint, total_revenue_cents bigint, avg_job_value_cents bigint, last_activity_at timestamp with time zone, days_since_last_activity integer, clv_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;

  RETURN QUERY
  WITH cs AS (
    SELECT c.id AS cid, concat(c.first_name,' ',c.last_name) AS cname, min(j.created_at) AS first_job, max(coalesce(j.updated_at,j.created_at)) AS last_act, count(j.id) AS jc, coalesce(sum(j.total_cents),0) AS rev
    FROM clients c LEFT JOIN jobs j ON j.client_id=c.id AND j.org_id=c.org_id AND j.deleted_at IS NULL AND j.status NOT IN ('draft','cancelled')
    WHERE c.org_id=v_org AND c.deleted_at IS NULL GROUP BY c.id, c.first_name, c.last_name
  ),
  ir AS (SELECT i.client_id AS cid, coalesce(sum(i.total_cents),0) AS inv FROM invoices i WHERE i.org_id=v_org AND i.deleted_at IS NULL AND i.status='paid' GROUP BY i.client_id)
  SELECT cs.cid, cs.cname, cs.first_job,
    extract(day FROM (now()-coalesce(cs.first_job,now())))::int,
    cs.jc::bigint, greatest(cs.rev,coalesce(ir.inv,0))::bigint,
    CASE WHEN cs.jc>0 THEN (greatest(cs.rev,coalesce(ir.inv,0))/cs.jc)::bigint ELSE 0 END,
    cs.last_act,
    extract(day FROM (now()-coalesce(cs.last_act,cs.first_job,now())))::int,
    round((least(greatest(cs.rev,coalesce(ir.inv,0))::numeric/100000,40)*0.5)+(least(cs.jc::numeric,20)*0.3)+(greatest(0,40-extract(day FROM (now()-coalesce(cs.last_act,now())))::numeric/3)*0.2),1)
  FROM cs LEFT JOIN ir ON ir.cid=cs.cid WHERE cs.jc>0 ORDER BY 10 DESC LIMIT p_limit;
END;
$$;


--
-- Name: rpc_insights_cohort_retention(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_cohort_retention(p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(cohort_month text, months_after integer, cohort_size bigint, active_count bigint, retention_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;

  RETURN QUERY
  WITH cfj AS (
    SELECT c.id AS client_id, date_trunc('month',min(j.created_at))::date AS acq
    FROM clients c JOIN jobs j ON j.client_id=c.id AND j.org_id=c.org_id AND j.deleted_at IS NULL
    WHERE c.org_id=v_org AND c.deleted_at IS NULL GROUP BY c.id HAVING min(j.created_at)>=(current_date-interval '12 months')
  ),
  coh AS (SELECT acq, count(*)::bigint AS sz FROM cfj GROUP BY acq),
  act AS (
    SELECT cfj.client_id, cfj.acq, date_trunc('month',j.created_at)::date AS am
    FROM cfj JOIN jobs j ON j.client_id=cfj.client_id AND j.org_id=v_org AND j.deleted_at IS NULL
  ),
  ret AS (
    SELECT a.acq, (extract(year FROM a.am)*12+extract(month FROM a.am)-extract(year FROM a.acq)*12-extract(month FROM a.acq))::int AS ma, count(distinct a.client_id)::bigint AS ac
    FROM act a GROUP BY a.acq, 2
  )
  SELECT to_char(c.acq,'YYYY-MM'), r.ma, c.sz, r.ac, round((r.ac::numeric/c.sz)*100,1)
  FROM coh c JOIN ret r ON r.acq=c.acq WHERE r.ma BETWEEN 0 AND 11 ORDER BY c.acq, r.ma;
END;
$$;


--
-- Name: rpc_insights_invoices_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_invoices_summary(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(count_draft bigint, count_sent bigint, count_paid bigint, count_past_due bigint, total_outstanding_cents bigint, avg_payment_time_days numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_from_date date;
  v_to_date date;
  v_from_ts timestamptz;
  v_to_exclusive timestamptz;
begin
  v_org := coalesce(p_org, public.current_org_id());
  if v_org is null then
    raise exception 'Unable to resolve org_id';
  end if;

  if not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not allowed for this organization';
  end if;

  v_from_date := least(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_to_date := greatest(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_from_ts := v_from_date::timestamptz;
  v_to_exclusive := (v_to_date + 1)::timestamptz;

  return query
  with base as (
    select *
    from public.invoices i
    where i.org_id = v_org
      and i.deleted_at is null
      and coalesce(i.issued_at, i.created_at) >= v_from_ts
      and coalesce(i.issued_at, i.created_at) < v_to_exclusive
  ),
  -- L'encours n'est pas une métrique de période : une facture impayée émise
  -- avant la fenêtre reste à recevoir. Org-wide, sans borne de date.
  open_inv as (
    select i.balance_cents, i.due_date
    from public.invoices i
    where i.org_id = v_org
      and i.deleted_at is null
      and i.status in ('sent', 'partial')
      and i.balance_cents > 0
  ),
  paid_stats as (
    select
      avg(extract(epoch from (i.paid_at - i.issued_at)) / 86400.0) as avg_payment_time_days
    from public.invoices i
    where i.org_id = v_org
      and i.deleted_at is null
      and i.paid_at is not null
      and i.issued_at is not null
      and i.paid_at >= v_from_ts
      and i.paid_at < v_to_exclusive
      and i.paid_at >= i.issued_at
  )
  select
    (select count(*) from base b where b.status = 'draft')::bigint as count_draft,
    (select count(*) from base b where b.status in ('sent', 'partial'))::bigint as count_sent,
    (select count(*) from base b where b.status = 'paid')::bigint as count_paid,
    (select count(*) from open_inv o where o.due_date < current_date)::bigint as count_past_due,
    coalesce((select sum(o.balance_cents) from open_inv o), 0)::bigint as total_outstanding_cents,
    (select p.avg_payment_time_days from paid_stats p) as avg_payment_time_days;
end;
$$;


--
-- Name: rpc_insights_job_profitability(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_job_profitability(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(total_jobs bigint, total_revenue_cents bigint, total_cost_cents bigint, gross_margin_cents bigint, margin_pct numeric, avg_revenue_per_job_cents bigint, avg_cost_per_job_cents bigint, profitable_jobs bigint, unprofitable_jobs bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_from_ts timestamptz; v_to_ex timestamptz; v_has_cost boolean;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;
  v_from_ts := coalesce(p_from, date_trunc('month',current_date)::date)::timestamptz;
  v_to_ex := (coalesce(p_to,current_date)+1)::timestamptz;
  v_has_cost := exists (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='jobs' AND column_name='cost_cents');

  IF v_has_cost THEN
    RETURN QUERY
    WITH jd AS (SELECT j.id, coalesce(j.total_cents,0) AS rev, coalesce(j.cost_cents,0) AS cost FROM jobs j WHERE j.org_id=v_org AND j.deleted_at IS NULL AND j.status IN ('completed','invoiced') AND j.created_at>=v_from_ts AND j.created_at<v_to_ex)
    SELECT count(*)::bigint, coalesce(sum(rev),0)::bigint, coalesce(sum(cost),0)::bigint, (coalesce(sum(rev),0)-coalesce(sum(cost),0))::bigint,
      CASE WHEN sum(rev)>0 THEN round(((sum(rev)-sum(cost))::numeric/sum(rev))*100,1) ELSE 0 END,
      CASE WHEN count(*)>0 THEN (sum(rev)/count(*))::bigint ELSE 0 END,
      CASE WHEN count(*)>0 THEN (sum(cost)/count(*))::bigint ELSE 0 END,
      count(*) FILTER (WHERE rev>cost)::bigint, count(*) FILTER (WHERE rev<=cost AND cost>0)::bigint FROM jd;
  ELSE
    RETURN QUERY SELECT count(*)::bigint, coalesce(sum(j.total_cents),0)::bigint, 0::bigint, coalesce(sum(j.total_cents),0)::bigint, 100::numeric,
      CASE WHEN count(*)>0 THEN (sum(j.total_cents)/count(*))::bigint ELSE 0 END, 0::bigint, count(*)::bigint, 0::bigint
    FROM jobs j WHERE j.org_id=v_org AND j.deleted_at IS NULL AND j.status IN ('completed','invoiced') AND j.created_at>=v_from_ts AND j.created_at<v_to_ex;
  END IF;
END;
$$;


--
-- Name: rpc_insights_lead_conversion(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_lead_conversion(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(leads_created bigint, leads_closed bigint, conversion_rate numeric, breakdown jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid; v_from_date date; v_to_date date; v_from_ts timestamptz; v_to_exclusive timestamptz;
  v_has_payments boolean; v_created bigint := 0; v_closed bigint := 0; v_rate numeric := 0; v_breakdown jsonb := null;
begin
  v_org := coalesce(p_org, public.current_org_id());
  if v_org is null then raise exception 'Unable to resolve org_id'; end if;
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) then raise exception 'Not allowed for this organization'; end if;

  v_from_date := least(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_to_date := greatest(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_from_ts := v_from_date::timestamptz;
  v_to_exclusive := (v_to_date + 1)::timestamptz;
  v_has_payments := to_regclass('public.payments') is not null;

  -- Un client « a été un lead » s'il l'est encore, s'il porte un lead_status,
  -- ou si un job le référence comme lead_id (la conversion met status='active'
  -- — filtrer sur le statut actuel faisait disparaître chaque lead converti).
  select count(*) into v_created
  from public.clients l
  where l.org_id = v_org and l.deleted_at is null
    and l.created_at >= v_from_ts and l.created_at < v_to_exclusive
    and (
      l.status = 'lead'
      or l.lead_status is not null
      or exists (select 1 from public.jobs j2 where j2.org_id = l.org_id and j2.lead_id = l.id and j2.deleted_at is null)
    );

  -- Leads distincts convertis (pas des jobs — un lead à 3 jobs comptait 3×).
  select count(distinct j.lead_id) into v_closed
  from public.jobs j
  where j.org_id = v_org and j.deleted_at is null and j.lead_id is not null
    and j.created_at >= v_from_ts and j.created_at < v_to_exclusive;

  if v_created > 0 then
    v_rate := least(round((v_closed::numeric / v_created::numeric), 4), 1);
  else
    v_rate := 0;
  end if;

  if v_has_payments then
    with created_source as (
      select coalesce(nullif(trim(l.source), ''), 'Unknown') as source_key, count(*)::bigint as leads_created
      from public.clients l
      where l.org_id = v_org and l.deleted_at is null
        and l.created_at >= v_from_ts and l.created_at < v_to_exclusive
        and (
          l.status = 'lead'
          or l.lead_status is not null
          or exists (select 1 from public.jobs j2 where j2.org_id = l.org_id and j2.lead_id = l.id and j2.deleted_at is null)
        )
      group by 1
    ),
    closed_source as (
      select coalesce(nullif(trim(l.source), ''), 'Unknown') as source_key, count(distinct j.lead_id)::bigint as leads_closed
      from public.jobs j
      join public.clients l on l.id = j.lead_id and l.org_id = j.org_id and l.deleted_at is null
      where j.org_id = v_org and j.deleted_at is null and j.lead_id is not null
        and j.created_at >= v_from_ts and j.created_at < v_to_exclusive
      group by 1
    ),
    revenue_source as (
      select coalesce(nullif(trim(l.source), ''), 'Unknown') as source_key, coalesce(sum(p.amount_cents), 0)::bigint as revenue_cents
      from public.payments p
      join public.jobs j on j.id = p.job_id and j.org_id = p.org_id and j.deleted_at is null and j.lead_id is not null
      join public.clients l on l.id = j.lead_id and l.org_id = j.org_id and l.deleted_at is null
      where p.org_id = v_org and p.deleted_at is null and p.status = 'succeeded'
        and p.paid_at >= v_from_ts and p.paid_at < v_to_exclusive
      group by 1
    ),
    source_keys as (
      select source_key from created_source union
      select source_key from closed_source union
      select source_key from revenue_source
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'source', sk.source_key,
      'leads_created', coalesce(cs.leads_created, 0),
      'leads_closed', coalesce(cl.leads_closed, 0),
      'revenue_cents', coalesce(rs.revenue_cents, 0)
    ) order by sk.source_key), '[]'::jsonb)
    into v_breakdown
    from source_keys sk
    left join created_source cs on cs.source_key = sk.source_key
    left join closed_source cl on cl.source_key = sk.source_key
    left join revenue_source rs on rs.source_key = sk.source_key;
  else
    with created_source as (
      select coalesce(nullif(trim(l.source), ''), 'Unknown') as source_key, count(*)::bigint as leads_created
      from public.clients l
      where l.org_id = v_org and l.deleted_at is null
        and l.created_at >= v_from_ts and l.created_at < v_to_exclusive
        and (
          l.status = 'lead'
          or l.lead_status is not null
          or exists (select 1 from public.jobs j2 where j2.org_id = l.org_id and j2.lead_id = l.id and j2.deleted_at is null)
        )
      group by 1
    ),
    closed_source as (
      select coalesce(nullif(trim(l.source), ''), 'Unknown') as source_key, count(distinct j.lead_id)::bigint as leads_closed
      from public.jobs j
      join public.clients l on l.id = j.lead_id and l.org_id = j.org_id and l.deleted_at is null
      where j.org_id = v_org and j.deleted_at is null and j.lead_id is not null
        and j.created_at >= v_from_ts and j.created_at < v_to_exclusive
      group by 1
    ),
    source_keys as (
      select source_key from created_source union
      select source_key from closed_source
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'source', sk.source_key,
      'leads_created', coalesce(cs.leads_created, 0),
      'leads_closed', coalesce(cl.leads_closed, 0),
      'revenue_cents', 0
    ) order by sk.source_key), '[]'::jsonb)
    into v_breakdown
    from source_keys sk
    left join created_source cs on cs.source_key = sk.source_key
    left join closed_source cl on cl.source_key = sk.source_key;
  end if;

  return query select v_created, v_closed, v_rate, v_breakdown;
end;
$$;


--
-- Name: rpc_insights_overview(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_overview(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(new_leads_count bigint, converted_quotes_count bigint, new_oneoff_jobs_count bigint, invoiced_value_cents bigint, revenue_cents bigint, requests_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_org uuid; v_from_date date; v_to_date date; v_from_ts timestamptz; v_to_exclusive timestamptz;
  v_has_job_type boolean; v_has_payments boolean;
  v_new_leads bigint := 0; v_converted_quotes bigint := 0; v_new_oneoff_jobs bigint := 0;
  v_invoiced_cents bigint := 0; v_revenue_cents bigint := 0; v_requests bigint := null;
  v_has_requests boolean; v_requests_has_org boolean; v_requests_has_created boolean;
  v_requests_has_deleted boolean; v_requests_sql text;
BEGIN
  v_org := coalesce(p_org, public.current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed for this organization'; END IF;

  v_from_date := least(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_to_date := greatest(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_from_ts := v_from_date::timestamptz;
  v_to_exclusive := (v_to_date + 1)::timestamptz;

  v_has_job_type := exists (select 1 from information_schema.columns where table_schema='public' and table_name='jobs' and column_name='job_type');
  v_has_payments := to_regclass('public.payments') is not null;

  SELECT count(*) INTO v_new_leads
  FROM public.clients l
  WHERE l.org_id = v_org AND l.status = 'lead' AND l.deleted_at IS NULL
    AND l.created_at >= v_from_ts AND l.created_at < v_to_exclusive;

  SELECT count(*) INTO v_converted_quotes
  FROM public.jobs j
  WHERE j.org_id = v_org AND j.deleted_at IS NULL AND j.lead_id IS NOT NULL
    AND j.created_at >= v_from_ts AND j.created_at < v_to_exclusive;

  SELECT count(*) INTO v_new_oneoff_jobs
  FROM public.jobs j
  WHERE j.org_id = v_org AND j.deleted_at IS NULL
    AND j.created_at >= v_from_ts AND j.created_at < v_to_exclusive
    AND (not v_has_job_type OR coalesce(nullif(lower(trim(j.job_type)), ''), 'one_off') = 'one_off');

  SELECT coalesce(sum(i.total_cents), 0)::bigint INTO v_invoiced_cents
  FROM public.invoices i
  WHERE i.org_id = v_org AND i.deleted_at IS NULL AND i.status in ('sent', 'partial', 'paid')
    AND coalesce(i.issued_at, i.created_at) >= v_from_ts AND coalesce(i.issued_at, i.created_at) < v_to_exclusive;

  IF v_has_payments THEN
    SELECT coalesce(sum(p.amount_cents), 0)::bigint INTO v_revenue_cents
    FROM public.payments p
    WHERE p.org_id = v_org AND p.deleted_at IS NULL AND p.paid_at >= v_from_ts AND p.paid_at < v_to_exclusive;
  ELSE
    SELECT coalesce(sum(i.paid_cents), 0)::bigint INTO v_revenue_cents
    FROM public.invoices i
    WHERE i.org_id = v_org AND i.deleted_at IS NULL AND i.paid_at IS NOT NULL
      AND i.paid_at >= v_from_ts AND i.paid_at < v_to_exclusive;
  END IF;

  v_has_requests := to_regclass('public.requests') is not null;
  IF v_has_requests THEN
    v_requests_has_org := exists (select 1 from information_schema.columns where table_schema='public' and table_name='requests' and column_name='org_id');
    v_requests_has_created := exists (select 1 from information_schema.columns where table_schema='public' and table_name='requests' and column_name='created_at');
    v_requests_has_deleted := exists (select 1 from information_schema.columns where table_schema='public' and table_name='requests' and column_name='deleted_at');
    IF v_requests_has_org AND v_requests_has_created THEN
      v_requests_sql := 'select count(*) from public.requests r where r.org_id = $1 and r.created_at >= $2 and r.created_at < $3';
      IF v_requests_has_deleted THEN v_requests_sql := v_requests_sql || ' and r.deleted_at is null'; END IF;
      EXECUTE v_requests_sql INTO v_requests USING v_org, v_from_ts, v_to_exclusive;
    END IF;
  END IF;

  RETURN QUERY SELECT v_new_leads, v_converted_quotes, v_new_oneoff_jobs, v_invoiced_cents, v_revenue_cents, v_requests;
END;
$_$;


--
-- Name: rpc_insights_period_comparison(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_period_comparison(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(metric text, current_value bigint, previous_value bigint, change_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_from date; v_to date; v_days int; v_prev_from date; v_prev_to date;
  v_from_ts timestamptz; v_to_ex timestamptz; v_prev_from_ts timestamptz; v_prev_to_ex timestamptz; v_has_payments boolean;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;

  v_from := coalesce(p_from, date_trunc('month', current_date)::date);
  v_to := coalesce(p_to, current_date);
  v_days := greatest(v_to - v_from + 1, 1);
  v_prev_from := v_from - v_days; v_prev_to := v_from - 1;
  v_from_ts := v_from::timestamptz; v_to_ex := (v_to + 1)::timestamptz;
  v_prev_from_ts := v_prev_from::timestamptz; v_prev_to_ex := v_from::timestamptz;
  v_has_payments := to_regclass('public.payments') is not null;

  RETURN QUERY
  WITH cur AS (
    SELECT
      (select count(*) from clients where org_id = v_org and status = 'lead' and deleted_at is null and created_at >= v_from_ts and created_at < v_to_ex) as leads,
      (select count(*) from jobs where org_id = v_org and deleted_at is null and created_at >= v_from_ts and created_at < v_to_ex) as jobs,
      (select coalesce(sum(total_cents),0) from invoices where org_id = v_org and deleted_at is null and status in ('sent','partial','paid') and coalesce(issued_at,created_at) >= v_from_ts and coalesce(issued_at,created_at) < v_to_ex) as invoiced,
      (select count(*) from jobs where org_id = v_org and deleted_at is null and lead_id is not null and created_at >= v_from_ts and created_at < v_to_ex) as conversions,
      (select count(*) from invoices where org_id = v_org and deleted_at is null and status = 'paid' and paid_at >= v_from_ts and paid_at < v_to_ex) as paid_invoices
  ),
  prev AS (
    SELECT
      (select count(*) from clients where org_id = v_org and status = 'lead' and deleted_at is null and created_at >= v_prev_from_ts and created_at < v_prev_to_ex) as leads,
      (select count(*) from jobs where org_id = v_org and deleted_at is null and created_at >= v_prev_from_ts and created_at < v_prev_to_ex) as jobs,
      (select coalesce(sum(total_cents),0) from invoices where org_id = v_org and deleted_at is null and status in ('sent','partial','paid') and coalesce(issued_at,created_at) >= v_prev_from_ts and coalesce(issued_at,created_at) < v_prev_to_ex) as invoiced,
      (select count(*) from jobs where org_id = v_org and deleted_at is null and lead_id is not null and created_at >= v_prev_from_ts and created_at < v_prev_to_ex) as conversions,
      (select count(*) from invoices where org_id = v_org and deleted_at is null and status = 'paid' and paid_at >= v_prev_from_ts and paid_at < v_prev_to_ex) as paid_invoices
  )
  SELECT 'new_leads'::text, cur.leads::bigint, prev.leads::bigint, case when prev.leads > 0 then round(((cur.leads - prev.leads)::numeric / prev.leads) * 100, 1) else null end from cur, prev
  UNION ALL
  SELECT 'new_jobs', cur.jobs, prev.jobs, case when prev.jobs > 0 then round(((cur.jobs - prev.jobs)::numeric / prev.jobs) * 100, 1) else null end from cur, prev
  UNION ALL
  SELECT 'invoiced_value', cur.invoiced, prev.invoiced, case when prev.invoiced > 0 then round(((cur.invoiced - prev.invoiced)::numeric / prev.invoiced) * 100, 1) else null end from cur, prev
  UNION ALL
  SELECT 'conversions', cur.conversions, prev.conversions, case when prev.conversions > 0 then round(((cur.conversions - prev.conversions)::numeric / prev.conversions) * 100, 1) else null end from cur, prev
  UNION ALL
  SELECT 'paid_invoices', cur.paid_invoices, prev.paid_invoices, case when prev.paid_invoices > 0 then round(((cur.paid_invoices - prev.paid_invoices)::numeric / prev.paid_invoices) * 100, 1) else null end from cur, prev;
END;
$$;


--
-- Name: rpc_insights_pipeline_velocity(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_pipeline_velocity(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(total_deals bigint, won_deals bigint, lost_deals bigint, win_rate numeric, avg_deal_value_cents bigint, avg_days_to_close numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_from_ts timestamptz; v_to_ex timestamptz;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;
  v_from_ts := coalesce(p_from, date_trunc('month',current_date)::date)::timestamptz;
  v_to_ex := (coalesce(p_to,current_date)+1)::timestamptz;

  RETURN QUERY
  WITH deals AS (
    -- pipeline_deals n'a pas de colonne status : l'état vit dans stage
    -- (closed_won / closed_lost). L'ancienne version lisait d.status et
    -- plantait à chaque appel.
    SELECT d.id, d.stage AS status, d.value_cents, d.created_at, d.updated_at,
      CASE WHEN d.stage IN ('won','closed_won') THEN extract(epoch FROM (d.updated_at-d.created_at))/86400.0 ELSE NULL END AS days_to_close
    FROM pipeline_deals d WHERE d.org_id=v_org AND d.deleted_at IS NULL AND d.created_at>=v_from_ts AND d.created_at<v_to_ex
  )
  SELECT count(*)::bigint,
    count(*) FILTER (WHERE status IN ('won','closed_won'))::bigint,
    count(*) FILTER (WHERE status IN ('lost','closed_lost'))::bigint,
    CASE WHEN count(*) FILTER (WHERE status IN ('won','closed_won','lost','closed_lost'))>0
      THEN round(count(*) FILTER (WHERE status IN ('won','closed_won'))::numeric/count(*) FILTER (WHERE status IN ('won','closed_won','lost','closed_lost'))*100,1) ELSE 0 END,
    CASE WHEN count(*) FILTER (WHERE status IN ('won','closed_won'))>0
      THEN (coalesce(sum(value_cents) FILTER (WHERE status IN ('won','closed_won')),0)/count(*) FILTER (WHERE status IN ('won','closed_won')))::bigint ELSE 0 END,
    round(coalesce(avg(days_to_close),0)::numeric,1)
  FROM deals;
END;
$$;


--
-- Name: rpc_insights_revenue_forecast(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_revenue_forecast(p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(month_start date, projected_cents bigint, source text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid; v_avg bigint; v_pipeline bigint; v_rate numeric;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;

  SELECT coalesce(sum(i.total_cents)/greatest(count(distinct date_trunc('month',coalesce(i.paid_at,i.issued_at))),1),0)::bigint INTO v_avg
  FROM invoices i WHERE i.org_id=v_org AND i.deleted_at IS NULL AND i.status='paid' AND i.paid_at>=(current_date-interval '6 months');

  SELECT coalesce(sum(q.total_cents),0)::bigint INTO v_pipeline
  FROM quotes q WHERE q.org_id=v_org AND q.deleted_at IS NULL AND q.status IN ('draft','awaiting_response','changes_requested');

  SELECT CASE WHEN count(*)>0 THEN (count(*) FILTER (WHERE q.status='approved'))::numeric/count(*) ELSE 0.3 END INTO v_rate
  FROM quotes q WHERE q.org_id=v_org AND q.deleted_at IS NULL AND q.created_at>=(current_date-interval '6 months');

  RETURN QUERY
  SELECT (date_trunc('month',current_date)+(n||' months')::interval)::date, (v_avg*0.7+(v_pipeline*v_rate*(1.0/(n+1)))*0.3)::bigint, 'blended'::text
  FROM generate_series(1,3) AS n;
END;
$$;


--
-- Name: rpc_insights_revenue_series(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_revenue_series(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_granularity text DEFAULT 'month'::text) RETURNS TABLE(bucket_start date, revenue_cents bigint, invoiced_cents bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_from_date date;
  v_to_date date;
  v_from_ts timestamptz;
  v_to_exclusive timestamptz;
  v_granularity text;
  v_step interval;
  v_series_start date;
  v_series_end date;
  v_has_payments boolean;
begin
  v_org := coalesce(p_org, public.current_org_id());
  if v_org is null then
    raise exception 'Unable to resolve org_id';
  end if;

  if not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not allowed for this organization';
  end if;

  v_from_date := least(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_to_date := greatest(coalesce(p_from, date_trunc('month', current_date)::date), coalesce(p_to, current_date));
  v_from_ts := v_from_date::timestamptz;
  v_to_exclusive := (v_to_date + 1)::timestamptz;
  v_granularity := lower(coalesce(p_granularity, 'month'));
  if v_granularity not in ('day', 'week', 'month') then
    v_granularity := 'month';
  end if;

  if v_granularity = 'day' then
    v_step := interval '1 day';
    v_series_start := v_from_date;
    v_series_end := v_to_date;
  elsif v_granularity = 'week' then
    v_step := interval '1 week';
    v_series_start := date_trunc('week', v_from_date::timestamp)::date;
    v_series_end := date_trunc('week', v_to_date::timestamp)::date;
  else
    v_step := interval '1 month';
    v_series_start := date_trunc('month', v_from_date::timestamp)::date;
    v_series_end := date_trunc('month', v_to_date::timestamp)::date;
  end if;

  v_has_payments := to_regclass('public.payments') is not null;

  if v_has_payments then
    return query
    with buckets as (
      select generate_series(v_series_start::timestamp, v_series_end::timestamp, v_step)::date as bucket_start
    ),
    revenue as (
      select
        date_trunc(v_granularity, p.paid_at)::date as bucket_start,
        coalesce(sum(p.amount_cents), 0)::bigint as revenue_cents
      from public.payments p
      where p.org_id = v_org
        and p.deleted_at is null
        and p.status = 'succeeded'
        and p.paid_at >= v_from_ts
        and p.paid_at < v_to_exclusive
      group by 1
    ),
    invoiced as (
      select
        date_trunc(v_granularity, coalesce(i.issued_at, i.created_at))::date as bucket_start,
        coalesce(sum(i.total_cents), 0)::bigint as invoiced_cents
      from public.invoices i
      where i.org_id = v_org
        and i.deleted_at is null
        and i.status in ('sent', 'partial', 'paid')
        and coalesce(i.issued_at, i.created_at) >= v_from_ts
        and coalesce(i.issued_at, i.created_at) < v_to_exclusive
      group by 1
    )
    select
      b.bucket_start,
      coalesce(r.revenue_cents, 0)::bigint,
      coalesce(i.invoiced_cents, 0)::bigint
    from buckets b
    left join revenue r on r.bucket_start = b.bucket_start
    left join invoiced i on i.bucket_start = b.bucket_start
    order by b.bucket_start asc;
  else
    return query
    with buckets as (
      select generate_series(v_series_start::timestamp, v_series_end::timestamp, v_step)::date as bucket_start
    ),
    revenue as (
      select
        date_trunc(v_granularity, i.paid_at)::date as bucket_start,
        coalesce(sum(i.paid_cents), 0)::bigint as revenue_cents
      from public.invoices i
      where i.org_id = v_org
        and i.deleted_at is null
        and i.paid_at is not null
        and i.paid_at >= v_from_ts
        and i.paid_at < v_to_exclusive
      group by 1
    ),
    invoiced as (
      select
        date_trunc(v_granularity, coalesce(i.issued_at, i.created_at))::date as bucket_start,
        coalesce(sum(i.total_cents), 0)::bigint as invoiced_cents
      from public.invoices i
      where i.org_id = v_org
        and i.deleted_at is null
        and i.status in ('sent', 'partial', 'paid')
        and coalesce(i.issued_at, i.created_at) >= v_from_ts
        and coalesce(i.issued_at, i.created_at) < v_to_exclusive
      group by 1
    )
    select
      b.bucket_start,
      coalesce(r.revenue_cents, 0)::bigint,
      coalesce(i.invoiced_cents, 0)::bigint
    from buckets b
    left join revenue r on r.bucket_start = b.bucket_start
    left join invoiced i on i.bucket_start = b.bucket_start
    order by b.bucket_start asc;
  end if;
end;
$$;


--
-- Name: rpc_insights_team_performance(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_insights_team_performance(p_org uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(team_id uuid, team_name text, jobs_count bigint, jobs_completed bigint, completion_rate numeric, revenue_cents bigint, avg_job_value_cents bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_from_ts timestamptz; v_to_ex timestamptz;
BEGIN
  v_org := coalesce(p_org, current_org_id());
  IF v_org IS NULL THEN RAISE EXCEPTION 'Unable to resolve org_id'; END IF;
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), v_org) THEN RAISE EXCEPTION 'Not allowed'; END IF;
  v_from_ts := coalesce(p_from, date_trunc('month',current_date)::date)::timestamptz;
  v_to_ex := (coalesce(p_to,current_date)+1)::timestamptz;

  RETURN QUERY
  SELECT tm.id, tm.name,
    count(j.id)::bigint,
    count(j.id) FILTER (WHERE j.status IN ('completed','invoiced'))::bigint,
    CASE WHEN count(j.id)>0 THEN round((count(j.id) FILTER (WHERE j.status IN ('completed','invoiced')))::numeric/count(j.id)*100,1) ELSE 0 END,
    coalesce(sum(j.total_cents) FILTER (WHERE j.status IN ('completed','invoiced')),0)::bigint,
    CASE WHEN count(j.id) FILTER (WHERE j.status IN ('completed','invoiced'))>0 THEN (sum(j.total_cents) FILTER (WHERE j.status IN ('completed','invoiced'))/count(j.id) FILTER (WHERE j.status IN ('completed','invoiced')))::bigint ELSE 0 END
  FROM teams tm
  LEFT JOIN jobs j ON j.team_id=tm.id AND j.org_id=v_org AND j.deleted_at IS NULL AND j.created_at>=v_from_ts AND j.created_at<v_to_ex
  WHERE tm.org_id=v_org AND tm.deleted_at IS NULL AND tm.is_active=true
  GROUP BY tm.id, tm.name ORDER BY revenue_cents DESC;
END;
$$;


--
-- Name: rpc_invoices_kpis_30d(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_invoices_kpis_30d(p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(past_due_count bigint, past_due_total_cents bigint, sent_not_due_count bigint, sent_not_due_total_cents bigint, draft_count bigint, draft_total_cents bigint, issued_30d_count bigint, issued_30d_total_cents bigint, avg_invoice_30d_cents bigint, avg_payment_time_days_30d numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
begin
  v_org := coalesce(p_org, public.current_org_id());
  if v_org is null then
    raise exception 'Unable to resolve org_id';
  end if;

  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not allowed for this organization';
  end if;

  return query
  with base as (
    select *
    from public.invoices i
    where i.org_id = v_org
      and i.deleted_at is null
  ),
  overview as (
    select
      count(*) filter (
        where due_date < current_date
          and balance_cents > 0
          and status in ('sent', 'partial')
      ) as past_due_count,
      coalesce(sum(balance_cents) filter (
        where due_date < current_date
          and balance_cents > 0
          and status in ('sent', 'partial')
      ), 0)::bigint as past_due_total_cents,
      count(*) filter (
        where due_date >= current_date
          and balance_cents > 0
          and status in ('sent', 'partial')
      ) as sent_not_due_count,
      coalesce(sum(balance_cents) filter (
        where due_date >= current_date
          and balance_cents > 0
          and status in ('sent', 'partial')
      ), 0)::bigint as sent_not_due_total_cents,
      count(*) filter (
        where status = 'draft'
      ) as draft_count,
      coalesce(sum(total_cents) filter (
        where status = 'draft'
      ), 0)::bigint as draft_total_cents
    from base
  ),
  issued as (
    select
      count(*) as issued_30d_count,
      coalesce(sum(total_cents), 0)::bigint as issued_30d_total_cents
    from base
    where issued_at >= (now() - interval '30 days')
      and status in ('sent', 'partial', 'paid')
  ),
  payment as (
    select
      avg(extract(epoch from (paid_at - issued_at)) / 86400.0) as avg_payment_time_days_30d
    from base
    where paid_at is not null
      and issued_at is not null
      and paid_at >= (now() - interval '30 days')
      and paid_at >= issued_at
  )
  select
    o.past_due_count,
    o.past_due_total_cents,
    o.sent_not_due_count,
    o.sent_not_due_total_cents,
    o.draft_count,
    o.draft_total_cents,
    i.issued_30d_count,
    i.issued_30d_total_cents,
    case
      when i.issued_30d_count = 0 then 0::bigint
      else round(i.issued_30d_total_cents::numeric / i.issued_30d_count::numeric)::bigint
    end as avg_invoice_30d_cents,
    p.avg_payment_time_days_30d
  from overview o
  cross join issued i
  cross join payment p;
end;
$$;


--
-- Name: rpc_list_invoices(text, text, text, text, integer, integer, date, date, uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_list_invoices(p_status text DEFAULT 'all'::text, p_range text DEFAULT 'all'::text, p_q text DEFAULT NULL::text, p_sort text DEFAULT 'due_date_desc'::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_org uuid DEFAULT NULL::uuid, p_salesperson uuid DEFAULT NULL::uuid, p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(id uuid, client_id uuid, client_name text, invoice_number text, status text, subject text, issued_at timestamp with time zone, due_date date, total_cents integer, balance_cents integer, paid_cents integer, created_at timestamp with time zone, updated_at timestamp with time zone, property_id uuid, job_id uuid, site text, quote_number text, payer_name text, payment_method text, provider text, card_last4 text, card_brand text, payment_id uuid, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_status text := lower(coalesce(p_status, 'all'));
  v_range text := lower(coalesce(p_range, 'all'));
  v_sort text := lower(coalesce(p_sort, 'due_date_desc'));
  v_limit integer := greatest(coalesce(p_limit, 25), 1);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_q text := nullif(trim(coalesce(p_q, '')), '');
begin
  v_org := coalesce(p_org, public.current_org_id());
  if v_org is null then
    raise exception 'Unable to resolve org_id';
  end if;

  if not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not allowed for this organization';
  end if;

  return query
  with base as (
    select
      i.id,
      i.client_id,
      coalesce(
        nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''),
        nullif(trim(c.company), ''),
        'Unknown client'
      ) as client_name,
      i.invoice_number,
      i.status,
      i.subject,
      i.issued_at,
      i.due_date,
      i.total_cents,
      i.balance_cents,
      i.paid_cents,
      i.created_at,
      i.updated_at,
      i.property_id,
      i.job_id,
      coalesce(nullif(trim(prop.address), ''), prop.name) as site,
      lq.quote_number,
      coalesce(
        nullif(trim(concat_ws(' ', pc.first_name, pc.last_name)), ''),
        nullif(trim(pc.company), ''),
        nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''),
        nullif(trim(c.company), '')
      ) as payer_name,
      lp.method as payment_method,
      lp.provider,
      lp.card_last4,
      lp.card_brand,
      lp.id as payment_id,
      coalesce(i.issued_at::date, i.created_at::date) as reference_date,
      coalesce(i.salesperson_id, ij.salesperson_id) as effective_salesperson_id
    from public.invoices i
    left join public.clients c on c.id = i.client_id
    left join public.jobs ij on ij.id = i.job_id
    -- latest succeeded payment for this invoice (limit 1 → no row fan-out)
    left join lateral (
      select p.id, p.method, p.provider, null::text as card_last4, null::text as card_brand, p.client_id
      from public.payments p
      where p.invoice_id = i.id
        and p.org_id = v_org
        and p.status = 'succeeded'
        and p.deleted_at is null
      order by coalesce(p.paid_at, p.payment_date, p.created_at) desc
      limit 1
    ) lp on true
    left join public.clients pc on pc.id = lp.client_id and pc.org_id = v_org
    left join public.properties prop on prop.id = i.property_id and prop.org_id = v_org
    -- quote number via quotes.job_id → invoices.job_id
    left join lateral (
      select q.quote_number
      from public.quotes q
      where q.job_id = i.job_id
        and q.org_id = v_org
        and q.deleted_at is null
      order by q.created_at desc
      limit 1
    ) lq on true
    where i.org_id = v_org
      and i.deleted_at is null
      -- Filtre par champs personnalisés (v2) : ids calculés par cf_filtrer.
      and (p_ids is null or i.id = any(p_ids))
      and (c.id is null or c.org_id = v_org)
  ),
  filtered as (
    select *
    from base b
    where
      (
        v_status = 'all'
        or (v_status = 'draft' and b.status = 'draft')
        or (v_status = 'paid' and b.status = 'paid')
        or (
          v_status = 'past_due'
          and b.status in ('sent', 'partial')
          and b.balance_cents > 0
          and b.due_date < current_date
        )
        or (
          v_status = 'sent_not_due'
          and b.status in ('sent', 'partial')
          and b.balance_cents > 0
          and b.due_date >= current_date
        )
      )
      and (p_salesperson is null or b.effective_salesperson_id = p_salesperson)
      and (
        v_range = 'all'
        or (v_range = '30d' and b.reference_date >= (current_date - interval '30 days')::date)
        or (v_range = 'this_month' and date_trunc('month', b.reference_date) = date_trunc('month', current_date))
        or (
          v_range = 'custom'
          and (p_from is null or b.reference_date >= p_from)
          and (p_to is null or b.reference_date <= p_to)
        )
      )
      and (
        v_q is null
        or b.client_name ilike ('%' || v_q || '%')
        or b.invoice_number ilike ('%' || v_q || '%')
        or coalesce(b.subject, '') ilike ('%' || v_q || '%')
      )
  )
  select
    f.id,
    f.client_id,
    f.client_name,
    f.invoice_number,
    f.status,
    f.subject,
    f.issued_at,
    f.due_date,
    f.total_cents,
    f.balance_cents,
    f.paid_cents,
    f.created_at,
    f.updated_at,
    f.property_id,
    f.job_id,
    f.site,
    f.quote_number,
    f.payer_name,
    f.payment_method,
    f.provider,
    f.card_last4,
    f.card_brand,
    f.payment_id,
    count(*) over() as total_count
  from filtered f
  order by
    case when v_sort = 'client_asc' then lower(f.client_name) end asc nulls last,
    case when v_sort = 'client_desc' then lower(f.client_name) end desc nulls last,
    case when v_sort = 'invoice_number_asc' then f.invoice_number end asc nulls last,
    case when v_sort = 'invoice_number_desc' then f.invoice_number end desc nulls last,
    case when v_sort = 'due_date_asc' then f.due_date end asc nulls last,
    case when v_sort = 'due_date_desc' then f.due_date end desc nulls last,
    case when v_sort = 'status_asc' then f.status end asc nulls last,
    case when v_sort = 'status_desc' then f.status end desc nulls last,
    case when v_sort = 'total_asc' then f.total_cents end asc nulls last,
    case when v_sort = 'total_desc' then f.total_cents end desc nulls last,
    case when v_sort = 'balance_asc' then f.balance_cents end asc nulls last,
    case when v_sort = 'balance_desc' then f.balance_cents end desc nulls last,
    f.created_at desc
  limit v_limit
  offset v_offset;
end;
$$;


--
-- Name: rpc_list_payments(text, text, text, text, date, date, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_list_payments(p_status text DEFAULT 'all'::text, p_method text DEFAULT 'all'::text, p_date text DEFAULT 'all'::text, p_q text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, client_id uuid, client_name text, invoice_id uuid, invoice_number text, payment_date timestamp with time zone, payout_date timestamp with time zone, status text, method text, amount_cents integer, currency text, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_status text := lower(coalesce(nullif(trim(p_status), ''), 'all'));
  v_method text := lower(coalesce(nullif(trim(p_method), ''), 'all'));
  v_date text := lower(coalesce(nullif(trim(p_date), ''), 'all'));
  v_q text := nullif(trim(coalesce(p_q, '')), '');
  v_q_amount text;
  v_limit integer := greatest(coalesce(p_limit, 25), 1);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  v_org := coalesce(p_org, public.current_org_id());

  if v_org is null then
    raise exception 'Unable to resolve org_id';
  end if;

  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not allowed for this organization';
  end if;

  v_q_amount := nullif(regexp_replace(coalesce(v_q, ''), '[^0-9.]', '', 'g'), '');

  return query
  with base as (
    select
      p.id,
      p.client_id,
      coalesce(
        nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''),
        nullif(trim(c.company), ''),
        'Unknown client'
      ) as client_name,
      p.invoice_id,
      i.invoice_number,
      p.payment_date,
      p.payout_date,
      p.status,
      p.method,
      p.amount_cents,
      p.currency,
      p.created_at
    from public.payments p
    left join public.clients c
      on c.id = p.client_id
     and c.org_id = v_org
    left join public.invoices i
      on i.id = p.invoice_id
     and i.org_id = v_org
     and i.deleted_at is null
    where p.org_id = v_org
      and p.deleted_at is null
  ),
  filtered as (
    select *
    from base b
    where
      (v_status = 'all' or b.status = v_status)
      and (v_method = 'all' or coalesce(b.method, '') = v_method)
      and (
        v_date = 'all'
        or (v_date = '30d' and b.payment_date >= (now() - interval '30 days'))
        or (v_date = 'this_month' and date_trunc('month', b.payment_date) = date_trunc('month', now()))
        or (
          v_date = 'custom'
          and (p_from is null or b.payment_date::date >= p_from)
          and (p_to is null or b.payment_date::date <= p_to)
        )
      )
      and (
        v_q is null
        or b.client_name ilike ('%' || v_q || '%')
        or coalesce(b.invoice_number, '') ilike ('%' || v_q || '%')
        or coalesce(b.method, '') ilike ('%' || v_q || '%')
        or b.amount_cents::text ilike ('%' || v_q || '%')
        or (v_q_amount is not null and to_char((b.amount_cents::numeric / 100.0), 'FM9999999990D00') ilike ('%' || v_q_amount || '%'))
      )
  )
  select
    f.id,
    f.client_id,
    f.client_name,
    f.invoice_id,
    f.invoice_number,
    f.payment_date,
    f.payout_date,
    f.status,
    f.method,
    f.amount_cents,
    f.currency,
    count(*) over() as total_count
  from filtered f
  order by f.payment_date desc, f.created_at desc
  limit v_limit
  offset v_offset;
end;
$$;


--
-- Name: rpc_my_failed_logins(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_my_failed_logins(p_limit integer DEFAULT 50) RETURNS TABLE(email text, ip inet, user_agent text, reason text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select f.email, f.ip_address, f.user_agent, f.reason, f.created_at
    from public.failed_login_attempts f
   where lower(f.email) = lower((select u.email from auth.users u where u.id = (select auth.uid())))
   order by f.created_at desc
   limit least(p_limit, 200);
$$;


--
-- Name: rpc_payments_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_payments_overview(p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(available_funds_cents bigint, invoice_payment_time_days_30d numeric, paid_on_time_global_pct_60d numeric, paid_on_time_residential_pct_60d numeric, paid_on_time_commercial_pct_60d numeric, has_property_split boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_has_property_type boolean;
  v_available bigint := 0;
  v_avg_payment_days numeric := null;
  v_global_pct numeric := null;
  v_res_pct numeric := null;
  v_com_pct numeric := null;
begin
  v_org := coalesce(p_org, public.current_org_id());

  if v_org is null then
    raise exception 'Unable to resolve org_id';
  end if;

  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not allowed for this organization';
  end if;

  select coalesce(sum(p.amount_cents), 0)::bigint
    into v_available
  from public.payments p
  where p.org_id = v_org
    and p.deleted_at is null
    and p.status = 'succeeded'
    and p.payout_date is null;

  with paid_invoice as (
    select
      p.invoice_id,
      max(p.payment_date) as last_payment_date
    from public.payments p
    where p.org_id = v_org
      and p.deleted_at is null
      and p.status = 'succeeded'
      and p.invoice_id is not null
    group by p.invoice_id
  )
  select avg(extract(epoch from (pi.last_payment_date - coalesce(i.issued_at, i.created_at))) / 86400.0)
    into v_avg_payment_days
  from paid_invoice pi
  join public.invoices i
    on i.id = pi.invoice_id
   and i.org_id = v_org
   and i.deleted_at is null
  where pi.last_payment_date >= (now() - interval '30 days')
    and coalesce(i.issued_at, i.created_at) is not null
    and pi.last_payment_date >= coalesce(i.issued_at, i.created_at);

  with paid_invoice as (
    select
      p.invoice_id,
      max(p.payment_date) as paid_date,
      max(p.job_id) as job_id
    from public.payments p
    where p.org_id = v_org
      and p.deleted_at is null
      and p.status = 'succeeded'
      and p.invoice_id is not null
    group by p.invoice_id
  ),
  paid_60 as (
    select
      pi.invoice_id,
      pi.paid_date,
      i.due_date,
      pi.job_id
    from paid_invoice pi
    join public.invoices i
      on i.id = pi.invoice_id
     and i.org_id = v_org
     and i.deleted_at is null
    where pi.paid_date >= (now() - interval '60 days')
      and i.due_date is not null
  )
  select
    case
      when count(*) = 0 then null
      else round(avg(case when p60.paid_date::date <= p60.due_date then 100.0 else 0 end)::numeric, 2)
    end
  into v_global_pct
  from paid_60 p60;

  v_has_property_type := exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'jobs'
      and column_name = 'property_type'
  );

  if v_has_property_type then
    with paid_invoice as (
      select
        p.invoice_id,
        max(p.payment_date) as paid_date,
        max(p.job_id) as job_id
      from public.payments p
      where p.org_id = v_org
        and p.deleted_at is null
        and p.status = 'succeeded'
        and p.invoice_id is not null
      group by p.invoice_id
    ),
    paid_60 as (
      select
        pi.invoice_id,
        pi.paid_date,
        i.due_date,
        lower(trim(coalesce(j.property_type, ''))) as property_type
      from paid_invoice pi
      join public.invoices i
        on i.id = pi.invoice_id
       and i.org_id = v_org
       and i.deleted_at is null
      left join public.jobs j
        on j.id = pi.job_id
       and j.org_id = v_org
       and j.deleted_at is null
      where pi.paid_date >= (now() - interval '60 days')
        and i.due_date is not null
    )
    select
      case
        when count(*) filter (where property_type = 'residential') = 0 then null
        else round(
          avg(case when paid_date::date <= due_date then 100.0 else 0 end)
            filter (where property_type = 'residential')::numeric,
          2
        )
      end,
      case
        when count(*) filter (where property_type = 'commercial') = 0 then null
        else round(
          avg(case when paid_date::date <= due_date then 100.0 else 0 end)
            filter (where property_type = 'commercial')::numeric,
          2
        )
      end
    into v_res_pct, v_com_pct
    from paid_60;
  end if;

  return query
  select
    v_available,
    v_avg_payment_days,
    v_global_pct,
    v_res_pct,
    v_com_pct,
    v_has_property_type;
end;
$$;


--
-- Name: rpc_payments_overview_kpis(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_payments_overview_kpis(p_org uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(available_funds_cents bigint, invoice_payment_time_days_30d numeric, paid_on_time_global_pct_60d numeric, paid_on_time_residential_pct_60d numeric, paid_on_time_commercial_pct_60d numeric, has_segment_split boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_now timestamptz := coalesce(p_now, now());
  v_has_jobs_service_type boolean;
  v_has_clients_segment boolean;
  v_available bigint := 0;
  v_avg_payment_days numeric := 0;
  v_global_pct numeric := 0;
  v_res_pct numeric := null;
  v_com_pct numeric := null;
begin
  v_org := coalesce(p_org, public.current_org_id());

  if v_org is null then
    raise exception 'Unable to resolve org_id';
  end if;

  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not allowed for this organization';
  end if;

  select coalesce(sum(p.amount_cents), 0)::bigint
    into v_available
  from public.payments p
  where p.org_id = v_org
    and p.deleted_at is null
    and p.status = 'succeeded'
    and p.payout_date is null;

  select coalesce(
    avg(
      extract(epoch from (p.payment_date - coalesce(i.issued_at, i.created_at))) / 86400.0
    ),
    0
  )
  into v_avg_payment_days
  from public.payments p
  join public.invoices i
    on i.id = p.invoice_id
   and i.org_id = v_org
   and i.deleted_at is null
  where p.org_id = v_org
    and p.deleted_at is null
    and p.status = 'succeeded'
    and p.invoice_id is not null
    and p.payment_date >= (v_now - interval '30 days')
    and coalesce(i.issued_at, i.created_at) is not null
    and p.payment_date >= coalesce(i.issued_at, i.created_at);

  select coalesce(
    avg(
      case when i.paid_at::date <= i.due_date then 100.0 else 0 end
    ),
    0
  )
  into v_global_pct
  from public.invoices i
  where i.org_id = v_org
    and i.deleted_at is null
    and i.due_date is not null
    and i.paid_at is not null
    and i.paid_at >= (v_now - interval '60 days')
    and (i.status = 'paid' or i.balance_cents = 0);

  v_has_jobs_service_type := exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'jobs'
      and column_name = 'service_type'
  );

  v_has_clients_segment := exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'clients'
      and column_name = 'segment'
  );

  if v_has_jobs_service_type then
    with invoice_segment as (
      select
        i.id,
        i.paid_at,
        i.due_date,
        case
          when lower(coalesce(j.service_type, '')) like '%residential%' then 'residential'
          when lower(coalesce(j.service_type, '')) like '%commercial%' then 'commercial'
          else null
        end as segment
      from public.invoices i
      join public.payments p
        on p.invoice_id = i.id
       and p.org_id = v_org
       and p.deleted_at is null
      left join public.jobs j
        on j.id = p.job_id
       and j.org_id = v_org
       and j.deleted_at is null
      where i.org_id = v_org
        and i.deleted_at is null
        and i.due_date is not null
        and i.paid_at is not null
        and i.paid_at >= (v_now - interval '60 days')
        and (i.status = 'paid' or i.balance_cents = 0)
      group by i.id, i.paid_at, i.due_date, j.service_type
    )
    select
      case
        when count(*) filter (where segment = 'residential') = 0 then null
        else round(avg(case when paid_at::date <= due_date then 100.0 else 0 end)
          filter (where segment = 'residential')::numeric, 2)
      end,
      case
        when count(*) filter (where segment = 'commercial') = 0 then null
        else round(avg(case when paid_at::date <= due_date then 100.0 else 0 end)
          filter (where segment = 'commercial')::numeric, 2)
      end
    into v_res_pct, v_com_pct
    from invoice_segment;
  elsif v_has_clients_segment then
    with invoice_segment as (
      select
        i.id,
        i.paid_at,
        i.due_date,
        case
          when lower(coalesce(c.segment, '')) like '%residential%' then 'residential'
          when lower(coalesce(c.segment, '')) like '%commercial%' then 'commercial'
          else null
        end as segment
      from public.invoices i
      left join public.clients c
        on c.id = i.client_id
       and c.org_id = v_org
      where i.org_id = v_org
        and i.deleted_at is null
        and i.due_date is not null
        and i.paid_at is not null
        and i.paid_at >= (v_now - interval '60 days')
        and (i.status = 'paid' or i.balance_cents = 0)
    )
    select
      case
        when count(*) filter (where segment = 'residential') = 0 then null
        else round(avg(case when paid_at::date <= due_date then 100.0 else 0 end)
          filter (where segment = 'residential')::numeric, 2)
      end,
      case
        when count(*) filter (where segment = 'commercial') = 0 then null
        else round(avg(case when paid_at::date <= due_date then 100.0 else 0 end)
          filter (where segment = 'commercial')::numeric, 2)
      end
    into v_res_pct, v_com_pct
    from invoice_segment;
  end if;

  return query
  select
    v_available,
    coalesce(round(v_avg_payment_days::numeric, 2), 0),
    coalesce(round(v_global_pct::numeric, 2), 0),
    v_res_pct,
    v_com_pct,
    (v_res_pct is not null or v_com_pct is not null);
end;
$$;


--
-- Name: rpc_peek_next_numbers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_peek_next_numbers() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid := public.current_org_id();
  v_inv bigint;
begin
  if v_org is null then
    raise exception 'No organization context';
  end if;

  v_inv := public.org_smallest_free_number(v_org, 'invoice');

  return jsonb_build_object(
    'job', public.org_smallest_free_number(v_org, 'job')::text,
    'quote', public.org_smallest_free_number(v_org, 'quote')::text,
    'invoice_seq', v_inv,
    'invoice', v_inv::text,
    'client', public.org_smallest_free_number(v_org, 'client')::text
  );
end;
$$;


--
-- Name: rpc_recalculate_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_recalculate_quote(p_quote_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_subtotal integer;
  v_tax_rate numeric;
  v_discount_type text;
  v_discount_value numeric;
  v_discount_cents integer;
  v_tax_cents integer;
  v_total integer;
begin

  -- Garde de cloisonnement (audit 2026-07-31). SECURITY DEFINER s'execute sous
  -- postgres (rolbypassrls = true) : la RLS ne protege PAS ce corps. Le
  -- parametre est un quote_id fourni par l'appelant, donc sans cette garde
  -- n'importe quel compte authentifie peut recalculer — et donc ecraser — les
  -- montants du devis d'une autre organisation.
  -- auth.uid() NULL = appel serveur en service_role : on laisse passer.
  if auth.uid() is not null and not exists (
    select 1 from public.quotes q
     where q.id = p_quote_id
       and public.has_org_membership(auth.uid(), q.org_id)
  ) then
    raise exception 'Not authorized for this quote.' using errcode = '42501';
  end if;

  -- Sum line items (exclude optional items from total)
  select coalesce(sum(total_cents), 0) into v_subtotal
  from public.quote_line_items
  where quote_id = p_quote_id and not is_optional;

  -- Get quote settings
  select tax_rate, discount_type, discount_value
  into v_tax_rate, v_discount_type, v_discount_value
  from public.quotes where id = p_quote_id;

  -- Calculate discount
  if v_discount_type = 'percentage' then
    v_discount_cents := round(v_subtotal * v_discount_value / 100);
  elsif v_discount_type = 'fixed' then
    v_discount_cents := round(v_discount_value * 100);
  else
    v_discount_cents := 0;
  end if;

  -- Calculate tax on (subtotal - discount)
  v_tax_cents := round((v_subtotal - v_discount_cents) * coalesce(v_tax_rate, 0) / 100);

  -- Total
  v_total := v_subtotal - v_discount_cents + v_tax_cents;

  -- Update
  update public.quotes set
    subtotal_cents = v_subtotal,
    discount_cents = v_discount_cents,
    tax_cents = v_tax_cents,
    total_cents = v_total,
    updated_at = now()
  where id = p_quote_id;
end;
$$;


--
-- Name: rpc_reschedule_event(uuid, timestamp with time zone, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reschedule_event(p_event_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_team_id uuid DEFAULT NULL::uuid, p_timezone text DEFAULT 'America/Montreal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_event public.schedule_events%rowtype; v_team public.teams%rowtype;
  v_overlaps integer := 0; v_team_for_overlap uuid;
begin
  if p_end_at <= p_start_at then raise exception 'end_at must be after start_at'; end if;
  select * into v_event from public.schedule_events where id = p_event_id and deleted_at is null for update;
  if v_event.id is null then raise exception 'Schedule event not found'; end if;
  if not public.has_org_membership(auth.uid(), v_event.org_id) then raise exception 'Not allowed for this organization'; end if;
  if p_team_id is not null then
    select * into v_team from public.teams where id = p_team_id and org_id = v_event.org_id and deleted_at is null limit 1;
    if v_team.id is null then raise exception 'Team not found in organization'; end if;
  end if;

  update public.schedule_events
  set start_at = p_start_at, end_at = p_end_at, team_id = coalesce(p_team_id, team_id),
      timezone = coalesce(nullif(trim(p_timezone), ''), timezone, 'America/Montreal'),
      status = 'scheduled', updated_at = now()
  where id = v_event.id returning * into v_event;

  perform public.recompute_job_schedule(v_event.job_id);

  v_team_for_overlap := coalesce(v_event.team_id, '00000000-0000-0000-0000-000000000000'::uuid);
  select count(*) into v_overlaps from public.schedule_events se
  where se.id <> v_event.id and se.deleted_at is null
    and coalesce(se.team_id, '00000000-0000-0000-0000-000000000000'::uuid) = v_team_for_overlap
    and tstzrange(se.start_at, se.end_at, '[)') && tstzrange(v_event.start_at, v_event.end_at, '[)');

  return jsonb_build_object('event', to_jsonb(v_event), 'overlaps', v_overlaps);
end;
$$;


--
-- Name: rpc_revenue_by_currency(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_revenue_by_currency(p_org_id uuid, p_from date DEFAULT (CURRENT_DATE - '30 days'::interval), p_to date DEFAULT CURRENT_DATE) RETURNS TABLE(currency text, total_cents bigint, payment_count integer, cad_equivalent_cents bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT
    p.currency,
    SUM(p.amount_cents)::bigint AS total_cents,
    COUNT(*)::int AS payment_count,
    SUM(
      CASE WHEN p.currency = 'CAD' THEN p.amount_cents
      ELSE convert_currency(p.amount_cents, p.currency, 'CAD', p.payment_date::date)
      END
    )::bigint AS cad_equivalent_cents
  FROM payments p
  WHERE p.org_id = p_org_id
    AND p.deleted_at IS NULL
    AND p.status = 'succeeded'
    AND p.payment_date >= p_from
    AND p.payment_date < p_to + INTERVAL '1 day'
  GROUP BY p.currency;
END;
$$;


--
-- Name: rpc_save_invoice_draft(uuid, text, date, integer, jsonb, text, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_save_invoice_draft(p_invoice_id uuid, p_subject text DEFAULT NULL::text, p_due_date date DEFAULT NULL::date, p_tax_cents integer DEFAULT 0, p_items jsonb DEFAULT '[]'::jsonb, p_notes text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text, p_discount_cents integer DEFAULT 0, p_template_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_org uuid;
  v_item jsonb;
  v_sort integer := 0;
begin
  select org_id into v_org from public.invoices
  where id = p_invoice_id and deleted_at is null;
  if v_org is null then raise exception 'Invoice not found.' using errcode='P0002'; end if;
  if not public.has_org_membership(v_uid, v_org) then raise exception 'Forbidden.' using errcode='42501'; end if;

  update public.invoices set
    subject       = coalesce(p_subject, subject),
    due_date      = coalesce(p_due_date, due_date),
    tax_cents     = greatest(0, coalesce(p_tax_cents, 0)),
    notes         = p_notes,
    internal_notes= p_internal_notes,
    discount_cents= greatest(0, coalesce(p_discount_cents, 0)),
    template_id   = p_template_id,
    updated_at    = now()
  where id = p_invoice_id;

  delete from public.invoice_items where invoice_id = p_invoice_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_sort := v_sort + 1;
    insert into public.invoice_items (
      org_id, invoice_id, description, title, qty, unit_price_cents,
      sort_order, source_type, source_id
    ) values (
      v_org, p_invoice_id,
      v_item->>'description',
      v_item->>'title',
      greatest(0, (v_item->>'qty')::numeric),
      greatest(0, (v_item->>'unit_price_cents')::integer),
      v_sort,
      nullif(v_item->>'source_type', ''),
      case when (v_item->>'source_id') is not null and (v_item->>'source_id') <> ''
           then (v_item->>'source_id')::uuid else null end
    );
  end loop;

  perform public.recalculate_invoice_totals(p_invoice_id);

  return (select to_jsonb(i.*) from public.invoices i where i.id = p_invoice_id);
end; $$;


--
-- Name: rpc_schedule_job(uuid, timestamp with time zone, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_schedule_job(p_job_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_team_id uuid DEFAULT NULL::uuid, p_timezone text DEFAULT 'America/Montreal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.jobs%rowtype; v_team public.teams%rowtype; v_event public.schedule_events%rowtype;
  v_existing_event public.schedule_events%rowtype; v_active_count integer := 0;
  v_overlaps integer := 0; v_team_for_overlap uuid; v_updated boolean := false;
begin
  if p_end_at <= p_start_at then raise exception 'end_at must be after start_at'; end if;
  select * into v_job from public.jobs where id = p_job_id and deleted_at is null for update;
  if v_job.id is null then raise exception 'Job not found'; end if;
  if not public.has_org_membership(auth.uid(), v_job.org_id) then raise exception 'Not allowed for this organization'; end if;
  if p_team_id is not null then
    select * into v_team from public.teams where id = p_team_id and org_id = v_job.org_id and deleted_at is null limit 1;
    if v_team.id is null then raise exception 'Team not found in organization'; end if;
  end if;

  select count(*) into v_active_count from public.schedule_events where job_id = v_job.id and deleted_at is null;

  if v_active_count >= 2 then
    perform public.recompute_job_schedule(v_job.id);
    select * into v_event from public.schedule_events
    where job_id = v_job.id and deleted_at is null
    order by (start_at >= now()) desc, case when start_at >= now() then start_at end asc, start_at desc
    limit 1;
    return jsonb_build_object('event', to_jsonb(v_event), 'overlaps', 0, 'updated', true);
  end if;

  select * into v_existing_event from public.schedule_events
  where job_id = v_job.id and deleted_at is null order by created_at desc limit 1 for update;

  if v_existing_event.id is not null then
    update public.schedule_events
    set start_at = p_start_at, end_at = p_end_at,
        team_id = coalesce(p_team_id, team_id, v_job.team_id),
        timezone = coalesce(nullif(trim(p_timezone), ''), timezone, 'America/Montreal'),
        status = 'scheduled', notes = coalesce(notes, v_job.notes), deleted_at = null, updated_at = now()
    where id = v_existing_event.id returning * into v_event;
    v_updated := true;
  else
    insert into public.schedule_events (org_id, created_by, job_id, team_id, start_at, end_at, timezone, status, notes)
    values (v_job.org_id, coalesce(auth.uid(), v_job.created_by), v_job.id, coalesce(p_team_id, v_job.team_id),
            p_start_at, p_end_at, coalesce(nullif(trim(p_timezone), ''), 'America/Montreal'), 'scheduled', v_job.notes)
    returning * into v_event;
  end if;

  update public.jobs set team_id = coalesce(p_team_id, team_id), updated_at = now() where id = v_job.id;
  perform public.recompute_job_schedule(v_job.id);

  v_team_for_overlap := coalesce(v_event.team_id, v_job.team_id, '00000000-0000-0000-0000-000000000000'::uuid);
  select count(*) into v_overlaps from public.schedule_events se
  where se.id <> v_event.id and se.deleted_at is null
    and coalesce(se.team_id, '00000000-0000-0000-0000-000000000000'::uuid) = v_team_for_overlap
    and tstzrange(se.start_at, se.end_at, '[)') && tstzrange(v_event.start_at, v_event.end_at, '[)');

  return jsonb_build_object('event', to_jsonb(v_event), 'overlaps', v_overlaps, 'updated', v_updated);
end;
$$;


--
-- Name: rpc_team_workload(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_team_workload(p_org_id uuid, p_from date DEFAULT CURRENT_DATE, p_to date DEFAULT (CURRENT_DATE + 14)) RETURNS TABLE(team_id uuid, team_name text, team_color text, scheduled_jobs integer, total_hours numeric, utilization_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT
    t.id,
    t.name,
    t.color_hex,
    COUNT(DISTINCT se.job_id)::int AS scheduled_jobs,
    ROUND(SUM(EXTRACT(EPOCH FROM (se.end_at - se.start_at)) / 3600)::numeric, 1) AS total_hours,
    -- utilization = scheduled hours / available hours
    ROUND(
      CASE WHEN avail.total_avail_hours > 0
        THEN (SUM(EXTRACT(EPOCH FROM (se.end_at - se.start_at)) / 3600) / avail.total_avail_hours * 100)::numeric
        ELSE 0
      END, 1
    ) AS utilization_pct
  FROM teams t
  LEFT JOIN schedule_events se ON se.team_id = t.id
    AND se.deleted_at IS NULL
    AND se.start_at >= p_from::timestamptz
    AND se.start_at < (p_to + 1)::timestamptz
  LEFT JOIN LATERAL (
    SELECT SUM((a.end_minute - a.start_minute) / 60.0 * (p_to - p_from + 1))::numeric AS total_avail_hours
    FROM availabilities a
    WHERE a.org_id = p_org_id AND a.team_id = t.id AND a.is_active = true
  ) avail ON TRUE
  WHERE t.org_id = p_org_id AND t.deleted_at IS NULL
  GROUP BY t.id, t.name, t.color_hex, avail.total_avail_hours;
END;
$$;


--
-- Name: rpc_unschedule_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_unschedule_job(p_job_id uuid, p_event_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_job public.jobs%rowtype;
begin
  select * into v_job from public.jobs where id = p_job_id and deleted_at is null for update;
  if v_job.id is null then raise exception 'Job not found'; end if;
  if not public.has_org_membership(auth.uid(), v_job.org_id) then raise exception 'Not allowed for this organization'; end if;

  if p_event_id is not null then
    update public.schedule_events set deleted_at = now(), updated_at = now()
    where id = p_event_id and job_id = p_job_id and deleted_at is null;
  else
    update public.schedule_events set deleted_at = now(), updated_at = now()
    where job_id = p_job_id and deleted_at is null;
  end if;

  perform public.recompute_job_schedule(p_job_id);
end;
$$;


--
-- Name: rpc_update_entity_number(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_entity_number(p_entity text, p_id uuid, p_number text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org    uuid := public.current_org_id();
  v_digits text;
  v_wanted bigint;
  v_next   bigint;
  v_stored text;
  v_count  int;
begin
  if v_org is null then
    raise exception 'No organization context';
  end if;
  if p_id is null then
    raise exception 'p_id is required' using errcode = '22023';
  end if;

  v_digits := nullif(regexp_replace(coalesce(p_number, ''), '\D', '', 'g'), '');
  if v_digits is null then
    raise exception 'Invalid number "%"', p_number using errcode = '22023';
  end if;
  v_wanted := v_digits::bigint;

  if p_entity = 'job' then
    select greatest(
      coalesce((select c.last_number from public.org_job_counters c where c.org_id = v_org), 0),
      coalesce((select max(nullif(regexp_replace(j.job_number, '\D', '', 'g'), '')::bigint)
                from public.jobs j
                where j.org_id = v_org and j.job_number ~ '\d'), 0)
    ) + 1 into v_next;

    if v_wanted > v_next then
      raise exception 'Job number % does not exist yet (next available is %)', v_wanted, v_next;
    end if;
    if exists (
      select 1 from public.jobs j
      where j.org_id = v_org and j.deleted_at is null
        and j.job_number = v_wanted::text and j.id <> p_id
    ) then
      raise exception 'Job number % is already in use', v_wanted;
    end if;

    v_stored := v_wanted::text;
    update public.jobs
    set job_number = v_stored, updated_at = now()
    where id = p_id and org_id = v_org and deleted_at is null;
    get diagnostics v_count = row_count;
    if v_count = 0 then
      raise exception 'Job not found';
    end if;

    insert into public.org_job_counters (org_id, last_number)
    values (v_org, v_wanted)
    on conflict (org_id) do update
      set last_number = greatest(public.org_job_counters.last_number, excluded.last_number),
          updated_at  = now();

  elsif p_entity = 'quote' then
    select greatest(
      coalesce((select s.last_value from public.quote_sequences s where s.org_id = v_org), 0),
      coalesce((select max(nullif(regexp_replace(q.quote_number, '\D', '', 'g'), '')::bigint)
                from public.quotes q
                where q.org_id = v_org and q.quote_number ~ '\d'), 0)
    ) + 1 into v_next;

    if v_wanted > v_next then
      raise exception 'Quote number % does not exist yet (next available is %)', v_wanted, v_next;
    end if;
    if exists (
      select 1 from public.quotes q
      where q.org_id = v_org and q.deleted_at is null
        and btrim(q.quote_number) = v_wanted::text and q.id <> p_id
    ) then
      raise exception 'Quote number % is already in use', v_wanted;
    end if;

    v_stored := v_wanted::text;
    update public.quotes
    set quote_number = v_stored, updated_at = now()
    where id = p_id and org_id = v_org and deleted_at is null;
    get diagnostics v_count = row_count;
    if v_count = 0 then
      raise exception 'Quote not found';
    end if;

    insert into public.quote_sequences (org_id, last_value, updated_at)
    values (v_org, v_wanted, now())
    on conflict (org_id) do update
      set last_value = greatest(public.quote_sequences.last_value, excluded.last_value),
          updated_at = now();

  elsif p_entity = 'invoice' then
    select greatest(
      coalesce((select s.last_value from public.invoice_sequences s where s.org_id = v_org), 0),
      coalesce((select max(nullif(regexp_replace(i.invoice_number, '\D', '', 'g'), '')::bigint)
                from public.invoices i
                where i.org_id = v_org and i.invoice_number ~ '\d'), 0)
    ) + 1 into v_next;

    if v_wanted > v_next then
      raise exception 'Invoice number % does not exist yet (next available is %)', v_wanted, v_next;
    end if;

    v_stored := v_wanted::text;

    if exists (
      select 1 from public.invoices i
      where i.org_id = v_org and i.id <> p_id
        and i.invoice_number ~ '\d'
        and nullif(regexp_replace(i.invoice_number, '\D', '', 'g'), '')::bigint = v_wanted
    ) then
      raise exception 'Invoice number % is already in use', v_stored;
    end if;

    update public.invoices
    set invoice_number = v_stored, updated_at = now()
    where id = p_id and org_id = v_org and deleted_at is null;
    get diagnostics v_count = row_count;
    if v_count = 0 then
      raise exception 'Invoice not found';
    end if;

    insert into public.invoice_sequences (org_id, last_value)
    values (v_org, v_wanted)
    on conflict (org_id) do update
      set last_value = greatest(public.invoice_sequences.last_value, excluded.last_value),
          updated_at = now();

  elsif p_entity = 'client' then
    select greatest(
      coalesce((select c.last_number from public.org_client_counters c where c.org_id = v_org), 0),
      coalesce((select max(nullif(regexp_replace(cl.client_number, '\D', '', 'g'), '')::bigint)
                from public.clients cl
                where cl.org_id = v_org and cl.client_number ~ '\d'), 0)
    ) + 1 into v_next;

    if v_wanted > v_next then
      raise exception 'Client number % does not exist yet (next available is %)', v_wanted, v_next;
    end if;
    if exists (
      select 1 from public.clients c
      where c.org_id = v_org and c.deleted_at is null
        and c.client_number = v_wanted::text and c.id <> p_id
    ) then
      raise exception 'Client number % is already in use', v_wanted;
    end if;

    v_stored := v_wanted::text;
    update public.clients
    set client_number = v_stored, updated_at = now()
    where id = p_id and org_id = v_org and deleted_at is null;
    get diagnostics v_count = row_count;
    if v_count = 0 then
      raise exception 'Client not found';
    end if;

    insert into public.org_client_counters (org_id, last_number)
    values (v_org, v_wanted)
    on conflict (org_id) do update
      set last_number = greatest(public.org_client_counters.last_number, excluded.last_number),
          updated_at  = now();

  else
    raise exception 'Unknown entity "%"', p_entity using errcode = '22023';
  end if;

  return v_stored;
end;
$$;


--
-- Name: run_invariant_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_invariant_checks() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count int := 0;
begin
  insert into public.security_events
    (org_id, event_type, severity, source, details)
  select null,                      -- invariant de plateforme, pas d'org
         'db_invariant_failure',
         case when r.failures > 10 then 'critical' else 'high' end,
         'db-cron',
         jsonb_build_object('check', r.check_name, 'failures', r.failures, 'detail', r.detail)
    from public.check_all_invariants() r
   where r.failures > 0;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: FUNCTION run_invariant_checks(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_invariant_checks() IS 'Execute check_all_invariants() et consigne toute defaillance dans security_events (org_id NULL = evenement de plateforme). A executer par cron.';


--
-- Name: run_retention_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_retention_job() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_leads bigint; v_clients bigint; v_tokens bigint; v_audit bigint; v_members bigint; v_logins bigint;
  v_org uuid;
begin
  v_leads   := public.anonymize_inactive_leads(24);
  v_clients := public.anonymize_old_soft_deleted_clients(180);
  v_tokens  := public.purge_expired_portal_tokens();
  v_audit   := public.purge_old_audit_events(1095);
  v_members := public.execute_scheduled_member_deletions();
  v_logins  := public.purge_old_failed_logins();

  -- audit_events.org_id est NOT NULL : on rattache l'unique ligne de run à une
  -- org active (au lieu d'une ligne identique par org, cf. P3-I).
  select id into v_org from public.orgs where deleted_at is null order by created_at limit 1;
  if v_org is not null then
    insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
    values (v_org, null, 'retention_run', 'system', null,
      jsonb_build_object(
        'anonymized_leads', v_leads, 'anonymized_clients', v_clients,
        'purged_portal_tokens', v_tokens, 'purged_audit_events', v_audit,
        'hard_deleted_members', v_members, 'purged_failed_logins', v_logins,
        'scope', 'platform', 'at', now()));
  end if;

  return jsonb_build_object(
    'anonymized_leads', v_leads, 'anonymized_clients', v_clients,
    'purged_portal_tokens', v_tokens, 'purged_audit_events', v_audit,
    'hard_deleted_members', v_members, 'purged_failed_logins', v_logins);
end
$$;


--
-- Name: run_retention_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_retention_logs() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v jsonb := '{}'::jsonb;
  n bigint;
  -- (table, colonne date, intervalle de rétention)
  cibles text[][] := array[
    ['automation_execution_logs', 'created_at', '90 days'],
    ['activity_log',              'created_at', '180 days'],
    ['login_history',             'created_at', '180 days'],
    ['security_events',           'created_at', '365 days'],
    ['webhook_deliveries',        'created_at', '30 days'],
    ['tracking_live_locations',   'updated_at', '7 days']
  ];
  c text[];
  total bigint;
begin
  foreach c slice 1 in array cibles loop
    total := 0;
    loop
      execute format(
        'with vieux as (select ctid from public.%I where %I < now() - interval %L order by %I limit 10000) '
        || 'delete from public.%I t using vieux where t.ctid = vieux.ctid',
        c[1], c[2], c[3], c[2], c[1]
      );
      get diagnostics n = row_count;
      total := total + n;
      exit when n < 10000;
    end loop;
    v := v || jsonb_build_object(c[1], total);
  end loop;

  -- notifications lues seulement (on garde les non-lues quel que soit l'âge)
  total := 0;
  loop
    with vieux as (
      select ctid from public.notifications
       where read_at is not null and created_at < now() - interval '90 days'
       order by created_at limit 10000
    )
    delete from public.notifications t using vieux where t.ctid = vieux.ctid;
    get diagnostics n = row_count;
    total := total + n;
    exit when n < 10000;
  end loop;
  v := v || jsonb_build_object('notifications', total);

  return v;
end $$;


--
-- Name: run_security_canary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_security_canary() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.security_canary_runs (controle, valeur)
  select 'tables_sans_rls', count(*)
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity

  union all
  select 'secdef_ouvertes_a_anon', count(*)
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.prosecdef
    and has_function_privilege('anon', p.oid, 'execute')

  union all
  select 'secdef_sans_search_path', count(*)
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.prosecdef and p.proconfig is null

  union all
  -- Le filtre sur le privilège évite un faux positif permanent : une policy
  -- sans WITH CHECK sur une table dont le GRANT a été révoqué est inerte.
  select 'update_sans_with_check', count(*)
  from pg_policies p
  join pg_class c on c.relname = p.tablename and c.relkind = 'r'
  join pg_namespace n on n.oid = c.relnamespace and n.nspname = 'public'
  where p.schemaname = 'public' and p.cmd in ('UPDATE','ALL')
    and ('authenticated' = any(p.roles) or 'public' = any(p.roles))
    and p.with_check is null
    and has_table_privilege('authenticated', c.oid, 'update')

  union all
  select 'control_plane_ecrivable', count(*)
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind = 'r'
    and c.relname in ('plans','api_keys','audit_events','security_incidents',
      'rate_limits','ip_blocklist','payment_provider_secrets','invoice_sequences',
      'promo_codes','webhook_events','subscriptions','consents','org_features',
      'integration_oauth_states','payments','tax_configs')
    and (has_table_privilege('authenticated', c.oid, 'insert')
      or has_table_privilege('authenticated', c.oid, 'update')
      or has_table_privilege('authenticated', c.oid, 'delete'))

  union all
  select 'secrets_oauth_lisibles', count(*)
  from pg_attribute a
  where a.attrelid = 'public.app_connections'::regclass and not a.attisdropped
    and a.attname in ('encrypted_access_token','encrypted_refresh_token',
                      'encrypted_credentials','credentials')
    and has_column_privilege('authenticated', 'public.app_connections',
                             a.attname, 'select')

  union all
  select 'vues_sans_security_invoker', count(*)
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind = 'v'
    and has_table_privilege('authenticated', c.oid, 'select')
    and not exists (
      select 1 from unnest(coalesce(c.reloptions, array[]::text[])) o
      where lower(o) in ('security_invoker=true','security_invoker=on'))

  union all
  -- > 0 signifie qu'un mélange entre organisations a DÉJÀ eu lieu en base.
  select 'references_croisees_orgs',
    (select count(*) from public.jobs j
       join public.clients c on c.id = j.client_id where c.org_id <> j.org_id)
  + (select count(*) from public.invoices i
       join public.jobs j on j.id = i.job_id where j.org_id <> i.org_id)

  union all
  select 'version_ecrivable', count(*)
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname in ('jobs','quotes','invoices')
    and has_column_privilege('authenticated', c.oid, 'version', 'update');

  delete from public.security_canary_runs where ran_at < now() - interval '90 days';
end $$;


--
-- Name: same_company_orgs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.same_company_orgs(p_user uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct o2.id
  from public.memberships m
  join public.orgs o1 on o1.id = m.org_id
  join public.orgs o2 on o2.company_group_id = o1.company_group_id
  where m.user_id = p_user
    and m.status = 'active';
$$;


--
-- Name: sanitize_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sanitize_text(p_input text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT regexp_replace(
    regexp_replace(
      regexp_replace(COALESCE(p_input, ''), '<script[^>]*>.*?</script>', '', 'gi'),
      '<[^>]+on\w+=', '<', 'gi'
    ),
    'javascript:', '', 'gi'
  );
$$;


--
-- Name: FUNCTION sanitize_text(p_input text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sanitize_text(p_input text) IS 'Strip potentially dangerous HTML/JS from text input';


--
-- Name: save_note_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_note_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.content is distinct from new.content then
    insert into public.note_history (note_id, old_content, new_content, edited_by)
    values (old.id, old.content, new.content, auth.uid());
  end if;
  return new;
end;
$$;


--
-- Name: schedule_events_apply_job_team_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_events_apply_job_team_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job_team_id uuid;
begin
  if new.team_id is not null then
    return new;
  end if;

  select j.team_id
    into v_job_team_id
  from public.jobs j
  where j.id = new.job_id
    and j.org_id = new.org_id
    and j.deleted_at is null
  limit 1;

  if v_job_team_id is not null then
    new.team_id := v_job_team_id;
  end if;

  return new;
end;
$$;


--
-- Name: schedule_events_sync_time_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_events_sync_time_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.start_at is null and new.start_time is not null then
    new.start_at := new.start_time;
  end if;
  if new.end_at is null and new.end_time is not null then
    new.end_at := new.end_time;
  end if;
  if new.start_time is null and new.start_at is not null then
    new.start_time := new.start_at;
  end if;
  if new.end_time is null and new.end_at is not null then
    new.end_time := new.end_at;
  end if;
  return new;
end;
$$;


--
-- Name: search_global(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_global(p_org uuid, p_q text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(entity_type text, entity_id uuid, title text, subtitle text, extra_status text, extra_amount_cents bigint, extra_currency text, extra_date timestamp with time zone, extra_client_id uuid, extra_client_name text, created_at timestamp with time zone, rank integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with q as (
    select '%' || p_q || '%' as pat
  ),

  -- Chiffres seuls de la requete : « (514) 555-1234 » → « 5145551234 ».
  -- Seuil de 4 chiffres pour eviter que « 2 » ou « 514 » matche tout le monde.
  qd as (
    select regexp_replace(p_q, '\D', '', 'g') as digits
  ),

  -- Clients (status = 'active' or 'inactive')
  client_hits as (
    select
      'client'::text                                       as entity_type,
      c.id                                                 as entity_id,
      coalesce(c.first_name || ' ' || c.last_name,
               c.company,
               'Unnamed Client')                           as title,
      coalesce(c.email, c.phone, '')                       as subtitle,
      c.status::text                                       as extra_status,
      null::bigint                                         as extra_amount_cents,
      null::text                                           as extra_currency,
      null::timestamptz                                    as extra_date,
      null::uuid                                           as extra_client_id,
      null::text                                           as extra_client_name,
      c.created_at,
      case
        when (c.first_name || ' ' || c.last_name) ilike (select pat from q) then 1
        when c.company ilike (select pat from q) then 2
        when c.email   ilike (select pat from q) then 3
        when c.phone   ilike (select pat from q) then 4
        when length((select digits from qd)) >= 4
             and regexp_replace(coalesce(c.phone, ''), '\D', '', 'g') like '%' || (select digits from qd) || '%' then 4
        else 5
      end                                                  as rank
    from public.clients c
    where c.org_id = p_org
      and c.deleted_at is null
      and c.status <> 'lead'
      and (
           (c.first_name || ' ' || c.last_name) ilike (select pat from q)
        or c.company ilike (select pat from q)
        or c.email   ilike (select pat from q)
        or c.phone   ilike (select pat from q)
        or c.address ilike (select pat from q)
        or (
          length((select digits from qd)) >= 4
          and (
            regexp_replace(coalesce(c.phone, ''), '\D', '', 'g') like '%' || (select digits from qd) || '%'
            or exists (
              select 1
              from jsonb_array_elements(coalesce(c.phones, '[]'::jsonb)) ph
              where regexp_replace(coalesce(ph->>'number', ''), '\D', '', 'g') like '%' || (select digits from qd) || '%'
            )
          )
        )
      )
  ),

  -- Leads (clients with status = 'lead')
  lead_hits as (
    select
      'lead'::text                                         as entity_type,
      c.id                                                 as entity_id,
      coalesce(c.first_name || ' ' || c.last_name,
               c.company,
               'Unnamed Lead')                             as title,
      coalesce(c.email, c.phone, '')                       as subtitle,
      c.status::text                                       as extra_status,
      null::bigint                                         as extra_amount_cents,
      null::text                                           as extra_currency,
      null::timestamptz                                    as extra_date,
      null::uuid                                           as extra_client_id,
      null::text                                           as extra_client_name,
      c.created_at,
      case
        when (c.first_name || ' ' || c.last_name) ilike (select pat from q) then 1
        when c.company ilike (select pat from q) then 2
        when c.email   ilike (select pat from q) then 3
        when c.phone   ilike (select pat from q) then 4
        when length((select digits from qd)) >= 4
             and regexp_replace(coalesce(c.phone, ''), '\D', '', 'g') like '%' || (select digits from qd) || '%' then 4
        else 5
      end                                                  as rank
    from public.clients c
    where c.org_id = p_org
      and c.deleted_at is null
      and c.status = 'lead'
      and (
           (c.first_name || ' ' || c.last_name) ilike (select pat from q)
        or c.company ilike (select pat from q)
        or c.email   ilike (select pat from q)
        or c.phone   ilike (select pat from q)
        or c.address ilike (select pat from q)
        or (
          length((select digits from qd)) >= 4
          and (
            regexp_replace(coalesce(c.phone, ''), '\D', '', 'g') like '%' || (select digits from qd) || '%'
            or exists (
              select 1
              from jsonb_array_elements(coalesce(c.phones, '[]'::jsonb)) ph
              where regexp_replace(coalesce(ph->>'number', ''), '\D', '', 'g') like '%' || (select digits from qd) || '%'
            )
          )
        )
      )
  ),

  -- Jobs
  job_hits as (
    select
      'job'::text                                          as entity_type,
      j.id                                                 as entity_id,
      j.title                                              as title,
      coalesce(j.job_number, '')                            as subtitle,
      j.status::text                                       as extra_status,
      j.total_cents::bigint                                as extra_amount_cents,
      j.currency                                           as extra_currency,
      j.scheduled_at                                       as extra_date,
      j.client_id                                          as extra_client_id,
      j.client_name                                        as extra_client_name,
      j.created_at,
      case
        when j.title      ilike (select pat from q) then 1
        when j.job_number  ilike (select pat from q) then 2
        when j.client_name ilike (select pat from q) then 3
        when j.description ilike (select pat from q) then 4
        else 5
      end                                                  as rank
    from public.jobs j
    where j.org_id = p_org
      and j.deleted_at is null
      and (
           j.title       ilike (select pat from q)
        or j.job_number   ilike (select pat from q)
        or j.client_name  ilike (select pat from q)
        or j.description  ilike (select pat from q)
      )
  ),

  -- Quotes
  quote_hits as (
    select
      'quote'::text                                        as entity_type,
      qu.id                                                as entity_id,
      qu.title                                             as title,
      coalesce(qu.quote_number, '')                         as subtitle,
      qu.status::text                                      as extra_status,
      qu.total_cents::bigint                               as extra_amount_cents,
      qu.currency                                          as extra_currency,
      qu.valid_until::timestamptz                             as extra_date,
      qu.client_id                                         as extra_client_id,
      null::text                                           as extra_client_name,
      qu.created_at,
      case
        when qu.title        ilike (select pat from q) then 1
        when qu.quote_number ilike (select pat from q) then 2
        when qu.notes        ilike (select pat from q) then 3
        else 5
      end                                                  as rank
    from public.quotes qu
    where qu.org_id = p_org
      and qu.deleted_at is null
      and (
           qu.title        ilike (select pat from q)
        or qu.quote_number ilike (select pat from q)
        or qu.notes        ilike (select pat from q)
      )
  ),

  -- Invoices
  invoice_hits as (
    select
      'invoice'::text                                      as entity_type,
      inv.id                                               as entity_id,
      coalesce(inv.subject, 'Invoice ' || inv.invoice_number) as title,
      coalesce(inv.invoice_number, '')                      as subtitle,
      inv.status::text                                     as extra_status,
      inv.total_cents::bigint                              as extra_amount_cents,
      inv.currency                                         as extra_currency,
      inv.due_date::timestamptz                              as extra_date,
      inv.client_id                                        as extra_client_id,
      null::text                                           as extra_client_name,
      inv.created_at,
      case
        when inv.subject        ilike (select pat from q) then 1
        when inv.invoice_number ilike (select pat from q) then 2
        when inv.notes          ilike (select pat from q) then 3
        else 5
      end                                                  as rank
    from public.invoices inv
    where inv.org_id = p_org
      and inv.deleted_at is null
      and (
           inv.subject        ilike (select pat from q)
        or inv.invoice_number ilike (select pat from q)
        or inv.notes          ilike (select pat from q)
      )
  ),

  -- Union all results
  combined as (
    select * from client_hits
    union all
    select * from lead_hits
    union all
    select * from job_hits
    union all
    select * from quote_hits
    union all
    select * from invoice_hits
  )

  select * from combined
  order by rank asc, created_at desc
  limit p_limit
  offset p_offset;
$$;


--
-- Name: search_global_by_type(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_global_by_type(p_org uuid, p_q text, p_entity_type text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(entity_type text, entity_id uuid, title text, subtitle text, extra_status text, extra_amount_cents integer, extra_currency text, extra_date text, extra_client_id uuid, extra_client_name text, created_at timestamp with time zone, rank double precision)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select
    s.entity_type,
    s.entity_id,
    s.title,
    s.subtitle,
    s.extra_status,
    s.extra_amount_cents,
    s.extra_currency,
    s.extra_date,
    s.extra_client_id,
    s.extra_client_name,
    s.created_at,
    s.rank
  from public.search_global_source(p_org, p_q) s
  where s.entity_type = lower(trim(coalesce(p_entity_type, '')))
  order by s.rank desc nulls last, s.created_at desc
  limit greatest(1, least(coalesce(p_limit, 20), 200))
  offset greatest(coalesce(p_offset, 0), 0);
$$;


--
-- Name: search_global_counts(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_global_counts(p_org uuid, p_q text) RETURNS TABLE(entity_type text, total bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select s.entity_type, count(*)::bigint as total
  from public.search_global_source(p_org, p_q) s
  group by s.entity_type;
$$;


--
-- Name: search_global_source(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_global_source(p_org uuid, p_q text) RETURNS TABLE(entity_type text, entity_id uuid, title text, subtitle text, extra_status text, extra_amount_cents integer, extra_currency text, extra_date text, extra_client_id uuid, extra_client_name text, created_at timestamp with time zone, rank double precision)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  with args as (
    select p_org as org_id, trim(coalesce(p_q, '')) as raw_q, lower(trim(coalesce(p_q, ''))) as q,
      public.normalize_phone_digits(p_q) as q_digits, auth.uid() as user_id
  ),
  guard as (
    select 1 as ok from args a
    where a.raw_q <> '' and a.org_id is not null
  ),
  query_terms as (
    select a.q, a.q_digits, ('%' || a.q || '%')::text as pattern,
      plainto_tsquery('simple', a.q) as tsq,
      case when length(a.q_digits) >= 4 then ('%' || a.q_digits || '%')::text else null end as phone_pattern
    from args a join guard g on true
  ),
  clients_ranked as (
    select 'client'::text as entity_type, c.id as entity_id,
      coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), nullif(c.company, ''), 'Client') as title,
      coalesce(nullif(c.company, ''), nullif(c.email, ''), nullif(c.phone, ''), nullif(c.address, ''), 'Client') as subtitle,
      c.status as extra_status, null::integer as extra_amount_cents, null::text as extra_currency,
      null::text as extra_date, null::uuid as extra_client_id, null::text as extra_client_name, c.created_at,
      (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', c.first_name, c.last_name, c.company, c.email, c.phone, c.address))), qt.tsq) * 2.0
        + greatest(
            similarity(lower(concat_ws(' ', c.first_name, c.last_name, c.company)), qt.q),
            similarity(lower(coalesce(c.email, '')), qt.q),
            similarity(lower(coalesce(c.phone, '')), qt.q),
            similarity(lower(coalesce(c.address, '')), qt.q),
            case when qt.phone_pattern is not null and public.normalize_phone_digits(c.phone) like qt.phone_pattern then 0.9 else 0.0 end
          ))::double precision as rank
    from public.clients c join query_terms qt on true
    where c.org_id = p_org and c.deleted_at is null
      and (
        lower(concat_ws(' ', c.first_name, c.last_name, c.company, c.email, c.phone, c.address)) ilike qt.pattern
        or similarity(lower(concat_ws(' ', c.first_name, c.last_name, c.company, c.email, c.phone)), qt.q) > 0.12
        or to_tsvector('simple', lower(concat_ws(' ', c.first_name, c.last_name, c.company, c.email, c.phone, c.address))) @@ qt.tsq
        or (qt.phone_pattern is not null and public.normalize_phone_digits(c.phone) like qt.phone_pattern)
      )
  ),
  jobs_ranked as (
    select 'job'::text as entity_type, j.id as entity_id,
      coalesce(nullif(j.title, ''), nullif(j.job_number, ''), 'Job') as title,
      coalesce(nullif(j.client_name, ''), nullif(j.property_address, ''), nullif(j.status, ''), nullif(j.job_number, ''), 'Job') as subtitle,
      j.status as extra_status, j.total_cents as extra_amount_cents, j.currency as extra_currency,
      j.scheduled_at::text as extra_date, j.client_id as extra_client_id, j.client_name as extra_client_name, j.created_at,
      (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', j.title, j.job_number, j.client_name, j.property_address, j.notes, j.status))), qt.tsq) * 2.0
        + greatest(similarity(lower(coalesce(j.title, '')), qt.q), similarity(lower(coalesce(j.client_name, '')), qt.q), similarity(lower(coalesce(j.property_address, '')), qt.q)))::double precision as rank
    from public.jobs j join query_terms qt on true
    where j.org_id = p_org and j.deleted_at is null
      and (
        lower(concat_ws(' ', j.title, j.job_number, j.client_name, j.property_address, j.notes, j.status)) ilike qt.pattern
        or similarity(lower(concat_ws(' ', j.title, j.job_number, j.client_name, j.property_address, j.notes)), qt.q) > 0.12
        or to_tsvector('simple', lower(concat_ws(' ', j.title, j.job_number, j.client_name, j.property_address, j.notes, j.status))) @@ qt.tsq
      )
  ),
  lead_candidates as (
    select l.id as entity_id,
      coalesce(nullif(pd.title, ''), nullif(trim(concat_ws(' ', l.first_name, l.last_name)), ''), 'Lead') as title,
      coalesce(nullif(pd.stage, ''), nullif(l.phone, ''), nullif(l.email, ''), 'Lead') as subtitle,
      l.lead_status as extra_status, pd.value::integer as extra_amount_cents, null::text as extra_currency,
      null::text as extra_date, null::uuid as extra_client_id, null::text as extra_client_name,
      coalesce(pd.created_at, l.created_at) as created_at,
      (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', pd.title, pd.notes, pd.stage, l.first_name, l.last_name, l.company, l.title, l.email, l.phone))), qt.tsq) * 2.0
        + greatest(similarity(lower(coalesce(pd.title, '')), qt.q), similarity(lower(concat_ws(' ', l.first_name, l.last_name)), qt.q), similarity(lower(coalesce(l.email, '')), qt.q)))::double precision as rank,
      row_number() over (
        partition by l.id
        order by (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', pd.title, pd.notes, pd.stage, l.first_name, l.last_name, l.company, l.title, l.email, l.phone))), qt.tsq) * 2.0
          + greatest(similarity(lower(coalesce(pd.title, '')), qt.q), similarity(lower(concat_ws(' ', l.first_name, l.last_name)), qt.q), similarity(lower(coalesce(l.email, '')), qt.q))) desc,
          coalesce(pd.created_at, l.created_at) desc
      ) as rn
    from public.pipeline_deals pd
    join public.clients l on l.id = pd.lead_id and l.org_id = p_org and l.deleted_at is null and l.status = 'lead'
    join query_terms qt on true
    where pd.org_id = p_org and pd.deleted_at is null
      and (
        lower(concat_ws(' ', pd.title, pd.notes, pd.stage, l.first_name, l.last_name, l.company, l.title, l.email, l.phone)) ilike qt.pattern
        or similarity(lower(concat_ws(' ', pd.title, pd.notes, pd.stage, l.first_name, l.last_name, l.company, l.title, l.email, l.phone)), qt.q) > 0.12
        or to_tsvector('simple', lower(concat_ws(' ', pd.title, pd.notes, pd.stage, l.first_name, l.last_name, l.company, l.title, l.email, l.phone))) @@ qt.tsq
      )
  ),
  leads_ranked as (
    select 'lead'::text as entity_type, lc.entity_id, lc.title, lc.subtitle, lc.extra_status,
      lc.extra_amount_cents, lc.extra_currency, lc.extra_date, lc.extra_client_id, lc.extra_client_name, lc.created_at, lc.rank
    from lead_candidates lc where lc.rn = 1
  ),
  invoices_ranked as (
    select 'invoice'::text as entity_type, i.id as entity_id,
      coalesce(nullif(i.invoice_number, ''), 'Invoice') as title,
      coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), nullif(trim(c.company), ''), coalesce(i.subject, 'Invoice')) as subtitle,
      i.status as extra_status, i.total_cents as extra_amount_cents, 'CAD'::text as extra_currency,
      i.due_date::text as extra_date, i.client_id as extra_client_id,
      coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), nullif(trim(c.company), ''), 'Unknown') as extra_client_name, i.created_at,
      (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', i.invoice_number, i.subject, c.first_name, c.last_name, c.company, c.email))), qt.tsq) * 2.0
        + greatest(similarity(lower(coalesce(i.invoice_number, '')), qt.q), similarity(lower(concat_ws(' ', c.first_name, c.last_name, c.company)), qt.q)))::double precision as rank
    from public.invoices i
    left join public.clients c on c.id = i.client_id and c.org_id = p_org
    join query_terms qt on true
    where i.org_id = p_org and i.deleted_at is null
      and (
        lower(concat_ws(' ', i.invoice_number, i.subject, c.first_name, c.last_name, c.company, c.email)) ilike qt.pattern
        or similarity(lower(concat_ws(' ', i.invoice_number, i.subject, c.first_name, c.last_name, c.company)), qt.q) > 0.12
        or to_tsvector('simple', lower(concat_ws(' ', i.invoice_number, i.subject, c.first_name, c.last_name, c.company, c.email))) @@ qt.tsq
      )
  ),
  quotes_ranked as (
    select 'quote'::text as entity_type, q2.id as entity_id,
      coalesce(nullif(q2.quote_number, ''), 'Quote') as title,
      coalesce(nullif(q2.title, ''), nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), nullif(trim(c.company), ''),
        coalesce(nullif(trim(concat_ws(' ', l.first_name, l.last_name)), ''), 'Quote')) as subtitle,
      q2.status as extra_status, q2.total_cents as extra_amount_cents, q2.currency as extra_currency,
      q2.valid_until::text as extra_date, q2.client_id as extra_client_id,
      coalesce(nullif(trim(concat_ws(' ', c.first_name, c.last_name)), ''), nullif(trim(c.company), ''),
        nullif(trim(concat_ws(' ', l.first_name, l.last_name)), ''), 'Unknown') as extra_client_name, q2.created_at,
      (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', q2.quote_number, q2.title, q2.notes, c.first_name, c.last_name, c.company, l.first_name, l.last_name))), qt.tsq) * 2.0
        + greatest(similarity(lower(coalesce(q2.quote_number, '')), qt.q), similarity(lower(coalesce(q2.title, '')), qt.q), similarity(lower(concat_ws(' ', c.first_name, c.last_name, c.company)), qt.q)))::double precision as rank
    from public.quotes q2
    left join public.clients c on c.id = q2.client_id and c.org_id = p_org
    left join public.clients l on l.id = q2.lead_id and l.org_id = p_org
    join query_terms qt on true
    where q2.org_id = p_org and q2.deleted_at is null
      and (
        lower(concat_ws(' ', q2.quote_number, q2.title, q2.notes, c.first_name, c.last_name, c.company, l.first_name, l.last_name)) ilike qt.pattern
        or similarity(lower(concat_ws(' ', q2.quote_number, q2.title, q2.notes, c.first_name, c.last_name, c.company)), qt.q) > 0.12
        or to_tsvector('simple', lower(concat_ws(' ', q2.quote_number, q2.title, q2.notes, c.first_name, c.last_name, c.company, l.first_name, l.last_name))) @@ qt.tsq
      )
  ),
  requests_ranked as (
    select 'request'::text as entity_type, fs.id as entity_id,
      coalesce(nullif(trim(concat_ws(' ', fs.first_name, fs.last_name)), ''), 'Request') as title,
      coalesce(nullif(fs.company, ''), nullif(fs.email, ''), nullif(fs.phone, ''), nullif(fs.city, ''), 'Request') as subtitle,
      null::text as extra_status, null::integer as extra_amount_cents, null::text as extra_currency,
      fs.created_at::text as extra_date, fs.client_id as extra_client_id,
      coalesce(nullif(trim(concat_ws(' ', fs.first_name, fs.last_name)), ''), 'Unknown') as extra_client_name, fs.created_at,
      (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', fs.first_name, fs.last_name, fs.company, fs.email, fs.phone, fs.street_address, fs.city, fs.notes))), qt.tsq) * 2.0
        + greatest(similarity(lower(concat_ws(' ', fs.first_name, fs.last_name, fs.company)), qt.q), similarity(lower(coalesce(fs.email, '')), qt.q), similarity(lower(coalesce(fs.phone, '')), qt.q),
            case when qt.phone_pattern is not null and public.normalize_phone_digits(fs.phone) like qt.phone_pattern then 0.9 else 0.0 end))::double precision as rank
    from public.form_submissions fs join query_terms qt on true
    where fs.org_id = p_org
      and (
        lower(concat_ws(' ', fs.first_name, fs.last_name, fs.company, fs.email, fs.phone, fs.street_address, fs.city, fs.notes)) ilike qt.pattern
        or similarity(lower(concat_ws(' ', fs.first_name, fs.last_name, fs.company, fs.email, fs.phone)), qt.q) > 0.12
        or to_tsvector('simple', lower(concat_ws(' ', fs.first_name, fs.last_name, fs.company, fs.email, fs.phone, fs.street_address, fs.city, fs.notes))) @@ qt.tsq
        or (qt.phone_pattern is not null and public.normalize_phone_digits(fs.phone) like qt.phone_pattern)
      )
  ),
  teams_ranked as (
    select 'team'::text as entity_type, t.id as entity_id, t.name as title, null::text as subtitle,
      null::text as extra_status, null::integer as extra_amount_cents, null::text as extra_currency,
      null::text as extra_date, null::uuid as extra_client_id, null::text as extra_client_name, t.created_at,
      (ts_rank_cd(to_tsvector('simple', lower(coalesce(t.name, ''))), qt.tsq) * 2.0 + similarity(lower(coalesce(t.name, '')), qt.q))::double precision as rank
    from public.teams t join query_terms qt on true
    where t.org_id = p_org and t.deleted_at is null
      and (lower(t.name) ilike qt.pattern or similarity(lower(coalesce(t.name, '')), qt.q) > 0.12 or to_tsvector('simple', lower(coalesce(t.name, ''))) @@ qt.tsq)
  ),
  events_ranked as (
    select 'event'::text as entity_type, se.id as entity_id,
      coalesce(nullif(j.title, ''), nullif(j.job_number, ''), 'Event') as title,
      coalesce(nullif(j.client_name, ''), to_char(se.start_time, 'Mon DD, YYYY HH24:MI')) as subtitle,
      j.status as extra_status, null::integer as extra_amount_cents, null::text as extra_currency,
      se.start_time::text as extra_date, j.client_id as extra_client_id, j.client_name as extra_client_name, se.created_at,
      (ts_rank_cd(to_tsvector('simple', lower(concat_ws(' ', j.title, j.job_number, j.client_name))), qt.tsq) * 2.0
        + greatest(similarity(lower(coalesce(j.title, '')), qt.q), similarity(lower(coalesce(j.client_name, '')), qt.q)))::double precision as rank
    from public.schedule_events se
    join public.jobs j on j.id = se.job_id and j.org_id = p_org
    join query_terms qt on true
    where se.org_id = p_org and se.deleted_at is null
      and (
        lower(concat_ws(' ', j.title, j.job_number, j.client_name)) ilike qt.pattern
        or similarity(lower(concat_ws(' ', j.title, j.job_number, j.client_name)), qt.q) > 0.12
        or to_tsvector('simple', lower(concat_ws(' ', j.title, j.job_number, j.client_name))) @@ qt.tsq
      )
  )
  select * from clients_ranked
  union all select * from jobs_ranked
  union all select * from leads_ranked
  union all select * from invoices_ranked
  union all select * from quotes_ranked
  union all select * from requests_ranked
  union all select * from teams_ranked
  union all select * from events_ranked;
$$;


--
-- Name: security_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.security_maintenance() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM ip_blocklist WHERE expires_at IS NOT NULL AND expires_at < now();
  DELETE FROM rate_limit_buckets WHERE last_refill < now() - interval '2 hours';
  DELETE FROM security_events WHERE created_at < now() - interval '90 days' AND severity IN ('low', 'info');
  DELETE FROM login_history WHERE created_at < now() - interval '365 days';
END;
$$;


--
-- Name: FUNCTION security_maintenance(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.security_maintenance() IS 'Periodic cleanup of expired security data';


--
-- Name: seed_agreement_signed_preset(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_agreement_signed_preset(p_org_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.automation_rules
    (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  select
    o.id,
    'Contract Signed',
    'Confirm to the client that their contract is signed',
    'agreement.signed',
    '{}'::jsonb,
    0,
    '[{"type":"send_sms","config":{"body":"Merci [client_first_name]! Votre contrat avec [company_name] est signé. Votre copie : [signed_contract_link]\n[deposit_line]"}},
      {"type":"send_email","config":{"subject":"[company_name] — Contrat signé","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Merci [client_first_name],</h2><p>Votre contrat avec [company_name] est signé. Vous pouvez le consulter en tout temps ici :</p><p><a href=\"[signed_contract_link]\">[signed_contract_link]</a></p><p>[deposit_line]</p><p>À bientôt!<br/>[company_name]</p></div>"}}]'::jsonb,
    true,
    true,
    'agreement_signed'
  from public.orgs o
  where p_org_id is null or o.id = p_org_id
  -- L'index unique est PARTIEL (where preset_key is not null) : le ON CONFLICT
  -- doit répéter la même clause, sinon Postgres ne reconnaît pas l'index.
  on conflict (org_id, preset_key) where preset_key is not null do nothing;
end;
$$;


--
-- Name: seed_automation_presets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_automation_presets(p_org_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
BEGIN

  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  --  QUOTE FOLLOW-UPS (5)
  -- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 1 Day', 'Friendly follow-up 1 day after quote sent', 'quote.sent', '{}'::jsonb, 86400,
    '[{"type":"send_sms","config":{"body":"Hi [client_first_name], just following up on the quote we sent yesterday. Have you had a chance to review it? Let us know if you have any questions! — [company_name]"}},
      {"type":"send_email","config":{"subject":"[company_name] — Following up on your quote","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>We sent you a quote yesterday and wanted to make sure you received it.</p><p>If you have any questions or would like to discuss the details, we''re happy to help.</p><p>Best regards,<br/>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_1d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 3 Days', 'Gentle reminder 3 days after quote sent', 'quote.sent', '{}'::jsonb, 259200,
    '[{"type":"send_sms","config":{"body":"Hi [client_first_name], we wanted to check in about the quote we sent a few days ago. — [company_name]"}},
      {"type":"send_email","config":{"subject":"[company_name] — Still interested in our quote?","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>We sent you a quote a few days ago and haven''t heard back yet.</p><p>We''re here if you have any questions.</p><p>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_3d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 7 Days', 'Follow-up 7 days after quote sent', 'quote.sent', '{}'::jsonb, 604800,
    '[{"type":"send_email","config":{"subject":"[company_name] — Your quote is still available","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>Your quote is still available. Let us know if you''d like to move forward!</p><p>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_7d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Quote Follow-Up — 14 Days', 'Last chance follow-up 14 days after quote sent', 'quote.sent', '{}'::jsonb, 1209600,
    '[{"type":"send_email","config":{"subject":"[company_name] — Last follow-up on your quote","body":"<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px;\"><h2>Hi [client_first_name],</h2><p>We wanted to reach out one last time about the quote we sent two weeks ago.</p><p>If now isn''t the right time, no worries — we''re here whenever you''re ready.</p><p>[company_name]</p></div>"}}]'::jsonb,
    true, true, 'quote_followup_14d')
  ON CONFLICT (org_id, preset_key) WHERE preset_key IS NOT NULL DO NOTHING;

  INSERT INTO public.automation_rules (org_id, name, description, trigger_event, conditions, delay_seconds, actions, is_active, is_preset, preset_key)
  VALUES (p_org_id, 'Estimate Follow-Up (3 days)', 'Follow-up 3 days after estimate sent', 'estimate.sent', '{}'::jsonb, 259200,
