--
-- Name: settle_ai_budget(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_ai_budget(p_reservation uuid, p_cost numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r public.ai_reservations%rowtype;
begin
  select * into r from public.ai_reservations where id = p_reservation and settled_at is null for update;
  if not found then return; end if;   -- déjà réglée ou expirée : idempotent
  update public.ai_reservations set settled_at = now() where id = r.id;
  update public.ai_usage_monthly
     set reserved_cents = greatest(0, reserved_cents - r.cents),
         spent_cents = spent_cents + coalesce(p_cost, 0),
         spent_proactive_cents = spent_proactive_cents + case when r.is_proactive then coalesce(p_cost, 0) else 0 end,
         updated_at = now()
   where org_id = r.org_id and period = r.period;
end;
$$;


--
-- Name: soft_delete_client(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_client(p_org_id uuid, p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
  v_now timestamptz := now();
  v_client integer := 0;
  v_jobs integer := 0;
  v_pipeline_deals integer := 0;
  v_deals_ventes integer := 0;
begin
  if v_uid = '00000000-0000-0000-0000-000000000000'::uuid then
    null;
  elsif not public.has_org_admin_role(v_uid, p_org_id) then
    raise exception 'Only owner/admin can delete clients' using errcode = '42501';
  end if;

  update public.clients
  set deleted_at = v_now, updated_at = v_now
  where id = p_client_id and org_id = p_org_id and deleted_at is null;
  get diagnostics v_client = row_count;

  update public.jobs
  set deleted_at = v_now, updated_at = v_now
  where client_id = p_client_id and org_id = p_org_id and deleted_at is null;
  get diagnostics v_jobs = row_count;

  update public.pipeline_deals
  set deleted_at = v_now, updated_at = v_now
  where client_id = p_client_id and org_id = p_org_id and deleted_at is null;
  get diagnostics v_pipeline_deals = row_count;

  -- Le pipeline de ventes. Le trigger ci-dessus l'aurait déjà fait, mais on
  -- ne s'appuie pas dessus : le décompte doit être juste même si quelqu'un
  -- désactive le trigger, et `row_count` vaudra simplement 0 si c'est déjà
  -- fait.
  update public.deals
  set deleted_at = v_now, updated_at = v_now
  where client_id = p_client_id and org_id = p_org_id and deleted_at is null;
  get diagnostics v_deals_ventes = row_count;

  return jsonb_build_object(
    'client', v_client,
    'jobs', v_jobs,
    'leads', 0,
    -- Les deux pipelines réunis : l'appelant veut savoir combien de cartes
    -- ont disparu, pas dans quelle table elles vivaient.
    'pipeline_deals', v_pipeline_deals + v_deals_ventes,
    'other_rows', 0
  );
end;
$$;


--
-- Name: FUNCTION soft_delete_client(p_org_id uuid, p_client_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.soft_delete_client(p_org_id uuid, p_client_id uuid) IS 'Soft-delete d''un client et de ce qui en dépend : jobs, deals du porte-à-porte ET deals de la page /ventes. Réservé aux propriétaires et administrateurs.';


--
-- Name: soft_delete_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_job(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_job int := 0;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT EXISTS (SELECT 1 FROM memberships WHERE user_id = auth.uid() AND org_id = p_org_id
                                             AND coalesce(status, 'active') = 'active') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE jobs SET deleted_at = v_now, updated_at = v_now
  WHERE id = p_job_id AND org_id = p_org_id AND deleted_at IS NULL;
  GET DIAGNOSTICS v_job = ROW_COUNT;

  RETURN jsonb_build_object('job', v_job);
END;
$$;


--
-- Name: sync_auth_telemetry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_auth_telemetry() RETURNS TABLE(nouvelles_connexions integer, sessions_suivies integer, sessions_expirees integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_new int := 0;
  v_tracked int := 0;
  v_expired int := 0;
begin
  -- 1a. Historique des connexions : une ligne par session jamais enregistree.
  -- org_id est NOT NULL : on rattache l'utilisateur a son organisation. Les
  -- utilisateurs sans aucune adhesion sont ignores (on ne peut pas inventer
  -- une org, et une session sans tenant n'a pas de sens ici).
  with candidat as (
    select s.id, s.user_id, s.created_at, s.ip, s.user_agent, s.aal::text as aal,
           (select m.org_id from public.memberships m
             where m.user_id = s.user_id order by m.created_at limit 1) as org_id
      from auth.sessions s
  ), insere as (
    insert into public.login_history
      (user_id, org_id, ip_address, user_agent, login_method, success, session_id, created_at)
    select c.user_id, c.org_id, c.ip, c.user_agent,
           'supabase_auth' || case when c.aal = 'aal2' then '+mfa' else '' end,
           true, c.id::text, c.created_at
      from candidat c
     where c.org_id is not null
       and not exists (select 1 from public.login_history lh where lh.session_id = c.id::text)
    returning 1
  )
  select count(*)::int into v_new from insere;

  -- 1b. Sessions actives : miroir de auth.sessions.
  with candidat as (
    select s.id, s.user_id, s.ip, s.user_agent,
           coalesce(s.refreshed_at at time zone 'UTC', s.updated_at, s.created_at) as last_act,
           (s.not_after is null or s.not_after > now()) as encore_valide,
           encode(sha256(s.id::text::bytea), 'hex') as jeton_hash,
           (select m.org_id from public.memberships m
             where m.user_id = s.user_id order by m.created_at limit 1) as org_id
      from auth.sessions s
  ), insere as (
    insert into public.active_sessions
      (user_id, org_id, session_token_hash, ip_address, user_agent, last_activity, is_valid)
    select c.user_id, c.org_id, c.jeton_hash, c.ip, c.user_agent, c.last_act, c.encore_valide
      from candidat c
     where c.org_id is not null
       and not exists (select 1 from public.active_sessions a where a.session_token_hash = c.jeton_hash)
    returning 1
  )
  select count(*)::int into v_tracked from insere;

  -- 1c. Sessions disparues de auth.sessions = revoquees ou expirees.
  update public.active_sessions a
     set is_valid = false,
         invalidated_reason = coalesce(a.invalidated_reason, 'session absente de auth.sessions')
   where a.is_valid is distinct from false
     and not exists (
       select 1 from auth.sessions s
        where encode(sha256(s.id::text::bytea), 'hex') = a.session_token_hash);
  get diagnostics v_expired = row_count;

  return query select v_new, v_tracked, v_expired;
end;
$$;


--
-- Name: FUNCTION sync_auth_telemetry(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_auth_telemetry() IS 'Alimente login_history et active_sessions depuis auth.sessions. Ne capture QUE les connexions reussies : une tentative echouee ne cree pas de session.';


--
-- Name: sync_client_status_from_jobs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_client_status_from_jobs(p_client_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target text;
begin
  if p_client_id is null then
    return;
  end if;

  -- Un client avec au moins un job vivant est « actif », sinon « prospect ».
  -- Les clients archivés à la main (« inactive ») ne sont jamais réactivés
  -- automatiquement : c'est une décision humaine.
  select case
           when exists (
             select 1 from public.jobs j
              where j.client_id = p_client_id and j.deleted_at is null
           ) then 'active'
           else 'lead'
         end
    into v_target;

  update public.clients
     set status = v_target
   where id = p_client_id
     and status is distinct from v_target
     and status <> 'inactive';
end;
$$;


--
-- Name: sync_field_pin_from_client(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_field_pin_from_client() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pin_status text;
  v_pin_color  text;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status
     AND NEW.lead_status IS NOT DISTINCT FROM OLD.lead_status THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'active' THEN
    -- ≥1 job assignée (trigger trg_jobs_sync_client_status) → Vendu
    v_pin_status := 'sale';
  ELSIF NEW.status = 'lead' THEN
    -- Lead → pin Lead, peu importe lead_status (une quote envoyée/refusée ne
    -- change jamais le pin ; seule une job le fait passer à 'sale').
    v_pin_status := 'lead';
  ELSE
    -- Archivé / inconnu : pin intact
    RETURN NEW;
  END IF;

  v_pin_color := CASE v_pin_status
    WHEN 'sale' THEN '#22c55e'
    ELSE '#A855F7'  -- lead → mauve
  END;

  UPDATE public.field_house_profiles fhp
  SET current_status = v_pin_status, last_activity_at = now(), updated_at = now()
  WHERE fhp.org_id = NEW.org_id
    AND fhp.deleted_at IS NULL
    AND (fhp.client_id = NEW.id OR fhp.lead_id = NEW.id)
    -- Priorité Vendu : on ne rétrograde jamais vers 'lead' tant qu'UN client
    -- lié à la maison est encore actif (≥1 job). Si plus aucun client lié
    -- n'est actif (job supprimée → retour lead), la rétrogradation est légitime.
    AND (
      v_pin_status = 'sale'
      OR NOT EXISTS (
        SELECT 1 FROM public.clients cx
        WHERE cx.id IN (fhp.client_id, fhp.lead_id)
          AND cx.deleted_at IS NULL
          AND cx.status = 'active'
      )
    );

  UPDATE public.field_pins fp
  SET status = v_pin_status, pin_color = v_pin_color, updated_at = now()
  FROM public.field_house_profiles fhp
  WHERE fp.house_id = fhp.id
    AND fhp.org_id = NEW.org_id
    AND fhp.deleted_at IS NULL
    AND fhp.current_status = v_pin_status
    AND (fhp.client_id = NEW.id OR fhp.lead_id = NEW.id);

  RETURN NEW;
END;
$$;


--
-- Name: sync_job_leaderboard_deal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_job_leaderboard_deal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_deal_id uuid;
  v_value numeric;
  v_value_cents integer;
  v_won_at timestamptz;
begin
  -- Job supprimé, sans vendeur, ou retiré du leaderboard : on retire le deal
  -- créé par ce trigger (source = 'job'). Les deals d'un autre flux (d2d,
  -- manuel) ne sont jamais supprimés ici.
  if new.deleted_at is not null
     or new.salesperson_id is null
     or new.show_on_leaderboard is distinct from true then
    update pipeline_deals
       set deleted_at = now(), updated_at = now()
     where job_id = new.id
       and source = 'job'
       and deleted_at is null;
    return new;
  end if;

  v_value_cents := coalesce(
    new.total_cents,
    round(coalesce(new.total, new.total_amount, 0) * 100)::integer,
    0
  );
  v_value := v_value_cents / 100.0;

  -- La « journée » du leaderboard est calculée en heure serveur (UTC).
  -- sale_date = aujourd'hui → won_at = now() (comportement normal).
  -- sale_date antidatée → midi UTC de cette journée, pour tomber dans le bon
  -- créneau daily/weekly/monthly sans effet de bord de timezone.
  v_won_at := case
    when new.sale_date is null or new.sale_date = (now() at time zone 'utc')::date
      then now()
    else (new.sale_date::timestamp + interval '12 hours') at time zone 'utc'
  end;

  -- 3a. Deal déjà lié à ce job : resynchroniser (vendeur, date, montant).
  select id into v_deal_id
  from pipeline_deals
  where job_id = new.id
  order by created_at asc
  limit 1;

  if v_deal_id is not null then
    update pipeline_deals
       set rep_id = new.salesperson_id,
           stage = 'closed_won',
           won_at = v_won_at,
           value = case when source = 'job' then v_value else greatest(coalesce(value, 0), v_value) end,
           value_cents = case when source = 'job' then v_value_cents else greatest(coalesce(value_cents, 0), v_value_cents) end,
           title = coalesce(nullif(title, ''), new.title, 'Job'),
           -- Un deal 'job' masqué puis ré-affiché est restauré.
           deleted_at = case when source = 'job' then null else deleted_at end,
           updated_at = now()
     where id = v_deal_id;
    return new;
  end if;

  -- 3b. Deal existant du lead (pipeline D2D) : l'avancer à closed_won et le
  -- lier au job — pas de doublon sur le leaderboard.
  if new.lead_id is not null then
    select id into v_deal_id
    from pipeline_deals
    where org_id = new.org_id
      and lead_id = new.lead_id
      and deleted_at is null
    order by created_at asc
    limit 1;

    if v_deal_id is not null then
      update pipeline_deals
         set job_id = coalesce(job_id, new.id),
             rep_id = coalesce(rep_id, new.salesperson_id),
             stage = 'closed_won',
             won_at = v_won_at,
             value = greatest(coalesce(value, 0), v_value),
             value_cents = greatest(coalesce(value_cents, 0), v_value_cents),
             title = coalesce(nullif(title, ''), new.title, 'Job'),
             updated_at = now()
       where id = v_deal_id;
      return new;
    end if;
  end if;

  -- 3c. Aucun deal : en créer un. pipeline_deals exige un client ou un lead.
  if new.client_id is null and new.lead_id is null then
    return new;
  end if;

  insert into pipeline_deals (
    org_id, lead_id, client_id, job_id, rep_id,
    stage, title, value, value_cents, currency,
    source, created_by, won_at
  ) values (
    new.org_id, new.lead_id, new.client_id, new.id, new.salesperson_id,
    'closed_won', coalesce(new.title, 'Job'), v_value, v_value_cents,
    coalesce(new.currency, 'CAD'), 'job', new.salesperson_id, v_won_at
  );

  return new;
end;
$$;


--
-- Name: sync_lead_or_client_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_lead_or_client_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_full_name text;
begin
  v_full_name := nullif(trim(coalesce(new.first_name, '') || ' ' || coalesce(new.last_name, '')), '');
  if new.contact_id is null then
    insert into public.contacts (org_id, full_name, email, phone)
    values (new.org_id, v_full_name, nullif(trim(new.email), ''), nullif(trim(new.phone), ''))
    returning id into new.contact_id;
  else
    update public.contacts
    set org_id = coalesce(new.org_id, org_id),
        full_name = coalesce(v_full_name, full_name),
        email = coalesce(nullif(trim(new.email), ''), email),
        phone = coalesce(nullif(trim(new.phone), ''), phone),
        updated_at = now()
    where id = new.contact_id;
  end if;
  return new;
end;
$$;


--
-- Name: sync_lead_stage_from_deal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_lead_stage_from_deal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stage text;
BEGIN
  IF new.lead_id IS NULL THEN
    RETURN new;
  END IF;

  -- Stage inchangé → ne pas réveiller trg_clients_sync_field_pin pour rien
  IF TG_OP = 'UPDATE' AND new.stage IS NOT DISTINCT FROM old.stage THEN
    RETURN new;
  END IF;

  v_stage := CASE lower(coalesce(new.stage, 'new_prospect'))
    -- Slugs canoniques (seuls admis par pipeline_deals_stage_check)
    WHEN 'new_prospect' THEN 'new_prospect'
    WHEN 'no_response'  THEN 'no_response'
    WHEN 'quote_sent'   THEN 'quote_sent'
    WHEN 'closed_won'   THEN 'closed_won'
    WHEN 'closed_lost'  THEN 'closed_lost'
    -- Slugs legacy (lignes d'avant 20260703200000)
    WHEN 'new'          THEN 'new_prospect'
    WHEN 'follow_up_1'  THEN 'no_response'
    WHEN 'follow_up_2'  THEN 'quote_sent'
    WHEN 'follow_up_3'  THEN 'quote_sent'
    WHEN 'closed'       THEN 'closed_won'
    WHEN 'lost'         THEN 'closed_lost'
    ELSE 'new_prospect'
  END;

  UPDATE public.clients
  SET lead_status = v_stage,
      updated_at = now()
  WHERE id = new.lead_id
    AND org_id = new.org_id
    AND deleted_at IS NULL
    AND lead_status IS DISTINCT FROM v_stage;

  RETURN new;
END;
$$;


--
-- Name: sync_legacy_money_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_legacy_money_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_table_name = 'jobs' then
    new.total_amount := round(coalesce(new.total_cents, 0) / 100.0, 2);
    new.total        := round(coalesce(new.total_cents, 0) / 100.0, 2);
    new.subtotal     := round(coalesce(new.subtotal_cents, 0) / 100.0, 2);
    new.tax_total    := round(coalesce(new.tax_cents, 0) / 100.0, 2);
  elsif tg_table_name = 'invoices' then
    new.total     := round(coalesce(new.total_cents, 0)    / 100.0, 2);
    new.subtotal  := round(coalesce(new.subtotal_cents, 0) / 100.0, 2);
    new.tax_total := round(coalesce(new.tax_cents, 0)      / 100.0, 2);
  end if;
  return new;
end $$;


--
-- Name: FUNCTION sync_legacy_money_columns(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_legacy_money_columns() IS 'N1.7 — Les colonnes numeric heritees (total, subtotal, tax_total, total_amount) sont des PROJECTIONS de *_cents, jamais des sources. A supprimer avec les colonnes, une fois tout le code bascule sur *_cents.';


--
-- Name: sync_notification_is_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_notification_is_read() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.read_at IS NOT NULL AND NEW.is_read = false THEN
    NEW.is_read := true;
  END IF;
  IF NEW.is_read = true AND NEW.read_at IS NULL THEN
    NEW.read_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_schedule_event_time_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_schedule_event_time_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.start_at IS NULL AND NEW.start_time IS NOT NULL THEN
    NEW.start_at := NEW.start_time;
  END IF;
  IF NEW.end_at IS NULL AND NEW.end_time IS NOT NULL THEN
    NEW.end_at := NEW.end_time;
  END IF;
  IF NEW.start_time IS NULL AND NEW.start_at IS NOT NULL THEN
    NEW.start_time := NEW.start_at;
  END IF;
  IF NEW.end_time IS NULL AND NEW.end_at IS NOT NULL THEN
    NEW.end_time := NEW.end_at;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_team_member_from_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_team_member_from_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_email text;
  v_nom   text;
  v_first text := '';
  v_last  text := '';
  v_role  text;
  v_status text;
begin
  if tg_op = 'DELETE' then
    update public.team_members
       set status = 'inactive', updated_at = now()
     where org_id = old.org_id and user_id = old.user_id and status <> 'inactive';
    return old;
  end if;

  if new.user_id is null then return new; end if;

  v_role := case when new.role in ('owner', 'admin', 'sales_rep', 'technician') then new.role else 'technician' end;
  v_status := case when coalesce(new.status, 'active') = 'active' then 'active' else 'inactive' end;

  -- Identité : courriel depuis auth.users, nom depuis profiles (comme
  -- get_user_id_by_email, la lecture d'auth.users passe par SECURITY DEFINER).
  select email into v_email from auth.users where id = new.user_id;
  -- Membership orphelin (utilisateur supprimé d'auth) : pas de fiche.
  if v_email is null then return new; end if;
  select full_name into v_nom from public.profiles where id = new.user_id;
  if v_nom is not null and btrim(v_nom) <> '' then
    v_first := split_part(btrim(v_nom), ' ', 1);
    v_last  := btrim(substr(btrim(v_nom), length(v_first) + 1));
  end if;

  insert into public.team_members (org_id, user_id, email, first_name, last_name, phone, role, status)
  values (new.org_id, new.user_id, coalesce(v_email, ''), v_first, v_last, '', v_role, v_status)
  on conflict (org_id, user_id) where user_id is not null
  do update set
    role   = excluded.role,
    status = excluded.status,
    email  = case when public.team_members.email = '' then excluded.email else public.team_members.email end,
    first_name = case when public.team_members.first_name = '' then excluded.first_name else public.team_members.first_name end,
    last_name  = case when public.team_members.last_name  = '' then excluded.last_name  else public.team_members.last_name  end,
    updated_at = now();
  return new;
end;
$$;


