--
-- Name: clients_active; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.clients_active WITH (security_invoker='true') AS
 SELECT id,
    org_id,
    first_name,
    last_name,
    company,
    email,
    phone,
    address,
    status,
    created_at,
    updated_at,
    deleted_at,
    contact_id,
    created_by,
    deleted_by,
    fts_vector,
    notes,
    archived_at,
    archived_by,
    portal_token,
    email_blind,
    phone_blind,
    portal_token_hash,
    portal_token_expires_at,
    portal_token_revoked_at,
    sms_consent_at,
    email_consent_at,
    email_opt_out_at,
    email_opt_out_reason,
    city,
    province,
    postal_code,
    last_client_activity_at,
    display_as_company,
    billing_same_as_service,
    billing_address,
    lead_status,
    source,
    title,
    user_id,
    assigned_to,
    assigned_team,
    value,
    tags,
    schedule,
    line_items,
    description,
    phones,
    email_label,
    lead_source,
    tax_ids,
    street_number,
    street_name,
    country,
    latitude,
    longitude,
    place_id,
    client_number
   FROM public.clients
  WHERE (deleted_at IS NULL);


