--
-- Name: jobs_active; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.jobs_active WITH (security_invoker='true') AS
 SELECT id,
    org_id,
    job_number,
    title,
    client_id,
    client_name,
    property_address,
    scheduled_at,
    status,
    total_cents,
    currency,
    job_type,
    notes,
    invoice_url,
    attachments,
    created_at,
    updated_at,
    description,
    deleted_at,
    total_amount,
    created_by,
    deal_id,
    lead_id,
    team_id,
    address,
    latitude,
    longitude,
    geocoded_at,
    geocode_status,
    deleted_by,
    end_at,
    completed_at,
    closed_at,
    start_at,
    subtotal,
    tax_lines,
    tax_total,
    total,
    billing_split,
    fts_vector,
    salesperson_id,
    requires_invoicing,
    archived_at,
    archived_by,
    deposit_required,
    deposit_type,
    deposit_value,
    deposit_cents,
    require_payment_method,
    deposit_status,
    property_id,
    tags,
    ask_for_review,
    assigned_user_id,
    expenses_cents,
    sale_date,
    show_on_leaderboard,
    version,
    subtotal_cents,
    tax_cents,
    tag_ids,
    billing_mode,
    auto_charge,
        CASE
            WHEN ((lower(COALESCE(status, ''::text)) = 'completed'::text) AND requires_invoicing) THEN 'requires_invoicing'::text
            WHEN (lower(COALESCE(status, ''::text)) = ANY (ARRAY['completed'::text, 'cancelled'::text, 'canceled'::text, 'archived'::text])) THEN 'archived'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.schedule_events se
              WHERE ((se.job_id = j.id) AND (se.deleted_at IS NULL) AND (se.start_at >= now()) AND (lower(COALESCE(se.status, ''::text)) <> 'cancelled'::text)))) THEN 'upcoming'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.schedule_events se
              WHERE ((se.job_id = j.id) AND (se.deleted_at IS NULL) AND (se.start_at < now()) AND (lower(COALESCE(se.status, ''::text)) <> ALL (ARRAY['completed'::text, 'cancelled'::text]))))) THEN 'late'::text
            ELSE 'action_required'::text
        END AS derived_status
   FROM public.jobs j
  WHERE (deleted_at IS NULL);


