--
-- Name: properties_active; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.properties_active WITH (security_invoker='on') AS
 SELECT id,
    org_id,
    client_id,
    name,
    address,
    street_number,
    street_name,
    city,
    province,
    postal_code,
    country,
    latitude,
    longitude,
    place_id,
    is_primary,
    created_by,
    created_at,
    updated_at,
    deleted_at
   FROM public.properties
  WHERE (deleted_at IS NULL);


