--
-- Name: COLUMN subscriptions.scheduled_plan_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.scheduled_plan_id IS 'Plan id the subscription will switch to at scheduled_at (downgrade end-of-period)';


--
-- Name: COLUMN subscriptions.scheduled_interval; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.scheduled_interval IS 'Billing interval after the scheduled change';


--
