-- Name: memberships memberships_bootstrap_window; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY memberships_bootstrap_window ON public.memberships AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((public.has_org_admin_role(( SELECT auth.uid() AS uid), org_id) OR public.org_is_within_bootstrap_window(org_id)));


--
-- Name: POLICY memberships_bootstrap_window ON memberships; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY memberships_bootstrap_window ON public.memberships IS 'Borne la branche bootstrap de memberships_insert_org a 24 h apres la creation de l''organisation. Mesure : le premier membre arrive en 21 min maximum. Empeche la revendication des organisations abandonnees.';


--
-- Name: memberships memberships_delete_org; Type: POLICY; Schema: public; Owner: -
--

